CREATE OR REPLACE FUNCTION ironclad_private.advance_match_communication_generation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
begin
  if row(new.player_one_registration_id, new.player_two_registration_id)
    is distinct from row(old.player_one_registration_id, old.player_two_registration_id) then
    new.communication_generation := old.communication_generation + 1;
  elsif new.communication_generation is distinct from old.communication_generation
    and new.communication_generation <> old.communication_generation + 1 then
    raise exception 'Invalid Match communication generation' using errcode = '22023';
  end if;
  if new.communication_generation is distinct from old.communication_generation then
    update public.match_rooms
    set closed_at = clock_timestamp(), closure_reason = 'lifecycle_changed'
    where match_id = old.id and closed_at is null;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION ironclad_private.guard_staging_synthetic_uat_player_record()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_expected record;
  v_provisioning boolean :=
    coalesce(
      current_setting('ironclad.staging_synthetic_uat_provisioning', true),
      ''
    ) = 'on'
    and coalesce(auth.role(), '') = 'service_role';
  v_account_closure boolean :=
    coalesce(current_setting('ironclad.account_closure', true), '') = 'on'
    and (
      session_user = 'postgres'
      or coalesce(auth.role(), '') = 'service_role'
    );
begin
  if tg_op = 'DELETE' then
    if v_account_closure then
      return old;
    end if;

    raise exception 'Synthetic fixture identity provenance is immutable'
      using errcode = '55000';
  end if;

  if not v_provisioning then
    raise exception 'Synthetic fixture identity provenance is immutable'
      using errcode = '55000';
  end if;

  if tg_op = 'UPDATE' then
    raise exception 'Synthetic fixture identity provenance is immutable'
      using errcode = '55000';
  end if;

  select definition.*
  into v_expected
  from ironclad_private.staging_synthetic_uat_alias_definition(
    new.approved_alias
  ) as definition;

  if not found
    or new.synthetic_elo is distinct from v_expected.synthetic_elo
    or new.synthetic_division is distinct from v_expected.synthetic_division
    or new.provenance is distinct from 'staging_synthetic_uat'
    or new.contract_version is distinct from 'staging-synthetic-v1'
    or new.clerk_environment is distinct from 'development'
    or new.clerk_test_user_verified is distinct from true
    or new.clerk_test_user_verified_at is null
    or new.steam_openid_verified is distinct from false
    or new.steam_ownership_verified is distinct from false
    or new.relic_live_lookup_verified is distinct from false
    or new.linked_steam_legal_confirmation is distinct from false then
    raise exception 'Synthetic fixture identity provenance is invalid'
      using errcode = '23514';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION ironclad_private.lock_match_room_case_authority()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare v_group public.match_result_report_groups%rowtype; v_closed timestamptz;
begin
  if tg_op='DELETE' then v_group:=old; else v_group:=new; end if;
  perform 1 from public.tournament_matches where id=v_group.match_id for update;
  if v_group.disputed_at is not null or v_group.result_type='no_show' or v_group.status in ('disputed','under_review') then
    if v_group.status in ('confirmed','auto_approved','approved','rejected','reset') then
      v_closed:=coalesce(v_group.finalized_at,v_group.reviewed_at);
    end if;
    -- Preserve only explicit formal-case provenance if competition maintenance
    -- resets/deletes the report. A vanished authority cannot revert evidence to
    -- routine chat. Unknown final result/closure remains fail-closed.
    insert into ironclad_private.match_room_retention_cases(room_id,case_reference,case_kind,closed_at)
    select r.id,v_group.id,case when v_group.result_type='no_show' then 'no_show' else 'dispute' end,v_closed
    from public.match_rooms r where r.match_id=v_group.match_id
      and v_group.submitted_by_registration_id in(r.player_one_registration_id,r.player_two_registration_id)
      and v_group.opponent_registration_id in(r.player_one_registration_id,r.player_two_registration_id)
    on conflict(room_id,case_reference) do update set closed_at=excluded.closed_at,updated_at=clock_timestamp();
  end if;
  if tg_op='DELETE' then return old; else return new; end if;
end $function$

CREATE OR REPLACE FUNCTION ironclad_private.lock_match_room_privacy(p_room_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare v_match uuid; v_tournament uuid;
begin
  -- Same outer lock as account closure and room callers, before match/room.
  perform pg_advisory_xact_lock(hashtextextended('ironclad:match-room-account-closure',0));
  select match_id into v_match from public.match_rooms where id=p_room_id;
  if v_match is null then raise exception 'Room unavailable' using errcode='22023'; end if;
  perform 1 from public.tournament_matches where id=v_match for update nowait;
  select b.tournament_id into v_tournament from public.tournament_matches m
    join public.generated_brackets g on g.id=m.generated_bracket_id
    join public.tournament_brackets b on b.id=g.tournament_bracket_id where m.id=v_match;
  perform 1 from public.tournaments where id=v_tournament for share nowait;
  perform 1 from public.match_rooms where id=p_room_id for update nowait;
end $function$

CREATE OR REPLACE FUNCTION ironclad_private.match_room_access(p_room_id uuid, p_sub text)
 RETURNS match_rooms
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare v_room public.match_rooms%rowtype; v_context jsonb; v_reason text;
begin
  select * into v_room from public.match_rooms where id = p_room_id;
  if not found or (coalesce(auth.jwt() -> 'metadata' ->> 'role', '') <> 'admin'
    and not exists (select 1 from public.registrations r
      where r.id in (v_room.player_one_registration_id, v_room.player_two_registration_id)
        and r.clerk_user_id = p_sub)) then
    raise exception 'Match Room unavailable' using errcode = '42501';
  end if;
  v_context := ironclad_private.match_room_context(v_room.match_id);
  select * into v_room from public.match_rooms where id = p_room_id for update;
  if v_room.closed_at is null then
    if v_context is null then v_reason := 'match_unavailable';
    elsif (v_context ->> 'generation')::bigint <> v_room.communication_generation
      or (v_context ->> 'playerOne')::uuid is distinct from v_room.player_one_registration_id
      or (v_context ->> 'playerTwo')::uuid is distinct from v_room.player_two_registration_id then
      v_reason := 'lifecycle_changed';
    elsif not (v_context ->> 'writable')::boolean then
      v_reason := v_context ->> 'closureReason';
    end if;
    if v_reason is not null then
      update public.match_rooms set closed_at = greatest(created_at,
        coalesce((v_context ->> 'closedAt')::timestamptz, clock_timestamp())), closure_reason = v_reason
      where id = p_room_id returning * into v_room;
    end if;
  end if;
  return v_room;
end;
$function$

CREATE OR REPLACE FUNCTION ironclad_private.match_room_actor()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare v_sub text := nullif(btrim(auth.jwt() ->> 'sub'), '');
begin
  if coalesce(auth.role(), '') <> 'authenticated' or v_sub is null then
    raise exception 'Match Room unavailable' using errcode = '42501';
  end if;
  perform pg_advisory_xact_lock_shared(hashtextextended('ironclad:match-room-account-closure', 0));
  perform pg_advisory_xact_lock(hashtextextended('ironclad:match-room-actor:' || v_sub, 0));
  if not exists (select 1 from public.players where clerk_user_id = v_sub and account_closed_at is null) then
    raise exception 'Match Room unavailable' using errcode = '42501';
  end if;
  return v_sub;
end;
$function$

CREATE OR REPLACE FUNCTION ironclad_private.match_room_context(p_match_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_match public.tournament_matches%rowtype;
  v_tournament_id uuid;
  v_bracket_id uuid;
  v_format text;
  v_launched_at timestamptz;
  v_status text;
  v_terminal_at timestamptz;
  v_eligible boolean;
  v_reason text;
  v_closed_at timestamptz;
begin
  select * into v_match from public.tournament_matches where id = p_match_id for update;
  if not found then return null; end if;
  select b.tournament_id, b.id, g.format, b.launched_at
  into v_tournament_id, v_bracket_id, v_format, v_launched_at
  from public.generated_brackets g join public.tournament_brackets b on b.id = g.tournament_bracket_id
  where g.id = v_match.generated_bracket_id;
  select status, terminal_at into v_status, v_terminal_at
  from public.tournaments where id = v_tournament_id for share nowait;
  v_eligible := v_launched_at is not null
    and v_match.player_one_registration_id is not null
    and v_match.player_two_registration_id is not null
    and v_match.player_one_registration_id <> v_match.player_two_registration_id
    and ((v_format = 'single_elimination' and v_match.activation_version > 0) or v_format = 'round_robin')
    and not exists (select 1 from public.tournament_division_not_held_closures where tournament_bracket_id = v_bracket_id)
    and (select count(*) = 2 from public.registrations r
      where r.id in (v_match.player_one_registration_id, v_match.player_two_registration_id)
        and r.tournament_id = v_tournament_id and r.tournament_bracket_id = v_bracket_id);
  if not coalesce(v_eligible, false) or v_match.outcome_type in ('automatic_bye', 'empty_feeder') then
    v_reason := 'match_unavailable';
  elsif v_status in ('completed', 'cancelled', 'voided') then
    v_reason := 'tournament_closed';
  elsif v_match.status = 'completed' then
    v_reason := 'match_completed';
  elsif v_status is distinct from 'in_progress'
    or v_match.status not in ('scheduled', 'in_progress', 'pending_review')
    or v_match.outcome_type is not null then
    v_reason := 'match_unavailable';
  end if;
  if v_reason is not null then
    v_closed_at := coalesce(v_terminal_at, v_match.official_result_decided_at,
      v_match.deadline_ruled_at, v_match.updated_at, clock_timestamp());
  end if;
  return jsonb_build_object(
    'generation', v_match.communication_generation, 'activation', v_match.activation_version,
    'playerOne', v_match.player_one_registration_id, 'playerTwo', v_match.player_two_registration_id,
    'eligible', coalesce(v_eligible, false), 'writable', v_reason is null,
    'closureReason', v_reason, 'closedAt', v_closed_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION ironclad_private.match_room_privacy_actor(p_actor text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare v_id uuid;
begin
  if session_user <> 'postgres' and coalesce(auth.jwt()->>'role','') <> 'service_role' then
    raise exception 'Not authorized' using errcode='42501';
  end if;
  -- Public execution is service-role-only. Trusted server/operator MUST verify
  -- the current Clerk admin claim; an actor string is not browser authority.
  select id into v_id from public.players where clerk_user_id=p_actor and account_closed_at is null;
  if v_id is null then raise exception 'Active privacy operator required' using errcode='42501'; end if;
  return v_id;
end $function$

CREATE OR REPLACE FUNCTION ironclad_private.match_room_retention_state(p_room_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare r record; a record; c record; v_closed timestamptz; v_case timestamptz;
  v_result timestamptz; v_open boolean:=false; v_formal boolean:=false; v_result_case boolean:=false;
  v_block text; v_total bigint; v_held bigint; v_eligible bigint; v_whole_hold boolean;
begin
  select room.*,t.id tournament_id,t.status terminal_status,t.terminal_at,m.status match_status,
    m.official_result_decided_at,m.deadline_ruled_at,obs.completed_at,
    m.player_one_registration_id current_player_one,m.player_two_registration_id current_player_two
  into r from public.match_rooms room
  left join public.tournament_matches m on m.id=room.match_id
  left join public.generated_brackets g on g.id=m.generated_bracket_id
  left join public.tournament_brackets b on b.id=g.tournament_bracket_id
  left join public.tournaments t on t.id=b.tournament_id
  left join ironclad_private.match_room_tournament_closures obs on obs.tournament_id=t.id
  where room.id=p_room_id;
  if not found then raise exception 'Room unavailable' using errcode='22023'; end if;
  if r.terminal_status in ('cancelled','voided') then v_closed:=r.terminal_at;
  elsif r.terminal_status='completed' then v_closed:=r.completed_at; end if;
  if r.match_status='completed' and (
    (r.current_player_one=r.player_one_registration_id and r.current_player_two=r.player_two_registration_id)
    or (r.current_player_one=r.player_two_registration_id and r.current_player_two=r.player_one_registration_id)) then
    v_result:=coalesce(r.official_result_decided_at,r.deadline_ruled_at);
  end if;
  select * into a from public.match_room_assistance where room_id=p_room_id;
  if found then
    v_formal:=true;
    if a.status <> 'resolved' or a.resolved_at is null then v_open:=true;
    else v_case:=a.resolved_at+interval '24 months'; end if;
  end if;
  if exists(select 1 from public.match_result_report_groups x where x.match_id=r.match_id
    and x.submitted_by_registration_id in (r.player_one_registration_id,r.player_two_registration_id)
    and x.opponent_registration_id in (r.player_one_registration_id,r.player_two_registration_id)
    and (x.disputed_at is not null or x.result_type='no_show' or x.status in ('disputed','under_review'))) then
    v_formal:=true; v_result_case:=true;
    if exists(select 1 from public.match_result_report_groups x where x.match_id=r.match_id
      and x.submitted_by_registration_id in (r.player_one_registration_id,r.player_two_registration_id)
      and x.opponent_registration_id in (r.player_one_registration_id,r.player_two_registration_id)
      and (x.disputed_at is not null or x.result_type='no_show' or x.status in ('disputed','under_review'))
      and x.status not in ('confirmed','auto_approved','approved','rejected','reset')) then v_open:=true; end if;
  end if;
  for c in select * from ironclad_private.match_room_retention_cases where room_id=p_room_id loop
    v_formal:=true;
    if c.closed_at is null then v_open:=true;
    elsif c.case_kind in ('dispute','no_show','competition_integrity') then v_result_case:=true;
    else v_case:=greatest(v_case,c.closed_at+interval '24 months'); end if;
  end loop;
  if v_result_case then
    if v_result is null then v_open:=true;
    else v_case:=greatest(v_case,v_result+interval '24 months'); end if;
  end if;
  if v_closed is null then v_block:='tournament_not_terminal_or_closure_unknown';
  elsif v_closed>clock_timestamp() then v_block:='closure_in_future';
  elsif v_open then v_block:='formal_case_open_or_result_not_final';
  elsif v_case>now() then v_block:='formal_case_retention';
  elsif v_closed+interval '40 days'>now() then v_block:='routine_retention'; end if;
  select count(*) into v_total from public.match_messages where room_id=p_room_id;
  select exists(select 1 from ironclad_private.match_room_retention_holds h where h.room_id=p_room_id
    and h.released_at is null and h.expires_at>now() and h.message_ids is null) into v_whole_hold;
  select count(*) into v_held from public.match_messages m where m.room_id=p_room_id and exists(
    select 1 from ironclad_private.match_room_retention_holds h where h.room_id=p_room_id
      and h.released_at is null and h.expires_at>now() and (h.message_ids is null or m.id=any(h.message_ids)));
  v_eligible:=case when v_block is null and not v_whole_hold then v_total-v_held else 0 end;
  if v_block is null and v_whole_hold then v_block:='active_room_hold'; end if;
  return jsonb_build_object('roomId',r.id,'tournamentId',r.tournament_id,'terminalStatus',r.terminal_status,
    'closedAt',v_closed,'retentionClass',case when v_formal then 'formal_case' else 'routine' end,
    'routineEligibleAt',v_closed+interval '40 days','caseEligibleAt',v_case,'blockedReason',v_block,
    'messageCount',v_total,'heldMessageCount',v_held,'eligibleMessageCount',v_eligible,
    'formalCaseBlocked',v_open or coalesce(v_case>now(),false),'contentPurgedAt',r.content_purged_at);
end $function$

CREATE OR REPLACE FUNCTION ironclad_private.protect_match_message_record()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
begin
  if row(new.id,new.room_id,new.sequence,new.sender_kind,new.sender_registration_id,new.client_message_id,new.created_at,new.author_player_id)
    is distinct from row(old.id,old.room_id,old.sequence,old.sender_kind,old.sender_registration_id,old.client_message_id,old.created_at,old.author_player_id)
    or new.actor_clerk_user_id is not null then
    raise exception 'Match Room messages are immutable' using errcode='55000';
  end if;
  if new.body is distinct from old.body then
    if current_setting('ironclad.match_room_privacy_redaction',true) is distinct from 'on'
      or new.body <> '[removed following privacy request]' then
      raise exception 'Match Room messages are immutable' using errcode='55000';
    end if;
  elsif coalesce(current_setting('ironclad.match_room_account_closure',true),'') <> 'on'
    and coalesce(current_setting('ironclad.match_room_privacy_redaction',true),'') <> 'on' then
    raise exception 'Match Room messages are immutable' using errcode='55000';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION ironclad_private.require_current_account_legal_acceptance()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_clerk_user_id text := nullif(auth.jwt() ->> 'sub', '');
  v_checked_at timestamptz := pg_catalog.clock_timestamp();
  v_document public.legal_documents%rowtype;
  v_document_count integer := 0;
  v_terms public.legal_documents%rowtype;
  v_privacy public.legal_documents%rowtype;
begin
  if coalesce(auth.role(), '') <> 'authenticated'
    or v_clerk_user_id is null then
    raise exception 'Authentication is required' using errcode = '42501';
  end if;

  -- Keep the acceptance writer's exact current-document predicates and lock
  -- order. SHARE locks keep successor activation behind this transaction.
  for v_document in
    select document.*
    from public.legal_documents as document
    where document.document_kind in ('privacy', 'terms')
      and document.status = 'effective'
      and document.published_at is not null
      and document.published_at <= v_checked_at
      and document.effective_at is not null
      and document.effective_at <= v_checked_at
      and document.sha256 is not null
    order by document.document_kind
    for share
  loop
    v_document_count := v_document_count + 1;
    if v_document.document_kind = 'terms' then
      v_terms := v_document;
    elsif v_document.document_kind = 'privacy' then
      v_privacy := v_document;
    end if;
  end loop;

  if v_document_count <> 2
    or v_terms.id is null
    or v_privacy.id is null then
    raise exception 'ACCOUNT_LEGAL_ACCEPTANCE_UNAVAILABLE'
      using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.account_legal_acceptances as acceptance
    where acceptance.clerk_user_id = v_clerk_user_id
      and acceptance.terms_document_id = v_terms.id
      and acceptance.privacy_document_id = v_privacy.id
      and acceptance.terms_accepted is true
      and acceptance.privacy_acknowledged is true
  ) then
    raise exception 'ACCOUNT_LEGAL_ACCEPTANCE_REQUIRED'
      using errcode = '42501';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION ironclad_private.send_match_room_message(p_match_id uuid, p_expected_room_id uuid, p_client_message_id uuid, p_body text, p_admin boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_sub text := ironclad_private.match_room_actor(); v_room public.match_rooms%rowtype;
  v_message public.match_messages%rowtype; v_registration_id uuid; v_now timestamptz;
  v_blank_chars constant text := U&'\0009\000A\000B\000C\000D\0020\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF';
begin
  if p_match_id is null or p_expected_room_id is null or p_client_message_id is null
    or p_body is null or char_length(p_body) not between 1 and 1000
    or btrim(p_body, v_blank_chars) = '' then
    raise exception 'Invalid Match Room message' using errcode = '22023';
  end if;
  if p_admin and coalesce(auth.jwt() -> 'metadata' ->> 'role', '') <> 'admin' then
    raise exception 'Match Room unavailable' using errcode = '42501';
  end if;
  perform ironclad_private.require_match_room_enabled();
  v_room := ironclad_private.match_room_access(p_expected_room_id, v_sub);
  if v_room.match_id <> p_match_id then
    raise exception 'Match Room unavailable' using errcode = '42501';
  end if;
  if not p_admin then
    select r.id into v_registration_id from public.registrations r
    where r.id in (v_room.player_one_registration_id, v_room.player_two_registration_id)
      and r.clerk_user_id = v_sub order by r.id limit 1;
    if v_registration_id is null then raise exception 'Match Room unavailable' using errcode = '42501'; end if;
  end if;
  -- Stale commands never receive historical content through the write endpoint.
  if not exists (select 1 from public.tournament_matches m where m.id = p_match_id
    and m.communication_generation = v_room.communication_generation
    and m.player_one_registration_id = v_room.player_one_registration_id
    and m.player_two_registration_id = v_room.player_two_registration_id) then
    raise exception 'The Match Room changed; refresh and try again' using errcode = '40001';
  end if;
  perform ironclad_private.require_current_account_legal_acceptance();
  select * into v_message from public.match_messages
  where room_id = v_room.id and actor_clerk_user_id = v_sub and client_message_id = p_client_message_id;
  if found then
    if v_message.body <> p_body or v_message.sender_kind <> (case when p_admin then 'admin' else 'player' end) then
      raise exception 'The message key has already been used' using errcode = '23505';
    end if;
    return jsonb_build_object('message', ironclad_private.match_message_projection(v_message), 'duplicate', true);
  end if;
  if v_room.closed_at is not null then
    raise exception 'Match Room is read-only' using errcode = '55000';
  end if;
  v_now := clock_timestamp();
  if (select count(*) from public.match_messages where room_id = v_room.id
    and actor_clerk_user_id = v_sub and created_at > v_now - interval '1 minute') >= 15 then
    raise exception 'MATCH_ROOM_RATE_LIMITED' using errcode = 'P0001';
  end if;
  update public.match_rooms set last_sequence = last_sequence + 1
  where id = v_room.id returning * into v_room;
  insert into public.match_messages(room_id, sequence, sender_kind, sender_registration_id,
    actor_clerk_user_id, client_message_id, body, created_at)
  values(v_room.id, v_room.last_sequence, case when p_admin then 'admin' else 'player' end,
    v_registration_id, v_sub, p_client_message_id, p_body, v_now) returning * into v_message;
  return jsonb_build_object('message', ironclad_private.match_message_projection(v_message), 'duplicate', false);
end;
$function$

CREATE OR REPLACE FUNCTION ironclad_private.validate_match_game_winner_sequence(p_match_id uuid, p_winner_registration_id uuid, p_player_one_score integer, p_player_two_score integer, p_game_winner_registration_ids uuid[])
 RETURNS uuid[]
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_match public.tournament_matches%rowtype;
  v_required_game_count integer;
  v_wins_required integer;
  v_player_one_wins integer := 0;
  v_player_two_wins integer := 0;
  v_index integer;
  v_game_winner uuid;
begin
  select match.*
  into v_match
  from public.tournament_matches as match
  where match.id = p_match_id;

  if not found then
    raise exception 'Tournament match not found';
  end if;

  if v_match.player_one_registration_id is null
    or v_match.player_two_registration_id is null then
    raise exception 'Both match participants must be assigned';
  end if;

  if p_winner_registration_id not in (
    v_match.player_one_registration_id,
    v_match.player_two_registration_id
  ) then
    raise exception 'Winner must be a participant in this match';
  end if;

  if p_player_one_score is null
    or p_player_two_score is null
    or p_player_one_score < 0
    or p_player_two_score < 0 then
    raise exception 'Enter a valid final score';
  end if;

  v_required_game_count := p_player_one_score + p_player_two_score;
  v_wins_required := (v_match.series_best_of / 2) + 1;

  if p_game_winner_registration_ids is null
    or cardinality(p_game_winner_registration_ids) <> v_required_game_count
    or array_position(p_game_winner_registration_ids, null) is not null then
    raise exception 'Select one winner for every played game';
  end if;

  for v_index in 1..v_required_game_count loop
    v_game_winner := p_game_winner_registration_ids[v_index];

    if v_game_winner = v_match.player_one_registration_id then
      v_player_one_wins := v_player_one_wins + 1;
    elsif v_game_winner = v_match.player_two_registration_id then
      v_player_two_wins := v_player_two_wins + 1;
    else
      raise exception 'Every game winner must be a match participant';
    end if;

    if v_index < v_required_game_count
      and (
        v_player_one_wins >= v_wins_required
        or v_player_two_wins >= v_wins_required
      ) then
      raise exception 'A played game cannot follow the series-clinching game';
    end if;
  end loop;

  if v_player_one_wins <> p_player_one_score
    or v_player_two_wins <> p_player_two_score then
    raise exception 'Game winners do not match the final score';
  end if;

  if (
    p_winner_registration_id = v_match.player_one_registration_id
    and v_player_one_wins <> v_wins_required
  ) or (
    p_winner_registration_id = v_match.player_two_registration_id
    and v_player_two_wins <> v_wins_required
  ) then
    raise exception 'Game winners do not match the series winner';
  end if;

  return p_game_winner_registration_ids;
end;
$function$

CREATE OR REPLACE FUNCTION public.add_leaderboard_admin_adjustment_without_terminal_guard(p_season_id uuid, p_player_id uuid, p_bracket_type text, p_points integer, p_description text DEFAULT NULL::text, p_tournament_id uuid DEFAULT NULL::uuid, p_tournament_bracket_id uuid DEFAULT NULL::uuid, p_registration_id uuid DEFAULT NULL::uuid, p_triggered_by_clerk_user_id text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_event_id uuid;
  v_season_run_id uuid;
  v_season_run_status text;
begin
  perform public.leaderboard_require_write_access();
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('ironclad:leaderboard:all-time', 0)
  );

  if not exists (
    select 1
    from public.leaderboard_seasons as season
    where season.id = p_season_id
  ) then
    raise exception 'Leaderboard season not found';
  end if;

  if not exists (
    select 1
    from public.players as player
    where player.id = p_player_id
  ) then
    raise exception 'Player not found';
  end if;

  if p_bracket_type not in ('academy', 'challenge', 'main', 'overall') then
    raise exception 'Invalid leaderboard bracket type';
  end if;

  insert into public.leaderboard_point_events (
    season_id,
    tournament_id,
    tournament_bracket_id,
    registration_id,
    player_id,
    bracket_type,
    points,
    event_type,
    description,
    source,
    created_by_clerk_user_id
  )
  values (
    p_season_id,
    p_tournament_id,
    p_tournament_bracket_id,
    p_registration_id,
    p_player_id,
    p_bracket_type,
    p_points,
    'admin_adjustment',
    nullif(pg_catalog.btrim(p_description), ''),
    'admin',
    nullif(pg_catalog.btrim(p_triggered_by_clerk_user_id), '')
  )
  returning id into v_event_id;

  v_season_run_id := public.recalculate_leaderboard_for_season(
    p_season_id,
    p_triggered_by_clerk_user_id
  );

  select run.status
  into v_season_run_status
  from public.leaderboard_recalculation_runs as run
  where run.id = v_season_run_id;

  if v_season_run_status is distinct from 'completed' then
    raise exception 'Season leaderboard recalculation failed';
  end if;

  return v_event_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_reset_tournament_match(p_match_id uuid, p_reset_by text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
begin
  if session_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'Not authorized' using errcode = '42501';
  end if;
  perform 1 from public.tournament_matches where id = p_match_id for update;
  perform public.admin_reset_tournament_match_without_communication_generation(p_match_id, p_reset_by);
  update public.tournament_matches
  set communication_generation = communication_generation + 1
  where id = p_match_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_reset_tournament_match_without_communication_generation(p_match_id uuid, p_reset_by text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_match public.tournament_matches%rowtype;
  v_round_number integer;
  v_round_name text;
  v_format text;
  v_next_round_id uuid;
  v_next_match_number integer;
  v_next public.tournament_matches%rowtype;
  v_activated_at timestamptz;
  v_activation_version integer;
begin
  if nullif(btrim(p_reset_by), '') is null then
    raise exception 'Resetting administrator is required';
  end if;

  select match.*
  into v_match
  from public.tournament_matches as match
  where match.id = p_match_id
  for update;

  if not found then
    raise exception 'Tournament match not found';
  end if;

  select round.round_number, round.name, generated.format
  into v_round_number, v_round_name, v_format
  from public.bracket_rounds as round
  join public.generated_brackets as generated
    on generated.id = round.generated_bracket_id
  where round.id = v_match.round_id;

  if v_format = 'round_robin' then
    perform public.admin_reset_tournament_match_without_deadline_outcomes(
      p_match_id,
      p_reset_by
    );
    return;
  end if;

  if v_match.status <> 'completed' then
    raise exception 'Only a completed match can use the downstream-safe reset';
  end if;

  if v_match.outcome_type in ('automatic_bye', 'empty_feeder') then
    raise exception 'Reset the originating feeder result instead';
  end if;

  if v_match.hold_started_at is not null
    and v_match.hold_released_at is null then
    raise exception 'Release the administrative hold before resetting';
  end if;

  if v_match.player_one_registration_id is null
    or v_match.player_two_registration_id is null then
    raise exception 'A reopened real matchup requires both participants';
  end if;

  select round.id
  into v_next_round_id
  from public.bracket_rounds as round
  where round.generated_bracket_id = v_match.generated_bracket_id
    and round.round_number = v_round_number + 1;

  if v_next_round_id is not null then
    v_next_match_number := ceil(v_match.match_number / 2.0)::integer;

    select match.*
    into v_next
    from public.tournament_matches as match
    where match.round_id = v_next_round_id
      and match.match_number = v_next_match_number
    for update;

    if not found then
      raise exception 'Generated downstream match not found';
    end if;

    if v_next.outcome_type in ('automatic_bye', 'empty_feeder') then
      perform public.unwind_derived_match_outcome(v_next.id, p_reset_by);

      select match.*
      into v_next
      from public.tournament_matches as match
      where match.id = v_next.id
      for update;
    end if;

    if v_next.status <> 'scheduled'
      or v_next.activation_version <> 0
      or v_next.activated_at is not null
      or v_next.deadline_at is not null
      or v_next.player_one_score is not null
      or v_next.player_two_score is not null
      or v_next.winner_registration_id is not null
      or v_next.official_result_submission_id is not null
      or v_next.official_result_decided_by is not null
      or v_next.official_result_decided_at is not null
      or v_next.outcome_type is not null
      or v_next.deadline_ruled_at is not null
      or v_next.extension_minutes is not null
      or v_next.hold_started_at is not null
      or exists (
        select 1
        from public.match_result_submissions as submission
        where submission.match_id = v_next.id
      )
      or exists (
        select 1
        from public.match_result_report_groups as report_group
        where report_group.match_id = v_next.id
      ) then
      raise exception 'Reset blocked because the downstream match has activity';
    end if;

    if (v_match.match_number % 2) = 1 then
      if v_match.winner_registration_id is not null
        and v_next.player_one_registration_id is distinct from
          v_match.winner_registration_id then
        raise exception 'Downstream player slot no longer matches this winner';
      end if;

      update public.tournament_matches
      set player_one_registration_id = null
      where id = v_next.id;
    else
      if v_match.winner_registration_id is not null
        and v_next.player_two_registration_id is distinct from
          v_match.winner_registration_id then
        raise exception 'Downstream player slot no longer matches this winner';
      end if;

      update public.tournament_matches
      set player_two_registration_id = null
      where id = v_next.id;
    end if;
  end if;

  update public.match_result_report_groups
  set
    status = 'reset',
    reviewed_by = p_reset_by,
    reviewed_at = now(),
    review_notes = coalesce(
      review_notes,
      'Match was reset by an administrator.'
    ),
    finalized_at = coalesce(finalized_at, now()),
    finalized_source = 'reset'
  where match_id = p_match_id
    and status <> 'reset';

  update public.match_result_submissions
  set
    status = 'rejected',
    reviewed_by = p_reset_by,
    review_notes = coalesce(
      review_notes,
      'Match was reset by an administrator.'
    ),
    reviewed_at = now()
  where match_id = p_match_id
    and status <> 'rejected';

  v_activated_at := clock_timestamp();
  v_activation_version := greatest(v_match.activation_version + 1, 1);

  update public.tournament_matches
  set
    player_one_score = null,
    player_two_score = null,
    winner_registration_id = null,
    official_result_submission_id = null,
    official_result_decided_by = null,
    official_result_decided_at = null,
    outcome_type = null,
    deadline_ruled_at = null,
    status = 'in_progress',
    activation_version = v_activation_version,
    activated_at = v_activated_at,
    deadline_at = v_activated_at + interval '7 days'
  where id = p_match_id;

  perform public.create_matchup_notifications(
    p_match_id,
    format('activation:%s:ready', v_activation_version),
    'match.ready',
    'Your matchup reopened',
    format(
      '%s reopened with a fresh seven-day window after an administrator reset.',
      v_round_name
    ),
    jsonb_build_object(
      'deadlineEvent', 'ready',
      'reopened', true,
      'activatedAt', v_activated_at,
      'deadlineAt', v_activated_at + interval '7 days'
    )
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_update_match_participants(p_match_id uuid, p_player_one_registration_id uuid, p_player_two_registration_id uuid, p_updated_by text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_match public.tournament_matches%rowtype;
  v_format text;
  v_tournament_bracket_id uuid;
begin
  if p_updated_by is null or btrim(p_updated_by) = '' then
    raise exception 'Updating administrator is required';
  end if;

  if p_player_one_registration_id is not null
    and p_player_one_registration_id = p_player_two_registration_id then
    raise exception 'A player cannot occupy both match slots';
  end if;

  select match.*
  into v_match
  from public.tournament_matches as match
  where match.id = p_match_id
  for update;

  if not found then
    raise exception 'Tournament match not found';
  end if;

  select generated.format, generated.tournament_bracket_id
  into v_format, v_tournament_bracket_id
  from public.generated_brackets as generated
  where generated.id = v_match.generated_bracket_id;

  if v_format = 'round_robin' then
    raise exception
      'Round-robin participant edits require the bracket population or reset workflow';
  end if;

  if v_match.status <> 'scheduled'
    or v_match.player_one_score is not null
    or v_match.player_two_score is not null
    or v_match.winner_registration_id is not null
    or v_match.official_result_submission_id is not null
    or v_match.official_result_decided_by is not null
    or v_match.official_result_decided_at is not null then
    raise exception
      'Participant edits are blocked after a match has started, been scored, or received an official result';
  end if;

  if exists (
    select 1
    from public.match_result_submissions as submission
    where submission.match_id = p_match_id
  )
  or exists (
    select 1
    from public.match_result_report_groups as report_group
    where report_group.match_id = p_match_id
  ) then
    raise exception
      'Participant edits are blocked because this match has result activity or proof records';
  end if;

  if p_player_one_registration_id is not null
    and not exists (
      select 1
      from public.registrations as registration
      where registration.id = p_player_one_registration_id
        and registration.tournament_bracket_id = v_tournament_bracket_id
        and registration.registration_status = 'approved'
    ) then
    raise exception
      'Player 1 must be an approved registration in this bracket';
  end if;

  if p_player_two_registration_id is not null
    and not exists (
      select 1
      from public.registrations as registration
      where registration.id = p_player_two_registration_id
        and registration.tournament_bracket_id = v_tournament_bracket_id
        and registration.registration_status = 'approved'
    ) then
    raise exception
      'Player 2 must be an approved registration in this bracket';
  end if;

  if exists (
    select 1
    from public.tournament_matches as other_match
    where other_match.generated_bracket_id = v_match.generated_bracket_id
      and other_match.id <> p_match_id
      and (
        (
          p_player_one_registration_id is not null
          and p_player_one_registration_id in (
            other_match.player_one_registration_id,
            other_match.player_two_registration_id
          )
        )
        or (
          p_player_two_registration_id is not null
          and p_player_two_registration_id in (
            other_match.player_one_registration_id,
            other_match.player_two_registration_id
          )
        )
        or (
          v_match.player_one_registration_id is not null
          and v_match.player_one_registration_id in (
            other_match.player_one_registration_id,
            other_match.player_two_registration_id
          )
        )
        or (
          v_match.player_two_registration_id is not null
          and v_match.player_two_registration_id in (
            other_match.player_one_registration_id,
            other_match.player_two_registration_id
          )
        )
      )
  ) then
    raise exception
      'Participant edits are blocked because one of these players already appears elsewhere in this bracket';
  end if;

  update public.tournament_matches
  set
    player_one_registration_id = p_player_one_registration_id,
    player_two_registration_id = p_player_two_registration_id
  where id = p_match_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.apply_official_match_result(p_match_id uuid, p_player_one_score integer, p_player_two_score integer, p_winner_registration_id uuid, p_decided_by text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_match public.tournament_matches%rowtype;
  v_format text;
  v_wins_required integer;
  v_loser_score integer;
begin
  if p_decided_by is null or btrim(p_decided_by) = '' then
    raise exception 'Deciding administrator is required';
  end if;

  select match.*
  into v_match
  from public.tournament_matches as match
  where match.id = p_match_id
  for update;

  if not found then
    raise exception 'Tournament match not found';
  end if;

  select generated.format
  into v_format
  from public.generated_brackets as generated
  where generated.id = v_match.generated_bracket_id;

  if (
      v_format = 'single_elimination'
      and v_match.status not in ('in_progress', 'pending_review')
    )
    or v_match.status = 'completed'
    or v_match.outcome_type is not null
    or v_match.winner_registration_id is not null then
    raise exception 'This match cannot receive an official result';
  end if;

  if v_match.player_one_registration_id is null
    or v_match.player_two_registration_id is null then
    raise exception 'Both match participants must be assigned';
  end if;

  if p_winner_registration_id not in (
    v_match.player_one_registration_id,
    v_match.player_two_registration_id
  ) then
    raise exception 'Winner must be a participant in this match';
  end if;

  if p_player_one_score is null
    or p_player_two_score is null
    or p_player_one_score < 0
    or p_player_two_score < 0
    or p_player_one_score = p_player_two_score then
    raise exception 'A valid non-tied score is required';
  end if;

  v_wins_required := (v_match.series_best_of / 2) + 1;

  if p_winner_registration_id = v_match.player_one_registration_id then
    if p_player_one_score <> v_wins_required
      or p_player_two_score >= v_wins_required then
      raise exception 'Score does not satisfy the match format';
    end if;
    v_loser_score := p_player_two_score;
  else
    if p_player_two_score <> v_wins_required
      or p_player_one_score >= v_wins_required then
      raise exception 'Score does not satisfy the match format';
    end if;
    v_loser_score := p_player_one_score;
  end if;

  if v_loser_score < 0 or v_loser_score >= v_wins_required then
    raise exception 'Score does not satisfy the match format';
  end if;

  update public.tournament_matches
  set
    player_one_score = p_player_one_score,
    player_two_score = p_player_two_score,
    winner_registration_id = p_winner_registration_id,
    outcome_type = null,
    deadline_ruled_at = null,
    status = 'completed'
  where id = p_match_id;

  update public.match_result_submissions
  set
    status = 'rejected',
    reviewed_by = p_decided_by,
    review_notes = coalesce(
      review_notes,
      'Superseded by the official match result.'
    ),
    reviewed_at = now()
  where match_id = p_match_id
    and status = 'pending';

  if v_format = 'round_robin' then
    update public.tournament_standings as standing
    set
      wins = results.wins,
      losses = results.losses,
      points = results.wins * 3
    from (
      select
        roster.registration_id,
        count(*) filter (
          where match.winner_registration_id = roster.registration_id
        )::integer as wins,
        count(*) filter (
          where match.status = 'completed'
            and match.winner_registration_id is distinct from
              roster.registration_id
        )::integer as losses
      from public.tournament_standings as roster
      cross join lateral (
        select match.*
        from public.tournament_matches as match
        where match.generated_bracket_id = v_match.generated_bracket_id
          and match.status = 'completed'
          and roster.registration_id in (
            match.player_one_registration_id,
            match.player_two_registration_id
          )
      ) as match
      where roster.generated_bracket_id = v_match.generated_bracket_id
      group by roster.registration_id
    ) as results
    where standing.generated_bracket_id = v_match.generated_bracket_id
      and standing.registration_id = results.registration_id;
  else
    perform public.reconcile_downstream_match(p_match_id);
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.assert_report_group_replay_count(p_report_group_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_group public.match_result_report_groups%rowtype;
  v_required_replay_count integer;
  v_replay_count integer;
  v_distinct_path_count integer;
  v_hash_count integer;
  v_distinct_hash_count integer;
begin
  select report_group.*
  into v_group
  from public.match_result_report_groups as report_group
  where report_group.id = p_report_group_id;

  if not found then
    raise exception 'Match result report group not found';
  end if;

  if v_group.result_type = 'no_show'
    or v_group.replay_proof_mode = 'no_show_report' then
    return;
  end if;

  v_required_replay_count := v_group.player_one_score + v_group.player_two_score;

  select
    (count(*) filter (
      where submission.replay_storage_path is not null
    ))::integer,
    (count(distinct submission.replay_storage_path) filter (
      where submission.replay_storage_path is not null
    ))::integer,
    (count(submission.replay_content_hash) filter (
      where submission.replay_storage_path is not null
    ))::integer,
    (count(distinct submission.replay_content_hash) filter (
      where submission.replay_storage_path is not null
        and submission.replay_content_hash is not null
    ))::integer
  into
    v_replay_count,
    v_distinct_path_count,
    v_hash_count,
    v_distinct_hash_count
  from public.match_result_submissions as submission
  where submission.report_group_id = p_report_group_id;

  if v_replay_count = 0 and v_group.replay_storage_path is not null then
    v_replay_count := 1;
    v_distinct_path_count := 1;
    v_hash_count := 0;
    v_distinct_hash_count := 0;
  end if;

  if v_group.replay_proof_mode = 'single_series_replay' then
    if v_replay_count < 1 then
      raise exception 'At least one replay file is required';
    end if;

    if v_distinct_path_count <> v_replay_count then
      raise exception 'Duplicate replay storage paths cannot be finalized';
    end if;

    if v_hash_count > 0 and v_distinct_hash_count <> v_hash_count then
      raise exception 'Duplicate replay payloads cannot be finalized';
    end if;

    return;
  end if;

  if v_replay_count <> v_required_replay_count then
    raise exception
      'This final score requires exactly % replay file%',
      v_required_replay_count,
      case when v_required_replay_count = 1 then '' else 's' end;
  end if;

  if v_distinct_path_count <> v_replay_count then
    raise exception 'Duplicate replay storage paths cannot be finalized';
  end if;

  if v_hash_count <> v_replay_count then
    raise exception 'Replay hash audit data is incomplete';
  end if;

  if v_distinct_hash_count <> v_hash_count then
    raise exception 'Duplicate replay payloads cannot be finalized';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.assert_tournament_not_terminal(p_tournament_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_status text;
begin
  select tournament.status
  into v_status
  from public.tournaments as tournament
  where tournament.id = p_tournament_id
  for key share;

  if not found then
    raise exception 'Tournament not found';
  end if;

  if v_status in ('cancelled', 'voided') then
    raise exception 'Terminal tournaments cannot accept competitive mutation'
      using errcode = '55000';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.assert_tournament_not_terminal_nowait(p_tournament_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_status text;
begin
  begin
    select tournament.status
    into v_status
    from public.tournaments as tournament
    where tournament.id = p_tournament_id
    for key share nowait;
  exception when lock_not_available then
    raise exception 'Tournament is being updated; retry the operation'
      using errcode = '55P03';
  end;

  if v_status is null then
    raise exception 'Tournament not found';
  end if;

  if v_status in ('cancelled', 'voided') then
    raise exception 'Terminal tournaments cannot accept competitive mutation'
      using errcode = '55000';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.assign_canonical_notification_event_key()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
begin
  if new.event_key is not null or new.registration_id is null then
    return new;
  end if;

  if new.type = 'registration.waitlist_offer' then
    new.event_key := pg_catalog.format(
      'registration:%s:waitlist-offer',
      new.registration_id
    );
  elsif new.type = 'registration.waitlist_closed' then
    new.event_key := pg_catalog.format(
      'registration:%s:waitlist-closed',
      new.registration_id
    );
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.assign_leaderboard_tournament_season(p_tournament_id uuid)
 RETURNS TABLE(season_id uuid, qualifying_event_number smallint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_status text;
  v_effective_date date;
  v_existing public.leaderboard_tournament_season_memberships%rowtype;
  v_season_id uuid;
  v_event_number smallint;
  v_has_launched_main boolean;
  v_valid_event_count integer;
begin
  select
    tournament.status,
    coalesce(
      tournament.first_completed_at::date,
      tournament.grand_final_at::date,
      tournament.end_date::date,
      tournament.start_date::date,
      tournament.created_at::date,
      current_date
    )
  into v_status, v_effective_date
  from public.tournaments as tournament
  where tournament.id = p_tournament_id;

  if not found then
    raise exception 'Tournament not found';
  end if;

  select membership.*
  into v_existing
  from public.leaderboard_tournament_season_memberships as membership
  where membership.tournament_id = p_tournament_id;

  if found then
    if v_existing.voided_at is not null then
      raise exception 'A voided tournament membership cannot be reassigned'
        using errcode = '55000';
    end if;

    return query
    select v_existing.season_id, v_existing.qualifying_event_number;
    return;
  end if;

  if v_status <> 'completed' then
    raise exception 'Tournament must be completed before leaderboard assignment';
  end if;

  if not exists (
    select 1
    from public.tournaments as tournament
    where tournament.id = p_tournament_id
      and tournament.first_completed_at is not null
  ) then
    raise exception 'Tournament first completion was not recorded';
  end if;

  select exists (
    select 1
    from public.tournament_brackets as bracket
    where bracket.tournament_id = p_tournament_id
      and bracket.name = 'Main'
      and bracket.launched_at is not null
  )
  into v_has_launched_main;

  if v_has_launched_main then
    select season.id
    into v_season_id
    from public.leaderboard_seasons as season
    where season.finalized_at is null
      and (
        select count(*)
        from public.leaderboard_tournament_season_memberships as membership
        where membership.season_id = season.id
          and membership.qualifying_event_number is not null
          and membership.voided_at is null
      ) < 6
    order by season.created_at, season.id
    limit 1;

    if v_season_id is null then
      v_season_id := public.get_or_create_leaderboard_season(v_effective_date);
    end if;

    select slot.event_number::smallint
    into v_event_number
    from generate_series(1, 6) as slot(event_number)
    where not exists (
      select 1
      from public.leaderboard_tournament_season_memberships as membership
      where membership.season_id = v_season_id
        and membership.qualifying_event_number = slot.event_number
        and membership.voided_at is null
    )
    order by slot.event_number
    limit 1;

    if v_event_number is null then
      raise exception 'Main/Pro leaderboard season already contains six valid events';
    end if;
  else
    -- Career-only history remains in the latest factual container and never
    -- consumes or creates a Main/Pro event slot.
    select season.id
    into v_season_id
    from public.leaderboard_seasons as season
    order by season.created_at desc, season.id desc
    limit 1;

    if v_season_id is null then
      v_season_id := public.get_or_create_leaderboard_season(v_effective_date);
    end if;
  end if;

  insert into public.leaderboard_tournament_season_memberships (
    tournament_id,
    season_id,
    qualifying_event_number
  )
  values (
    p_tournament_id,
    v_season_id,
    v_event_number
  );

  select count(*)::integer
  into v_valid_event_count
  from public.leaderboard_tournament_season_memberships as membership
  where membership.season_id = v_season_id
    and membership.qualifying_event_number is not null
    and membership.voided_at is null;

  update public.leaderboard_seasons
  set
    start_date = least(start_date, v_effective_date),
    end_date = greatest(end_date, v_effective_date),
    is_active = case
      when v_has_launched_main and v_valid_event_count = 6 then false
      else is_active
    end
  where id = v_season_id;

  return query select v_season_id, v_event_number;
end;
$function$

CREATE OR REPLACE FUNCTION public.cancel_poll(p_poll_id uuid, p_reason text, p_actor_clerk_user_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_actor text := nullif(pg_catalog.btrim(p_actor_clerk_user_id), '');
  v_reason text := nullif(pg_catalog.btrim(p_reason), '');
  v_poll public.polls%rowtype;
  v_cancelled_at timestamptz;
begin
  perform public.assert_poll_service_role();
  if v_actor is null then
    raise exception 'Poll administrator is required' using errcode = '22023';
  end if;
  if v_reason is null or char_length(v_reason) > 500 then
    raise exception 'Cancellation reason must be between 1 and 500 characters'
      using errcode = '22023';
  end if;

  select poll.* into v_poll
  from public.polls as poll
  where poll.id = p_poll_id
  for update;

  if not found then
    raise exception 'Poll not found';
  end if;
  if v_poll.published_at is null then
    raise exception 'Delete an unpublished Draft instead'
      using errcode = '55000';
  end if;
  if v_poll.cancelled_at is not null then
    raise exception 'Poll is already cancelled' using errcode = '55000';
  end if;
  if v_poll.final_decision_published_at is not null then
    raise exception 'A final-published decision cannot be cancelled'
      using errcode = '55000';
  end if;

  -- Record the factual cancellation instant only after the serialized poll
  -- state is known. A request waiting behind publication cannot backdate it.
  v_cancelled_at := pg_catalog.clock_timestamp();

  update public.polls
  set cancelled_at = v_cancelled_at,
    cancellation_reason = v_reason,
    cancelled_by_clerk_user_id = v_actor,
    updated_by_clerk_user_id = v_actor
  where id = p_poll_id;

  return pg_catalog.jsonb_build_object(
    'poll_id', p_poll_id,
    'cancelled_at', v_cancelled_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.cancel_tournament(p_tournament_id uuid, p_reason text, p_actor_clerk_user_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_tournament public.tournaments%rowtype;
  v_reason text := nullif(pg_catalog.btrim(p_reason), '');
  v_actor text := nullif(pg_catalog.btrim(p_actor_clerk_user_id), '');
  v_previous_transition text;
begin
  perform public.leaderboard_require_write_access();

  if p_tournament_id is null then
    raise exception 'Tournament is required';
  end if;
  if v_reason is null or char_length(v_reason) > 2000 then
    raise exception 'A non-empty cancellation reason of at most 2000 characters is required';
  end if;
  if v_actor is null then
    raise exception 'Cancelling administrator identity is required';
  end if;

  select tournament.*
  into v_tournament
  from public.tournaments as tournament
  where tournament.id = p_tournament_id
  for update;

  if not found then
    raise exception 'Tournament not found';
  end if;
  if v_tournament.status = 'cancelled' then
    return pg_catalog.jsonb_build_object('outcome', 'already_cancelled');
  end if;
  if v_tournament.status = 'voided' then
    raise exception 'A voided tournament cannot be cancelled'
      using errcode = '55000';
  end if;

  if not exists (
    select 1
    from public.tournament_brackets as bracket
    where bracket.tournament_id = p_tournament_id
      and bracket.launched_at is not null
  ) then
    raise exception 'Only a launched tournament can be cancelled';
  end if;

  if exists (
    select 1
    from public.leaderboard_point_events as event
    where event.tournament_id = p_tournament_id
      or event.tournament_bracket_id in (
        select bracket.id
        from public.tournament_brackets as bracket
        where bracket.tournament_id = p_tournament_id
      )
      or event.registration_id in (
        select registration.id
        from public.registrations as registration
        where registration.tournament_id = p_tournament_id
      )
  ) then
    raise exception 'Leaderboard point history requires the Void operation'
      using errcode = '55000';
  end if;

  if public.tournament_has_official_competition(p_tournament_id) then
    raise exception 'Official competitive history requires the Void operation'
      using errcode = '55000';
  end if;

  v_previous_transition := pg_catalog.current_setting(
    'ironclad.tournament_terminal_transition',
    true
  );
  perform pg_catalog.set_config(
    'ironclad.tournament_terminal_transition',
    'on',
    true
  );

  update public.tournaments
  set
    status = 'cancelled',
    registration_enabled = false,
    terminal_at = clock_timestamp(),
    terminal_reason = v_reason,
    terminated_by_clerk_user_id = v_actor
  where id = p_tournament_id;

  perform pg_catalog.set_config(
    'ironclad.tournament_terminal_transition',
    coalesce(v_previous_transition, ''),
    true
  );

  return pg_catalog.jsonb_build_object('outcome', 'cancelled');
end;
$function$

CREATE OR REPLACE FUNCTION public.canonicalize_registration_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_player public.players%rowtype;
  v_tournament_title text;
  v_bracket_name text;
begin
  if auth.role() is distinct from 'authenticated' then
    return new;
  end if;

  select player.*
  into v_player
  from public.players as player
  where player.id = new.profile_id
    and player.clerk_user_id = (auth.jwt() ->> 'sub')
    and player.profile_completed;

  if not found then
    raise exception
      'Registration profile must belong to the authenticated user and be complete';
  end if;

  select tournament.title, bracket.name
  into v_tournament_title, v_bracket_name
  from public.tournament_brackets as bracket
  join public.tournaments as tournament
    on tournament.id = bracket.tournament_id
  where bracket.id = new.tournament_bracket_id
    and tournament.id = new.tournament_id;

  if not found then
    raise exception 'Selected tournament bracket does not exist';
  end if;

  new.clerk_user_id = v_player.clerk_user_id;
  new.player_name = v_player.in_game_name;
  new.discord_username = v_player.discord_username;
  new.steam_name = v_player.steam_username;
  new.coh3_player_card_url = v_player.coh3_player_card_url;
  new.country = v_player.country;
  new.region = v_player.region;
  new.timezone = v_player.timezone;
  new.submitted_elo = v_player.current_elo;
  new.tournament_title = v_tournament_title;
  new.bracket_name = v_bracket_name || ' Bracket';
  new.elo_status = 'pending';
  new.elo_verified_elo = null;
  new.elo_difference = null;
  new.elo_highest_faction = null;
  new.elo_checked_mode = null;
  new.elo_checked_at = null;
  new.elo_verification_source = null;
  new.elo_verification_error = null;
  new.elo_verification_payload = null;
  new.elo_verified_player_name = null;
  new.elo_identity_status = null;
  new.elo_identity_error = null;
  new.admin_notes = '';
  new.created_at = now();
  new.updated_at = now();

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.cast_poll_ballot(p_poll_id uuid, p_expected_revision integer, p_option_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_clerk_user_id text := nullif(auth.jwt() ->> 'sub', '');
  v_player_id uuid;
  v_poll public.polls%rowtype;
  v_eligibility public.poll_eligible_voters%rowtype;
  v_now timestamptz;
  v_requested_count integer;
  v_valid_option_count integer;
  v_requested_options uuid[];
  v_current_options uuid[];
  v_first_voted_at timestamptz;
  v_ballot_updated_at timestamptz;
  v_new_revision integer;
begin
  if coalesce(auth.role(), '') <> 'authenticated'
    or v_clerk_user_id is null then
    raise exception 'Poll unavailable' using errcode = '42501';
  end if;

  select player.id
  into v_player_id
  from public.players as player
  where player.clerk_user_id = v_clerk_user_id
    and player.account_closed_at is null
  for share;

  if not found then
    raise exception 'Poll unavailable' using errcode = '42501';
  end if;

  select poll.*
  into v_poll
  from public.polls as poll
  where poll.id = p_poll_id
  for share;

  if not found
    or v_poll.published_at is null
    or v_poll.cancelled_at is not null then
    raise exception 'Poll unavailable' using errcode = '42501';
  end if;

  select eligible.*
  into v_eligibility
  from public.poll_eligible_voters as eligible
  where eligible.poll_id = p_poll_id
    and eligible.player_id = v_player_id
  for update;

  if not found then
    raise exception 'Poll unavailable' using errcode = '42501';
  end if;

  perform ironclad_private.require_current_account_legal_acceptance();

  -- Capture the authoritative time only after a concurrent ballot update can
  -- no longer keep this request waiting across the close boundary.
  v_now := pg_catalog.clock_timestamp();
  if v_now < v_poll.opens_at or v_now >= v_poll.closes_at then
    raise exception 'Poll unavailable' using errcode = '42501';
  end if;

  if p_option_ids is null
    or coalesce(cardinality(p_option_ids), 0) = 0
    or array_position(p_option_ids, null) is not null then
    raise exception 'Select at least one valid poll option'
      using errcode = '22023';
  end if;

  select count(distinct option_id)::integer,
    pg_catalog.array_agg(distinct option_id order by option_id)
  into v_requested_count, v_requested_options
  from unnest(p_option_ids) as option_id;

  if v_requested_count <> cardinality(p_option_ids)
    or v_requested_count > v_poll.max_selections then
    raise exception 'Ballot selections are invalid'
      using errcode = '22023';
  end if;

  select count(*)::integer
  into v_valid_option_count
  from public.poll_options as option
  where option.poll_id = p_poll_id
    and option.id = any(v_requested_options);

  if v_valid_option_count <> v_requested_count then
    raise exception 'Ballot selections are invalid'
      using errcode = '22023';
  end if;

  select coalesce(
    pg_catalog.array_agg(choice.option_id order by choice.option_id),
    array[]::uuid[]
  )
  into v_current_options
  from public.poll_ballot_choices as choice
  where choice.poll_id = p_poll_id
    and choice.eligible_voter_id = v_eligibility.id;

  if v_current_options = v_requested_options then
    return pg_catalog.jsonb_build_object(
      'poll_id', p_poll_id,
      'ballot_revision', v_eligibility.ballot_revision,
      'selected_option_ids', pg_catalog.to_jsonb(v_current_options),
      'first_voted_at', v_eligibility.first_voted_at,
      'ballot_updated_at', v_eligibility.ballot_updated_at,
      'idempotent', true
    );
  end if;

  if p_expected_revision is null
    or p_expected_revision < 0
    or p_expected_revision <> v_eligibility.ballot_revision then
    raise exception 'Ballot revision conflict' using errcode = '40001';
  end if;

  delete from public.poll_ballot_choices
  where poll_id = p_poll_id
    and eligible_voter_id = v_eligibility.id;

  v_ballot_updated_at := pg_catalog.clock_timestamp();
  insert into public.poll_ballot_choices (
    poll_id, eligible_voter_id, option_id, selected_at
  )
  select p_poll_id, v_eligibility.id, option_id, v_ballot_updated_at
  from unnest(v_requested_options) as option_id
  order by option_id;

  update public.poll_eligible_voters
  set first_voted_at = coalesce(first_voted_at, v_ballot_updated_at),
    ballot_updated_at = v_ballot_updated_at,
    ballot_revision = ballot_revision + 1
  where id = v_eligibility.id
    and poll_id = p_poll_id
  returning first_voted_at, ballot_updated_at, ballot_revision
  into v_first_voted_at, v_ballot_updated_at, v_new_revision;

  return pg_catalog.jsonb_build_object(
    'poll_id', p_poll_id,
    'ballot_revision', v_new_revision,
    'selected_option_ids', pg_catalog.to_jsonb(v_requested_options),
    'first_voted_at', v_first_voted_at,
    'ballot_updated_at', v_ballot_updated_at,
    'idempotent', false
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_match_replay_attempt_cleanup(p_attempt_id uuid, p_match_id uuid, p_submitted_by_clerk_user_id text, p_finalization_claim_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_attempt public.match_replay_upload_attempts%rowtype;
  v_cleanup_claim_id uuid;
  v_now timestamptz := clock_timestamp();
begin
  perform 1
  from public.tournament_matches as match
  where match.id = p_match_id
  for update;

  if not found then
    raise exception 'Tournament match not found';
  end if;

  select attempt.*
  into v_attempt
  from public.match_replay_upload_attempts as attempt
  where attempt.id = p_attempt_id
    and attempt.match_id = p_match_id
  for update;

  if not found then
    raise exception 'Replay attempt not found';
  end if;

  if p_submitted_by_clerk_user_id is null
    or btrim(p_submitted_by_clerk_user_id) = ''
    or not exists (
      select 1
      from public.registrations as registration
      where registration.id = v_attempt.submitting_registration_id
        and registration.clerk_user_id = p_submitted_by_clerk_user_id
    )
  then
    raise exception 'Player does not own this replay attempt';
  end if;

  if v_attempt.status = 'committed' then
    return jsonb_build_object('outcome', 'preserved');
  end if;

  if v_attempt.status = 'cleaned' then
    return jsonb_build_object('outcome', 'cleaned');
  end if;

  if v_attempt.status = 'finalizing' and not (
    p_finalization_claim_id is not null
    and v_attempt.finalization_claim_id = p_finalization_claim_id
  ) and v_attempt.finalization_lease_expires_at > v_now then
    raise exception 'Replay finalization owns this attempt';
  end if;

  if p_finalization_claim_id is not null and (
    v_attempt.status <> 'finalizing'
    or v_attempt.finalization_claim_id <> p_finalization_claim_id
  ) then
    raise exception 'Replay finalization claim no longer owns this attempt';
  end if;

  if v_attempt.status = 'cleaning'
    and v_attempt.cleanup_lease_expires_at > v_now then
    raise exception 'Replay cleanup is already in progress';
  end if;

  if v_attempt.status not in ('prepared', 'finalizing', 'cleaning') then
    raise exception 'Replay attempt is not available for cleanup';
  end if;

  v_cleanup_claim_id := gen_random_uuid();
  update public.match_replay_upload_attempts as attempt
  set
    status = 'cleaning',
    finalization_claim_id = null,
    finalization_lease_expires_at = null,
    cleanup_claim_id = v_cleanup_claim_id,
    cleanup_lease_expires_at = v_now + interval '5 minutes',
    updated_at = v_now
  where attempt.id = v_attempt.id;

  return jsonb_build_object(
    'outcome', 'claimed',
    'cleanup_claim_id', v_cleanup_claim_id,
    'replay_storage_paths', to_jsonb(v_attempt.replay_storage_paths)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_match_replay_attempt_finalization(p_attempt_id uuid, p_match_id uuid, p_submitted_by_clerk_user_id text, p_winner_registration_id uuid, p_player_one_score integer, p_player_two_score integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_attempt public.match_replay_upload_attempts%rowtype;
  v_match public.tournament_matches%rowtype;
  v_tournament_id uuid;
  v_launched_at timestamptz;
  v_claim_id uuid;
  v_now timestamptz := clock_timestamp();
begin
  if p_submitted_by_clerk_user_id is null
    or btrim(p_submitted_by_clerk_user_id) = '' then
    raise exception 'Submitting player is required';
  end if;

  select match.*
  into v_match
  from public.tournament_matches as match
  where match.id = p_match_id
  for update;

  if not found then
    raise exception 'Tournament match not found';
  end if;

  select bracket.tournament_id, bracket.launched_at
  into v_tournament_id, v_launched_at
  from public.tournament_matches as match
  join public.generated_brackets as generated
    on generated.id = match.generated_bracket_id
  join public.tournament_brackets as bracket
    on bracket.id = generated.tournament_bracket_id
  where match.id = v_match.id;

  if not found then
    raise exception 'Tournament bracket not found';
  end if;

  select attempt.*
  into v_attempt
  from public.match_replay_upload_attempts as attempt
  where attempt.id = p_attempt_id
    and attempt.match_id = p_match_id
  for update;

  if not found then
    raise exception 'Replay attempt not found';
  end if;

  if not exists (
    select 1
    from public.registrations as registration
    where registration.id = v_attempt.submitting_registration_id
      and registration.clerk_user_id = p_submitted_by_clerk_user_id
  ) then
    raise exception 'Player does not own this replay attempt';
  end if;

  if p_winner_registration_id is distinct from v_attempt.winner_registration_id
    or p_player_one_score is distinct from v_attempt.player_one_score
    or p_player_two_score is distinct from v_attempt.player_two_score then
    raise exception 'Final result does not match this replay attempt';
  end if;

  if v_attempt.status = 'committed' then
    return jsonb_build_object(
      'outcome', 'committed',
      'report', v_attempt.committed_result,
      'winner_registration_id', v_attempt.winner_registration_id,
      'player_one_score', v_attempt.player_one_score,
      'player_two_score', v_attempt.player_two_score,
      'required_replay_count', v_attempt.required_replay_count
    );
  end if;

  if v_attempt.status = 'finalizing'
    and v_attempt.finalization_lease_expires_at > v_now then
    raise exception 'Replay finalization is already in progress';
  end if;

  if v_attempt.status not in ('prepared', 'finalizing') then
    raise exception 'Replay attempt is not available for finalization';
  end if;

  if v_launched_at is null then
    raise exception 'This tournament match is not open for replay submission';
  end if;

  perform public.assert_tournament_not_terminal(v_tournament_id);

  if v_match.status = 'completed'
    or v_match.official_result_submission_id is not null then
    raise exception 'This match already has an official result';
  end if;

  if v_match.player_one_registration_id is null
    or v_match.player_two_registration_id is null
    or v_attempt.submitting_registration_id not in (
    v_match.player_one_registration_id,
    v_match.player_two_registration_id
  ) or v_attempt.winner_registration_id not in (
    v_match.player_one_registration_id,
    v_match.player_two_registration_id
  ) then
    raise exception 'Replay attempt no longer matches this match';
  end if;

  if exists (
    select 1
    from public.match_result_report_groups as report_group
    where report_group.match_id = p_match_id
      and report_group.status in (
        'pending_confirmation',
        'disputed',
        'under_review'
      )
      and report_group.finalized_at is null
  ) or exists (
    select 1
    from public.match_result_submissions as submission
    where submission.match_id = p_match_id
      and submission.status = 'pending'
      and submission.report_group_id is null
  ) then
    raise exception 'This match already has active result activity';
  end if;

  v_claim_id := gen_random_uuid();
  update public.match_replay_upload_attempts as attempt
  set
    status = 'finalizing',
    finalization_claim_id = v_claim_id,
    finalization_lease_expires_at = v_now + interval '10 minutes',
    updated_at = v_now
  where attempt.id = v_attempt.id;

  return jsonb_build_object(
    'outcome', 'claimed',
    'claim_id', v_claim_id,
    'replay_storage_paths',
      to_jsonb(v_attempt.replay_storage_paths[1:v_attempt.required_replay_count]),
    'winner_registration_id', v_attempt.winner_registration_id,
    'player_one_score', v_attempt.player_one_score,
    'player_two_score', v_attempt.player_two_score,
    'required_replay_count', v_attempt.required_replay_count
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.cleanup_staging_synthetic_uat_enrolment(p_fixture_secret text, p_alias text, p_tournament_id uuid)
 RETURNS TABLE(alias text, player_id uuid, registration_id uuid, deleted boolean, promoted_registration_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_fixture ironclad_private.staging_synthetic_uat_players%rowtype;
  v_registration public.registrations%rowtype;
  v_bracket_launched_at timestamptz;
  v_tournament_status text;
begin
  perform ironclad_private.assert_staging_synthetic_uat_access(
    p_fixture_secret
  );

  select fixture.*
  into v_fixture
  from ironclad_private.staging_synthetic_uat_players as fixture
  where fixture.approved_alias = p_alias
  for update;

  if not found then
    raise exception 'Synthetic fixture player is unavailable'
      using errcode = 'P0002';
  end if;

  select registration.*
  into v_registration
  from ironclad_private.staging_synthetic_uat_enrolments as enrolment
  join public.registrations as registration
    on registration.id = enrolment.registration_id
  where enrolment.player_id = v_fixture.player_id
    and enrolment.tournament_id = p_tournament_id
  for update of enrolment, registration;

  if not found then
    return query select
      v_fixture.approved_alias,
      v_fixture.player_id,
      null::uuid,
      false,
      null::uuid;
    return;
  end if;

  select bracket.launched_at, tournament.status
  into v_bracket_launched_at, v_tournament_status
  from public.tournament_brackets as bracket
  join public.tournaments as tournament
    on tournament.id = bracket.tournament_id
  where bracket.id = v_registration.tournament_bracket_id
    and tournament.id = v_registration.tournament_id
  for update of bracket;

  if not found
    or v_bracket_launched_at is not null
    or v_tournament_status is null
    or v_tournament_status not in (
      'upcoming',
      'registration_open',
      'in_progress'
    )
    or exists (
      select 1
      from public.tournament_matches as match
      where match.player_one_registration_id = v_registration.id
        or match.player_two_registration_id = v_registration.id
        or match.winner_registration_id = v_registration.id
    )
    or exists (
      select 1
      from public.tournament_standings as standing
      where standing.registration_id = v_registration.id
    ) then
    raise exception 'Synthetic fixture enrolment has competition history'
      using errcode = '55000';
  end if;

  perform set_config(
    'ironclad.staging_synthetic_uat_cleanup',
    'on',
    true
  );

  delete from public.registrations as registration
  where registration.id = v_registration.id;

  perform public.reset_unlaunched_tournament_bracket_draft(
    v_registration.tournament_bracket_id
  );
  perform public.reconcile_tournament_waitlist(
    v_registration.tournament_bracket_id
  );

  return query select
    v_fixture.approved_alias,
    v_fixture.player_id,
    v_registration.id,
    true,
    null::uuid;
end;
$function$

CREATE OR REPLACE FUNCTION public.close_ironclad_player_account(p_clerk_user_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare v_sub text := nullif(btrim(p_clerk_user_id), ''); v_result jsonb;
begin
  if session_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'Account closure requires the trusted server boundary' using errcode = '42501';
  end if;
  if v_sub is null then raise exception 'Authenticated account identity is required' using errcode = '22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended('ironclad:match-room-account-closure', 0));
  update public.match_room_notification_episodes e set resolved_at = clock_timestamp()
  where e.resolved_at is null and exists (
    select 1 from public.registrations r where r.id = e.recipient_registration_id and r.clerk_user_id = v_sub
  );
  update public.match_room_assistance set resolved_by_clerk_user_id = null where resolved_by_clerk_user_id = v_sub;
  v_result := public.close_ironclad_player_account_without_room_episodes(v_sub);
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.close_ironclad_player_account_without_announcement_cleanup(p_clerk_user_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_clerk_user_id text := nullif(btrim(p_clerk_user_id), '');
begin
  if session_user <> 'postgres'
    and coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'Account closure requires the trusted server boundary'
      using errcode = '42501';
  end if;

  if v_clerk_user_id is null then
    raise exception 'Authenticated account identity is required'
      using errcode = '22023';
  end if;

  delete from public.push_subscriptions as subscription
  where subscription.owner_clerk_user_id = v_clerk_user_id;

  return public.close_ironclad_player_account_without_push_cleanup(
    v_clerk_user_id
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.close_ironclad_player_account_without_match_rooms(p_clerk_user_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_clerk_user_id text := nullif(btrim(p_clerk_user_id), '');
begin
  if session_user <> 'postgres'
    and coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'Account closure requires the trusted server boundary'
      using errcode = '42501';
  end if;

  if v_clerk_user_id is null then
    raise exception 'Authenticated account identity is required'
      using errcode = '22023';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'ironclad:announcement-account:' || v_clerk_user_id,
      0
    )
  );

  delete from public.announcement_read_states as read_state
  where read_state.clerk_user_id = v_clerk_user_id;

  update public.announcements as announcement
  set
    published_by_clerk_user_id = case
      when announcement.published_by_clerk_user_id = v_clerk_user_id
        then null
      else announcement.published_by_clerk_user_id
    end,
    withdrawn_by_clerk_user_id = case
      when announcement.withdrawn_by_clerk_user_id = v_clerk_user_id
        then null
      else announcement.withdrawn_by_clerk_user_id
    end
  where announcement.published_by_clerk_user_id = v_clerk_user_id
    or announcement.withdrawn_by_clerk_user_id = v_clerk_user_id;

  return public.close_ironclad_player_account_without_announcement_cleanup(
    v_clerk_user_id
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.close_ironclad_player_account_without_room_episodes(p_clerk_user_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare v_sub text := nullif(btrim(p_clerk_user_id), ''); v_result jsonb;
  v_previous text := current_setting('ironclad.match_room_account_closure', true);
begin
  if session_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'Account closure requires the trusted server boundary' using errcode = '42501';
  end if;
  if v_sub is null then raise exception 'Authenticated account identity is required' using errcode = '22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended('ironclad:match-room-actor:' || v_sub, 0));
  v_result := public.close_ironclad_player_account_without_match_rooms(v_sub);
  delete from public.match_room_reads where viewer_clerk_user_id = v_sub;
  perform set_config('ironclad.match_room_account_closure', 'on', true);
  update public.match_messages set actor_clerk_user_id = null where actor_clerk_user_id = v_sub;
  perform set_config('ironclad.match_room_account_closure', coalesce(v_previous, ''), true);
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.commit_match_replay_attempt_result(p_attempt_id uuid, p_finalization_claim_id uuid, p_match_id uuid, p_submitted_by_clerk_user_id text, p_replay_content_hashes text[], p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_attempt public.match_replay_upload_attempts%rowtype;
  v_tournament_id uuid;
  v_result jsonb;
  v_paths text[];
  v_now timestamptz := clock_timestamp();
begin
  select bracket.tournament_id
  into v_tournament_id
  from public.tournament_matches as match
  join public.generated_brackets as generated
    on generated.id = match.generated_bracket_id
  join public.tournament_brackets as bracket
    on bracket.id = generated.tournament_bracket_id
  where match.id = p_match_id
  for update of match;

  if not found then
    raise exception 'Tournament match not found';
  end if;

  select attempt.*
  into v_attempt
  from public.match_replay_upload_attempts as attempt
  where attempt.id = p_attempt_id
    and attempt.match_id = p_match_id
  for update;

  if not found then
    raise exception 'Replay attempt not found';
  end if;

  if not exists (
    select 1
    from public.registrations as registration
    where registration.id = v_attempt.submitting_registration_id
      and registration.clerk_user_id = p_submitted_by_clerk_user_id
  ) then
    raise exception 'Player does not own this replay attempt';
  end if;

  if v_attempt.status = 'committed' then
    return v_attempt.committed_result;
  end if;

  if v_attempt.status <> 'finalizing'
    or v_attempt.finalization_claim_id <> p_finalization_claim_id
    or v_attempt.finalization_lease_expires_at <= v_now then
    raise exception 'Replay finalization claim no longer owns this attempt';
  end if;

  perform public.assert_tournament_not_terminal(v_tournament_id);

  if cardinality(p_replay_content_hashes) <> v_attempt.required_replay_count then
    raise exception 'Replay hash count does not match this attempt';
  end if;

  v_paths := v_attempt.replay_storage_paths[1:v_attempt.required_replay_count];

  if cardinality(v_attempt.game_winner_registration_ids) = 0 then
    if least(v_attempt.player_one_score, v_attempt.player_two_score) > 0 then
      raise exception
        'Replay attempt predates per-game winner capture; resubmit this non-shutout result'
        using errcode = '55000';
    end if;

    -- A pre-deployment shutout is unambiguous: every game has one winner.
    v_result := public.submit_match_series_result_report(
      p_match_id,
      p_submitted_by_clerk_user_id,
      v_attempt.winner_registration_id,
      v_attempt.player_one_score,
      v_attempt.player_two_score,
      v_paths,
      p_replay_content_hashes,
      p_notes
    );
  else
    v_result := public.submit_match_series_result_report(
      p_match_id,
      p_submitted_by_clerk_user_id,
      v_attempt.winner_registration_id,
      v_attempt.player_one_score,
      v_attempt.player_two_score,
      v_paths,
      p_replay_content_hashes,
      v_attempt.game_winner_registration_ids,
      p_notes
    );
  end if;

  update public.match_replay_upload_attempts as attempt
  set
    status = 'committed',
    finalization_claim_id = null,
    finalization_lease_expires_at = null,
    committed_report_group_id = (v_result->>'report_group_id')::uuid,
    committed_result = v_result,
    committed_at = v_now,
    updated_at = v_now
  where attempt.id = v_attempt.id;

  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.complete_match_replay_attempt_cleanup(p_attempt_id uuid, p_cleanup_claim_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_attempt public.match_replay_upload_attempts%rowtype;
  v_now timestamptz := clock_timestamp();
begin
  select attempt.*
  into v_attempt
  from public.match_replay_upload_attempts as attempt
  where attempt.id = p_attempt_id
  for update;

  if not found then
    raise exception 'Replay attempt not found';
  end if;

  if v_attempt.status = 'cleaned' then
    return false;
  end if;

  if v_attempt.status <> 'cleaning'
    or v_attempt.cleanup_claim_id <> p_cleanup_claim_id then
    raise exception 'Replay cleanup claim no longer owns this attempt';
  end if;

  update public.match_replay_upload_attempts as attempt
  set
    status = 'cleaned',
    cleanup_claim_id = null,
    cleanup_lease_expires_at = null,
    cleaned_at = v_now,
    updated_at = v_now
  where attempt.id = v_attempt.id;

  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.complete_match_replay_attempt_recycling(p_attempt_id uuid, p_recycle_claim_id uuid, p_match_id uuid, p_submitted_by_clerk_user_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_attempt public.match_replay_upload_attempts%rowtype;
  v_match public.tournament_matches%rowtype;
  v_tournament_id uuid;
  v_launched_at timestamptz;
  v_wins_required integer;
  v_winner_score integer;
  v_loser_score integer;
  v_paths text[] := array[]::text[];
  v_index integer;
  v_now timestamptz := clock_timestamp();
begin
  if p_submitted_by_clerk_user_id is null
    or btrim(p_submitted_by_clerk_user_id) = '' then
    raise exception 'Submitting player is required';
  end if;

  select match.*
  into v_match
  from public.tournament_matches as match
  where match.id = p_match_id
  for update;

  if not found then
    raise exception 'This tournament match is not open for replay submission';
  end if;

  select bracket.tournament_id, bracket.launched_at
  into v_tournament_id, v_launched_at
  from public.tournament_matches as match
  join public.generated_brackets as generated
    on generated.id = match.generated_bracket_id
  join public.tournament_brackets as bracket
    on bracket.id = generated.tournament_bracket_id
  where match.id = v_match.id;

  if not found or v_launched_at is null then
    raise exception 'This tournament match is not open for replay submission';
  end if;

  select attempt.*
  into v_attempt
  from public.match_replay_upload_attempts as attempt
  where attempt.id = p_attempt_id
    and attempt.match_id = p_match_id
  for update;

  if not found then
    raise exception 'Replay attempt not found';
  end if;

  if not exists (
    select 1
    from public.registrations as registration
    where registration.id = v_attempt.submitting_registration_id
      and registration.clerk_user_id = p_submitted_by_clerk_user_id
  ) then
    raise exception 'Player does not own this replay attempt';
  end if;

  if v_attempt.status <> 'recycling'
    or v_attempt.recycle_claim_id <> p_recycle_claim_id
    or v_attempt.recycle_lease_expires_at <= v_now then
    raise exception 'Replay recycling claim no longer owns this attempt';
  end if;

  perform public.assert_tournament_not_terminal(v_tournament_id);

  if v_match.status = 'completed'
    or v_match.official_result_submission_id is not null then
    raise exception 'This match already has an official result';
  end if;

  if v_match.player_one_registration_id is null
    or v_match.player_two_registration_id is null
    or v_attempt.submitting_registration_id not in (
      v_match.player_one_registration_id,
      v_match.player_two_registration_id
    )
    or v_attempt.winner_registration_id not in (
      v_match.player_one_registration_id,
      v_match.player_two_registration_id
    ) then
    raise exception 'Replay attempt no longer matches this match';
  end if;

  v_wins_required := (v_match.series_best_of / 2) + 1;
  v_winner_score := case
    when v_attempt.winner_registration_id = v_match.player_one_registration_id
      then v_attempt.player_one_score
    else v_attempt.player_two_score
  end;
  v_loser_score := case
    when v_attempt.winner_registration_id = v_match.player_one_registration_id
      then v_attempt.player_two_score
    else v_attempt.player_one_score
  end;

  if v_winner_score <> v_wins_required or v_loser_score >= v_wins_required then
    raise exception 'The final score is invalid for this series';
  end if;

  if exists (
    select 1
    from public.match_result_report_groups as report_group
    where report_group.match_id = p_match_id
      and report_group.status in (
        'pending_confirmation',
        'disputed',
        'under_review'
      )
      and report_group.finalized_at is null
  ) or exists (
    select 1
    from public.match_result_submissions as submission
    where submission.match_id = p_match_id
      and submission.status = 'pending'
      and submission.report_group_id is null
  ) then
    raise exception 'This match already has active result activity';
  end if;

  for v_index in 1..5 loop
    v_paths := array_append(
      v_paths,
      format(
        '%s/%s/game-%s-%s.rec',
        p_match_id,
        v_attempt.id,
        v_index,
        gen_random_uuid()
      )
    );
  end loop;

  update public.match_replay_upload_attempts as attempt
  set
    replay_storage_paths = v_paths,
    status = 'prepared',
    capability_issued_at = v_now,
    capability_not_before_reuse_at = v_now + interval '2 hours 5 minutes',
    capability_issue_count = attempt.capability_issue_count + 1,
    recycle_claim_id = null,
    recycle_lease_expires_at = null,
    updated_at = v_now
  where attempt.id = v_attempt.id
  returning attempt.* into v_attempt;

  return jsonb_build_object(
    'outcome', 'prepared',
    'attempt_id', v_attempt.id,
    'replay_storage_paths',
      to_jsonb(v_attempt.replay_storage_paths[1:v_attempt.required_replay_count]),
    'required_replay_count', v_attempt.required_replay_count,
    'capability_issue_count', v_attempt.capability_issue_count
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.complete_tournament_on_match_result()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tournament_id uuid;
begin
  if tg_op = 'INSERT' then
    if new.status <> 'completed'
      or new.winner_registration_id is null then
      return new;
    end if;
  end if;

  if tg_op = 'UPDATE'
    and old.status is not distinct from new.status
    and old.winner_registration_id is not distinct from
      new.winner_registration_id then
    return new;
  end if;

  if tg_op = 'UPDATE'
    and new.status <> 'completed'
    and old.status <> 'completed'
    and new.winner_registration_id is null
    and old.winner_registration_id is null then
    return new;
  end if;

  select bracket.tournament_id
  into v_tournament_id
  from public.generated_brackets as generated
  join public.tournament_brackets as bracket
    on bracket.id = generated.tournament_bracket_id
  where generated.id = new.generated_bracket_id;

  if v_tournament_id is not null then
    perform public.recompute_tournament_lifecycle_status(v_tournament_id);
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.complete_transactional_email_notification(p_notification_id uuid, p_claim_token uuid, p_outcome text, p_error_code text DEFAULT NULL::text, p_provider_message_id text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_attempt_count integer;
  v_error_code text;
  v_next_attempt_at timestamptz;
  v_final_status text;
  v_now timestamptz;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'Not authorized';
  end if;

  if p_outcome not in (
    'sent',
    'skipped',
    'retryable_failure',
    'permanent_failure'
  ) then
    raise exception 'Invalid email completion outcome';
  end if;

  v_now := clock_timestamp();

  select notification.email_attempt_count
  into v_attempt_count
  from public.notifications as notification
  where notification.id = p_notification_id
    and notification.email_delivery_status = 'processing'
    and notification.email_claim_token = p_claim_token
    and notification.email_claim_expires_at > v_now
  for update;

  if not found then
    raise exception 'No active email claim';
  end if;

  if p_outcome = 'sent' then
    if nullif(btrim(p_provider_message_id), '') is null
      or length(p_provider_message_id) > 255
      or p_provider_message_id ~ '[[:cntrl:]]' then
      raise exception 'Invalid provider message ID';
    end if;

    v_final_status := 'sent';
    v_error_code := null;
    v_next_attempt_at := null;
  else
    v_error_code := case
      when p_error_code ~ '^[A-Z][A-Z0-9_]{0,63}$'
        then p_error_code
      else 'UNCLASSIFIED_FAILURE'
    end;

    if p_outcome = 'retryable_failure' and v_attempt_count >= 5 then
      v_final_status := 'permanent_failure';
      v_next_attempt_at := null;
    elsif p_outcome = 'retryable_failure' then
      v_final_status := 'retryable_failure';
      v_next_attempt_at := v_now + case v_attempt_count
        when 1 then interval '5 minutes'
        when 2 then interval '15 minutes'
        when 3 then interval '30 minutes'
        else interval '2 hours'
      end;
    else
      v_final_status := p_outcome;
      v_next_attempt_at := null;
    end if;
  end if;

  update public.notifications as notification
  set
    email_delivery_status = v_final_status,
    email_next_attempt_at = v_next_attempt_at,
    email_claim_token = null,
    email_claim_expires_at = null,
    email_sent_at = case
      when v_final_status = 'sent' then v_now
      else null
    end,
    email_last_error_code = v_error_code,
    email_provider_message_id = case
      when v_final_status = 'sent' then btrim(p_provider_message_id)
      else null
    end
  where notification.id = p_notification_id
    and notification.email_delivery_status = 'processing'
    and notification.email_claim_token = p_claim_token
    and notification.email_claim_expires_at > v_now;

  if not found then
    raise exception 'No active email claim';
  end if;

  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.complete_web_push_notification(p_notification_id uuid, p_claim_token uuid, p_outcome text, p_error_code text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_attempt_count integer;
  v_error_code text;
  v_final_status text;
  v_next_attempt_at timestamptz;
  v_now timestamptz;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'Not authorized' using errcode = '42501';
  end if;

  if p_outcome not in (
    'sent',
    'skipped',
    'retryable_failure',
    'permanent_failure'
  ) then
    raise exception 'Invalid Push completion outcome'
      using errcode = '22023';
  end if;

  v_now := clock_timestamp();

  select notification.push_attempt_count
  into v_attempt_count
  from public.notifications as notification
  where notification.id = p_notification_id
    and notification.push_delivery_status = 'processing'
    and notification.push_claim_token = p_claim_token
    and notification.push_claim_expires_at > v_now
  for update;

  if not found then
    raise exception 'No active Push claim' using errcode = '55000';
  end if;

  if p_outcome = 'sent' then
    v_final_status := 'sent';
    v_error_code := null;
    v_next_attempt_at := null;
  else
    v_error_code := case
      when p_error_code ~ '^[A-Z][A-Z0-9_]{0,63}$'
        then p_error_code
      else 'UNCLASSIFIED_FAILURE'
    end;

    if p_outcome = 'retryable_failure' and v_attempt_count >= 5 then
      v_final_status := 'permanent_failure';
      v_next_attempt_at := null;
    elsif p_outcome = 'retryable_failure' then
      v_final_status := 'retryable_failure';
      v_next_attempt_at := v_now + case v_attempt_count
        when 1 then interval '5 minutes'
        when 2 then interval '15 minutes'
        when 3 then interval '30 minutes'
        else interval '2 hours'
      end;
    else
      v_final_status := p_outcome;
      v_next_attempt_at := null;
    end if;
  end if;

  update public.notifications as notification
  set
    push_delivery_status = v_final_status,
    push_next_attempt_at = v_next_attempt_at,
    push_claim_token = null,
    push_claim_expires_at = null,
    push_completed_at = case
      when v_final_status in ('sent', 'skipped', 'permanent_failure')
        then v_now
      else null
    end,
    push_last_error_code = v_error_code
  where notification.id = p_notification_id
    and notification.push_delivery_status = 'processing'
    and notification.push_claim_token = p_claim_token
    and notification.push_claim_expires_at > v_now;

  if not found then
    raise exception 'No active Push claim' using errcode = '55000';
  end if;

  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.confirm_match_result_report_group(p_report_group_id uuid, p_confirmed_by_clerk_user_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_match_id uuid;
  v_match public.tournament_matches%rowtype;
  v_group public.match_result_report_groups%rowtype;
  v_active_group_id uuid;
  v_confirmer_registration_id uuid;
  v_affected integer;
begin
  if p_confirmed_by_clerk_user_id is null
    or pg_catalog.btrim(p_confirmed_by_clerk_user_id) = '' then
    raise exception 'Confirming player is required';
  end if;

  select report_group.match_id
  into v_match_id
  from public.match_result_report_groups as report_group
  where report_group.id = p_report_group_id;

  if not found then
    raise exception 'Match result report group not found';
  end if;

  select match.*
  into v_match
  from public.tournament_matches as match
  where match.id = v_match_id
  for update;

  if not found then
    raise exception 'Tournament match not found';
  end if;

  select report_group.*
  into v_group
  from public.match_result_report_groups as report_group
  where report_group.id = p_report_group_id
    and report_group.match_id = v_match.id
  for update;

  if not found
    or v_group.status <> 'pending_confirmation'
    or v_group.finalized_at is not null then
    raise exception using
      errcode = '40001',
      message = 'Match result conflict: this report group is no longer awaiting confirmation';
  end if;

  if v_match.status = 'completed'
    or v_match.official_result_submission_id is not null
    or v_match.winner_registration_id is not null
    or v_match.outcome_type is not null then
    raise exception using
      errcode = '40001',
      message = 'Match result conflict: the Match already has an authoritative outcome';
  end if;

  select report_group.id
  into v_active_group_id
  from public.match_result_report_groups as report_group
  where report_group.match_id = v_match.id
    and report_group.finalized_at is null
    and report_group.status in (
      'pending_confirmation',
      'disputed',
      'under_review'
    )
  order by report_group.created_at, report_group.id
  limit 1
  for update;

  if v_active_group_id is distinct from v_group.id then
    raise exception using
      errcode = '40001',
      message = 'Match result conflict: this is no longer the authoritative active report group';
  end if;

  if pg_catalog.now() >= v_group.confirmation_deadline_at then
    raise exception 'The confirmation window has expired';
  end if;

  select registration.id
  into v_confirmer_registration_id
  from public.registrations as registration
  where registration.id = v_group.opponent_registration_id
    and registration.clerk_user_id = p_confirmed_by_clerk_user_id;

  if v_confirmer_registration_id is null then
    raise exception 'Only the opponent can confirm this result';
  end if;

  update public.match_result_report_groups
  set
    confirmed_at = pg_catalog.now(),
    confirmed_by_registration_id = v_confirmer_registration_id
  where id = p_report_group_id
    and status = 'pending_confirmation'
    and finalized_at is null;

  get diagnostics v_affected = row_count;
  if v_affected <> 1 then
    raise exception using
      errcode = '40001',
      message = 'Match result conflict: confirmation did not update the active report group';
  end if;

  perform public.finalize_match_result_report_group(
    p_report_group_id,
    'confirmed',
    'opponent_confirmation',
    p_confirmed_by_clerk_user_id,
    null
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.correct_tournament_bracket_map_pool(p_tournament_bracket_id uuid, p_map_ids uuid[], p_reason text, p_explanation text, p_actor_clerk_user_id text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_actor text := nullif(btrim(p_actor_clerk_user_id), '');
  v_explanation text := nullif(btrim(p_explanation), '');
  v_tournament_id uuid;
  v_tournament_status text;
  v_launched_at timestamptz;
  v_map_count integer;
  v_eligible_map_count integer;
  v_correction_id uuid := pg_catalog.gen_random_uuid();
  v_corrected_at timestamptz := clock_timestamp();
begin
  if session_user <> 'postgres'
    and coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'Map-pool correction requires the trusted server boundary'
      using errcode = '42501';
  end if;

  if v_actor is null then
    raise exception 'Correcting administrator is required'
      using errcode = '22023';
  end if;

  if p_reason not in (
    'technical_issue',
    'exploit',
    'game_update',
    'competitive_integrity'
  ) then
    raise exception 'Select an approved correction reason';
  end if;

  if v_explanation is null or char_length(v_explanation) > 500 then
    raise exception 'Enter a correction explanation of 500 characters or fewer';
  end if;

  if coalesce(cardinality(p_map_ids), 0) < 5
    or array_position(p_map_ids, null) is not null then
    raise exception 'A corrected Division pool requires five distinct maps';
  end if;

  select count(distinct map_id)::integer
  into v_map_count
  from unnest(p_map_ids) as map_id;

  if v_map_count <> cardinality(p_map_ids) then
    raise exception 'A corrected Division pool cannot contain duplicate maps';
  end if;

  select bracket.tournament_id
  into v_tournament_id
  from public.tournament_brackets as bracket
  where bracket.id = p_tournament_bracket_id;

  if not found then
    raise exception 'Tournament Division not found';
  end if;

  select tournament.status
  into v_tournament_status
  from public.tournaments as tournament
  where tournament.id = v_tournament_id
  for update;

  if not found then
    raise exception 'Tournament not found';
  end if;

  select bracket.launched_at
  into v_launched_at
  from public.tournament_brackets as bracket
  where bracket.id = p_tournament_bracket_id
    and bracket.tournament_id = v_tournament_id
    and bracket.max_players = 8
    and bracket.map_pool_published_at is not null
  for update;

  if not found or v_launched_at is null then
    raise exception
      'Only a launched eight-player Division with a published pool can be corrected';
  end if;

  if v_tournament_status <> 'in_progress' then
    raise exception 'Only an active nonterminal tournament can be corrected';
  end if;

  perform entry.id
  from public.tournament_bracket_map_pool_entries as entry
  where entry.tournament_bracket_id = p_tournament_bracket_id
    and entry.removed_at is null
  order by entry.id
  for update;

  perform map.id
  from public.coh3_maps as map
  where map.id = any(p_map_ids)
  order by map.id
  for update;

  select
    count(*)::integer,
    count(*) filter (
      where map.status = 'active'
        and map.game_mode = '1v1'
    )::integer
  into v_map_count, v_eligible_map_count
  from public.coh3_maps as map
  where map.id = any(p_map_ids);

  if v_map_count <> cardinality(p_map_ids)
    or v_eligible_map_count <> cardinality(p_map_ids) then
    raise exception 'Corrected pools require existing active 1v1 maps only';
  end if;

  if not exists (
    (
      select current_entry.coh3_map_id
      from public.tournament_bracket_map_pool_entries as current_entry
      where current_entry.tournament_bracket_id = p_tournament_bracket_id
        and current_entry.removed_at is null
      except
      select map_id from unnest(p_map_ids) as map_id
    )
    union all
    (
      select map_id from unnest(p_map_ids) as map_id
      except
      select current_entry.coh3_map_id
      from public.tournament_bracket_map_pool_entries as current_entry
      where current_entry.tournament_bracket_id = p_tournament_bracket_id
        and current_entry.removed_at is null
    )
  ) then
    raise exception 'The corrected map pool must change at least one map';
  end if;

  insert into public.tournament_bracket_map_pool_corrections (
    id,
    tournament_bracket_id,
    actor_clerk_user_id,
    reason,
    explanation,
    created_at
  ) values (
    v_correction_id,
    p_tournament_bracket_id,
    v_actor,
    p_reason,
    v_explanation,
    v_corrected_at
  );

  update public.tournament_bracket_map_pool_entries as entry
  set
    removed_at = v_corrected_at,
    removed_by_correction_id = v_correction_id
  where entry.tournament_bracket_id = p_tournament_bracket_id
    and entry.removed_at is null
    and not (entry.coh3_map_id = any(p_map_ids));

  insert into public.tournament_bracket_map_pool_entries (
    tournament_bracket_id,
    coh3_map_id,
    added_at,
    added_by_correction_id
  )
  select
    p_tournament_bracket_id,
    map_id,
    v_corrected_at,
    v_correction_id
  from unnest(p_map_ids) as map_id
  where not exists (
    select 1
    from public.tournament_bracket_map_pool_entries as current_entry
    where current_entry.tournament_bracket_id = p_tournament_bracket_id
      and current_entry.coh3_map_id = map_id
      and current_entry.removed_at is null
  );

  return v_correction_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_match_result_report_group(p_match_id uuid, p_submitted_by_clerk_user_id text, p_winner_registration_id uuid, p_player_one_score integer, p_player_two_score integer, p_submission_ids uuid[] DEFAULT NULL::uuid[], p_replay_storage_path text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_match public.tournament_matches%rowtype;
  v_format text;
begin
  select match.*
  into v_match
  from public.tournament_matches as match
  where match.id = p_match_id
  for update;

  if not found then
    raise exception 'Tournament match not found';
  end if;

  select generated.format
  into v_format
  from public.generated_brackets as generated
  where generated.id = v_match.generated_bracket_id;

  if v_format = 'single_elimination' then
    if v_match.status <> 'in_progress'
      or v_match.activation_version < 1
      or v_match.deadline_at is null
      or v_match.outcome_type is not null
      or v_match.hold_started_at is not null
        and v_match.hold_released_at is null then
      raise exception 'This matchup is not currently actionable';
    end if;

    if clock_timestamp() >= v_match.deadline_at then
      raise exception 'The matchup deadline has passed';
    end if;
  end if;

  return public.create_match_result_report_group_without_matchup_deadline(
    p_match_id,
    p_submitted_by_clerk_user_id,
    p_winner_registration_id,
    p_player_one_score,
    p_player_two_score,
    p_submission_ids,
    p_replay_storage_path
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.create_match_result_report_group_without_matchup_deadline(p_match_id uuid, p_submitted_by_clerk_user_id text, p_winner_registration_id uuid, p_player_one_score integer, p_player_two_score integer, p_submission_ids uuid[] DEFAULT NULL::uuid[], p_replay_storage_path text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_match public.tournament_matches%rowtype;
  v_tournament_id uuid;
  v_reporter_registration_id uuid;
  v_opponent_registration_id uuid;
  v_confirmation_window_minutes integer;
  v_group_id uuid;
  v_existing_group_id uuid;
  v_distinct_submission_count integer;
  v_valid_submission_count integer;
  v_linked_replay_storage_path text;
  v_group_replay_storage_path text;
begin
  if p_submitted_by_clerk_user_id is null
    or btrim(p_submitted_by_clerk_user_id) = '' then
    raise exception 'Submitting player is required';
  end if;

  select match.*
  into v_match
  from public.tournament_matches as match
  where match.id = p_match_id
  for update;

  if not found then
    raise exception 'Tournament match not found';
  end if;

  if v_match.status = 'completed'
    or v_match.official_result_submission_id is not null then
    raise exception 'This match already has an official result';
  end if;

  if v_match.player_one_registration_id is null
    or v_match.player_two_registration_id is null then
    raise exception 'Both match participants must be assigned';
  end if;

  select bracket.tournament_id, tournament.result_confirmation_window_minutes
  into v_tournament_id, v_confirmation_window_minutes
  from public.generated_brackets as generated
  join public.tournament_brackets as bracket
    on bracket.id = generated.tournament_bracket_id
  join public.tournaments as tournament
    on tournament.id = bracket.tournament_id
  where generated.id = v_match.generated_bracket_id;

  if v_tournament_id is null then
    raise exception 'Tournament could not be resolved for this match';
  end if;

  select registration.id
  into v_reporter_registration_id
  from public.registrations as registration
  where registration.id in (
    v_match.player_one_registration_id,
    v_match.player_two_registration_id
  )
    and registration.clerk_user_id = p_submitted_by_clerk_user_id;

  if v_reporter_registration_id is null then
    raise exception 'Player is not a participant in this match';
  end if;

  v_opponent_registration_id := case
    when v_reporter_registration_id = v_match.player_one_registration_id
      then v_match.player_two_registration_id
    else v_match.player_one_registration_id
  end;

  if p_winner_registration_id not in (
    v_match.player_one_registration_id,
    v_match.player_two_registration_id
  ) then
    raise exception 'Winner must be a participant in this match';
  end if;

  select report_group.id
  into v_existing_group_id
  from public.match_result_report_groups as report_group
  where report_group.match_id = p_match_id
    and report_group.status in (
      'pending_confirmation',
      'disputed',
      'under_review'
    )
  order by report_group.created_at, report_group.id
  limit 1
  for update;

  if v_existing_group_id is not null then
    raise exception 'This match already has an active result report group';
  end if;

  if p_submission_ids is not null
    and cardinality(p_submission_ids) > 0 then
    select count(distinct submission_id.id)
    into v_distinct_submission_count
    from unnest(p_submission_ids) as submission_id(id);

    select count(*)
    into v_valid_submission_count
    from public.match_result_submissions as submission
    where submission.id = any(p_submission_ids)
      and submission.match_id = p_match_id
      and submission.submitted_by_registration_id =
        v_reporter_registration_id
      and submission.status = 'pending'
      and submission.report_group_id is null;

    if v_valid_submission_count <> v_distinct_submission_count then
      raise exception
        'One or more game submissions cannot be linked to this report group';
    end if;

    select submission.replay_storage_path
    into v_linked_replay_storage_path
    from public.match_result_submissions as submission
    where submission.id = any(p_submission_ids)
      and submission.replay_storage_path is not null
    order by submission.game_number, submission.created_at, submission.id
    limit 1;
  end if;

  v_group_replay_storage_path := coalesce(
    nullif(btrim(p_replay_storage_path), ''),
    v_linked_replay_storage_path
  );

  if v_group_replay_storage_path is null then
    raise exception 'Replay proof is required for result confirmation';
  end if;

  insert into public.match_result_report_groups (
    match_id,
    tournament_id,
    submitted_by_clerk_user_id,
    submitted_by_registration_id,
    opponent_registration_id,
    winner_registration_id,
    player_one_score,
    player_two_score,
    replay_storage_path,
    status,
    confirmation_deadline_at
  )
  values (
    p_match_id,
    v_tournament_id,
    p_submitted_by_clerk_user_id,
    v_reporter_registration_id,
    v_opponent_registration_id,
    p_winner_registration_id,
    p_player_one_score,
    p_player_two_score,
    v_group_replay_storage_path,
    'pending_confirmation',
    now() + make_interval(
      mins => coalesce(v_confirmation_window_minutes, 30)
    )
  )
  returning id into v_group_id;

  if p_submission_ids is not null
    and cardinality(p_submission_ids) > 0 then
    update public.match_result_submissions
    set report_group_id = v_group_id
    where id = any(p_submission_ids);
  end if;

  update public.tournament_matches
  set status = 'pending_review'
  where id = p_match_id
    and status in ('scheduled', 'in_progress');

  return v_group_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.current_poll_player_id()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_clerk_user_id text := nullif(auth.jwt() ->> 'sub', '');
  v_player_id uuid;
begin
  if coalesce(auth.role(), '') <> 'authenticated'
    or v_clerk_user_id is null then
    raise exception 'Poll unavailable' using errcode = '42501';
  end if;

  select player.id
  into v_player_id
  from public.players as player
  where player.clerk_user_id = v_clerk_user_id
    and player.account_closed_at is null;

  if not found then
    raise exception 'Poll unavailable' using errcode = '42501';
  end if;

  return v_player_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.delete_poll_draft(p_poll_id uuid, p_actor_clerk_user_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_actor text := nullif(pg_catalog.btrim(p_actor_clerk_user_id), '');
  v_poll public.polls%rowtype;
begin
  perform public.assert_poll_service_role();
  if v_actor is null then
    raise exception 'Poll administrator is required' using errcode = '22023';
  end if;

  select poll.* into v_poll
  from public.polls as poll
  where poll.id = p_poll_id
  for update;

  if not found then
    raise exception 'Poll not found';
  end if;
  if v_poll.published_at is not null then
    raise exception 'Published polls cannot be deleted'
      using errcode = '55000';
  end if;
  delete from public.polls where id = p_poll_id;

  return pg_catalog.jsonb_build_object(
    'poll_id', p_poll_id,
    'deleted', true
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.delete_web_push_subscription(p_clerk_user_id text, p_endpoint text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_clerk_user_id text := nullif(btrim(p_clerk_user_id), '');
  v_endpoint text := btrim(p_endpoint);
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'Not authorized' using errcode = '42501';
  end if;

  if v_clerk_user_id is null or v_endpoint = '' then
    raise exception 'Invalid subscription deletion' using errcode = '22023';
  end if;

  delete from public.push_subscriptions as subscription
  where subscription.owner_clerk_user_id = v_clerk_user_id
    and subscription.endpoint = v_endpoint;

  return found;
end;
$function$

CREATE OR REPLACE FUNCTION public.dispute_match_result_report_group(p_report_group_id uuid, p_disputed_by_clerk_user_id text, p_dispute_notes text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_match_id uuid;
  v_match public.tournament_matches%rowtype;
  v_group public.match_result_report_groups%rowtype;
  v_active_group_id uuid;
  v_disputer_registration_id uuid;
  v_affected integer;
begin
  if p_disputed_by_clerk_user_id is null
    or pg_catalog.btrim(p_disputed_by_clerk_user_id) = '' then
    raise exception 'Disputing player is required';
  end if;

  select report_group.match_id
  into v_match_id
  from public.match_result_report_groups as report_group
  where report_group.id = p_report_group_id;

  if not found then
    raise exception 'Match result report group not found';
  end if;

  select match.*
  into v_match
  from public.tournament_matches as match
  where match.id = v_match_id
  for update;

  if not found then
    raise exception 'Tournament match not found';
  end if;

  select report_group.*
  into v_group
  from public.match_result_report_groups as report_group
  where report_group.id = p_report_group_id
    and report_group.match_id = v_match.id
  for update;

  if not found
    or v_group.status <> 'pending_confirmation'
    or v_group.finalized_at is not null then
    raise exception using
      errcode = '40001',
      message = 'Match result conflict: this report group is no longer awaiting confirmation';
  end if;

  if v_match.status = 'completed'
    or v_match.official_result_submission_id is not null
    or v_match.winner_registration_id is not null
    or v_match.outcome_type is not null then
    raise exception using
      errcode = '40001',
      message = 'Match result conflict: the Match already has an authoritative outcome';
  end if;

  select report_group.id
  into v_active_group_id
  from public.match_result_report_groups as report_group
  where report_group.match_id = v_match.id
    and report_group.finalized_at is null
    and report_group.status in (
      'pending_confirmation',
      'disputed',
      'under_review'
    )
  order by report_group.created_at, report_group.id
  limit 1
  for update;

  if v_active_group_id is distinct from v_group.id then
    raise exception using
      errcode = '40001',
      message = 'Match result conflict: this is no longer the authoritative active report group';
  end if;

  if pg_catalog.now() >= v_group.confirmation_deadline_at then
    raise exception 'The confirmation window has expired';
  end if;

  select registration.id
  into v_disputer_registration_id
  from public.registrations as registration
  where registration.id = v_group.opponent_registration_id
    and registration.clerk_user_id = p_disputed_by_clerk_user_id;

  if v_disputer_registration_id is null then
    raise exception 'Only the opponent can dispute this result';
  end if;

  update public.match_result_report_groups
  set
    status = 'disputed',
    no_show_status = case
      when result_type = 'no_show' then 'disputed'
      else no_show_status
    end,
    disputed_at = pg_catalog.now(),
    disputed_by_registration_id = v_disputer_registration_id,
    dispute_notes = nullif(pg_catalog.btrim(p_dispute_notes), ''),
    reviewed_by = null,
    reviewed_at = null
  where id = p_report_group_id
    and status = 'pending_confirmation'
    and finalized_at is null;

  get diagnostics v_affected = row_count;
  if v_affected <> 1 then
    raise exception using
      errcode = '40001',
      message = 'Match result conflict: dispute did not update the active report group';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_registration_elo_eligibility()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_current_elo integer;
  v_bracket_name text;
  v_elo_rules text;
  v_is_eligible boolean;
  v_expected_division text;
  v_fixture_alias text;
  v_fixture_synthetic_elo integer;
  v_fixture_synthetic_division text;
  v_progression_synthetic_elo integer;
  v_progression_synthetic_division text;
begin
  if coalesce(current_setting('ironclad.account_closure', true), '') = 'on'
    and (
      session_user = 'postgres'
      or coalesce(auth.role(), '') = 'service_role'
    ) then
    return new;
  end if;

  if new.registration_status = 'rejected' then
    return new;
  end if;

  if new.registration_provenance = 'staging_synthetic_uat' then
    select
      fixture.approved_alias,
      fixture.synthetic_elo,
      fixture.synthetic_division,
      bracket.name
    into
      v_fixture_alias,
      v_fixture_synthetic_elo,
      v_fixture_synthetic_division,
      v_bracket_name
    from ironclad_private.staging_synthetic_uat_players as fixture
    join public.players as player on player.id = fixture.player_id
    join public.tournament_brackets as bracket
      on bracket.id = new.tournament_bracket_id
    where fixture.player_id = new.profile_id
      and player.clerk_user_id = new.clerk_user_id;

    if not found then
      raise exception 'Synthetic fixture registration identity is invalid';
    end if;

    select progression.synthetic_elo, progression.synthetic_division
    into v_progression_synthetic_elo, v_progression_synthetic_division
    from ironclad_private.staging_badge_cross_division_enrolments
      as progression
    where progression.registration_id = new.id;

    if found then
      v_fixture_synthetic_elo := v_progression_synthetic_elo;
      v_fixture_synthetic_division := v_progression_synthetic_division;
    elsif coalesce(
      current_setting(
        'ironclad.staging_badge_cross_division_enrolling',
        true
      ),
      ''
    ) = 'on' and v_fixture_alias = 'TestAcademy1' then
      select definition.synthetic_elo, definition.synthetic_division
      into v_fixture_synthetic_elo, v_fixture_synthetic_division
      from ironclad_private.staging_badge_cross_division_definition(
        v_bracket_name
      ) as definition;
    end if;

    v_expected_division := case v_bracket_name
      when 'Academy' then 'Academy'
      when 'Challenge' then 'Challenge'
      when 'Main' then 'Main / Pro'
      else null
    end;

    if v_expected_division is null
      or v_fixture_synthetic_division is distinct from
        v_expected_division then
      raise exception
        'Synthetic ELO does not match the selected tournament division';
    end if;

    new.submitted_elo := v_fixture_synthetic_elo;
    new.elo_status := 'manual_review';
    new.elo_verified_elo := null;
    new.elo_difference := null;
    new.elo_highest_faction := null;
    new.elo_checked_mode := null;
    new.elo_checked_at := null;
    new.elo_verification_source := null;
    new.elo_verification_error := null;
    new.elo_verification_payload := null;
    new.elo_verified_player_name := null;
    new.elo_identity_status := null;
    new.elo_identity_error := null;
    new.elo_verified_division := null;
    new.elo_calculation_version := null;
    return new;
  end if;

  if new.tournament_bracket_id is null or new.clerk_user_id is null then
    return new;
  end if;

  if new.elo_verification_source = 'relic' then
    select bracket.name
    into v_bracket_name
    from public.tournament_brackets as bracket
    where bracket.id = new.tournament_bracket_id;

    if not found then
      raise exception 'Selected tournament bracket does not exist';
    end if;

    v_expected_division := case v_bracket_name
      when 'Academy' then 'Academy'
      when 'Challenge' then 'Challenge'
      when 'Main' then 'Main / Pro'
      else null
    end;

    if v_expected_division is null
      or new.elo_verified_division is distinct from v_expected_division then
      raise exception
        'Verified ELO does not match the selected tournament division';
    end if;

    if new.submitted_elo is distinct from new.elo_verified_elo then
      raise exception 'Registration verification data is invalid';
    end if;

    return new;
  end if;

  if tg_op = 'UPDATE'
    and old.registration_status is distinct from new.registration_status
    and new.registration_status <> 'approved' then
    return new;
  end if;

  select player.current_elo, bracket.name, bracket.elo_rules
  into v_current_elo, v_bracket_name, v_elo_rules
  from public.players as player
  cross join public.tournament_brackets as bracket
  where player.clerk_user_id = new.clerk_user_id
    and bracket.id = new.tournament_bracket_id;

  if not found or v_current_elo is null then
    raise exception 'A completed player profile with current ELO is required';
  end if;

  v_is_eligible := public.is_elo_eligible(v_current_elo, v_elo_rules);

  if v_is_eligible is null then
    raise exception
      'The % Bracket has an invalid ELO rule configuration: %',
      v_bracket_name,
      v_elo_rules;
  end if;

  if not v_is_eligible then
    raise exception
      'Saved ELO % does not satisfy the % Bracket requirement: %',
      v_current_elo,
      v_bracket_name,
      v_elo_rules;
  end if;

  new.submitted_elo := v_current_elo;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_supported_tournament_format()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.format <> '1v1' then
