$function$

CREATE OR REPLACE FUNCTION public.export_match_room_privacy_data(p_player_id uuid, p_room_id uuid, p_after_sequence bigint, p_limit integer, p_actor_clerk_user_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET lock_timeout TO '2s'
 SET statement_timeout TO '60s'
AS $function$
declare v_rows jsonb; v_participant boolean;
begin
  perform ironclad_private.match_room_privacy_actor(p_actor_clerk_user_id);
  if p_player_id is null or p_room_id is null or p_limit is null or p_limit not between 1 and 500 or coalesce(p_after_sequence,0)<0 then
    raise exception 'Invalid privacy scope' using errcode='22023'; end if;
  select exists(select 1 from public.match_rooms r join public.registrations a
    on a.id in(r.player_one_registration_id,r.player_two_registration_id) where r.id=p_room_id and a.profile_id=p_player_id) into v_participant;
  if not v_participant and not exists(select 1 from public.match_messages where room_id=p_room_id and author_player_id=p_player_id) then
    raise exception 'Room is not linked to subject' using errcode='42501'; end if;
  select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'sequence',x.sequence,'senderKind',x.sender_kind,
    'isSubjectSender',coalesce(x.author_player_id=p_player_id,false),'body',x.body,'createdAt',x.created_at) order by x.sequence),'[]') into v_rows
  from (select m.* from public.match_messages m where m.room_id=p_room_id and m.sequence>coalesce(p_after_sequence,0)
    and (v_participant or m.author_player_id=p_player_id) order by m.sequence limit p_limit) x;
  return jsonb_build_object('roomId',p_room_id,'playerId',p_player_id,'messages',v_rows,
    'nextSequence',case when jsonb_array_length(v_rows)=p_limit then (v_rows->-1->>'sequence')::bigint end);
end $function$

CREATE OR REPLACE FUNCTION public.extend_tournament_match_deadline(p_match_id uuid, p_extension_minutes integer, p_reason text, p_actor_clerk_user_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_match public.tournament_matches%rowtype;
  v_extended_at timestamptz;
  v_deadline_at timestamptz;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'Not authorized';
  end if;

  if p_extension_minutes is null
    or p_extension_minutes < 1
    or p_extension_minutes > 2880 then
    raise exception 'Extension must be between 1 and 2880 minutes';
  end if;

  if nullif(btrim(p_reason), '') is null then
    raise exception 'An extension reason is required';
  end if;

  if length(p_reason) > 2000 then
    raise exception 'Extension reason must be 2000 characters or fewer';
  end if;

  if nullif(btrim(p_actor_clerk_user_id), '') is null then
    raise exception 'Approving administrator is required';
  end if;

  select match.*
  into v_match
  from public.tournament_matches as match
  where match.id = p_match_id
  for update;

  if not found then
    raise exception 'Tournament match not found';
  end if;

  if v_match.status <> 'in_progress'
    or v_match.activation_version < 1
    or v_match.deadline_at is null
    or v_match.outcome_type is not null
    or v_match.player_one_registration_id is null
    or v_match.player_two_registration_id is null then
    raise exception 'Only an active two-player matchup can be extended';
  end if;

  if v_match.extension_minutes is not null then
    raise exception 'This matchup has already used its extension';
  end if;

  if v_match.hold_started_at is not null
    and v_match.hold_released_at is null then
    raise exception 'Release the active administrative hold first';
  end if;

  if clock_timestamp() >= v_match.deadline_at then
    raise exception 'An expired matchup cannot be extended';
  end if;

  if exists (
    select 1
    from public.match_result_report_groups as report_group
    where report_group.match_id = p_match_id
      and report_group.status in (
        'pending_confirmation',
        'disputed',
        'under_review'
      )
      and report_group.finalized_at is null
  ) or exists (
    select 1
    from public.match_result_submissions as submission
    where submission.match_id = p_match_id
      and submission.status = 'pending'
  ) then
    raise exception 'Resolve the pending result workflow before extending';
  end if;

  v_extended_at := clock_timestamp();
  v_deadline_at := v_match.deadline_at
    + make_interval(mins => p_extension_minutes);

  update public.tournament_matches
  set
    deadline_at = v_deadline_at,
    extension_minutes = p_extension_minutes,
    extension_reason = btrim(p_reason),
    extended_at = v_extended_at,
    extended_by_clerk_user_id = btrim(p_actor_clerk_user_id)
  where id = p_match_id;

  perform public.create_matchup_notifications(
    p_match_id,
    'extension',
    'match.deadline_updated',
    'Match deadline extended',
    format(
      'An administrator added %s minute%s to this matchup. Your new deadline is shown in the match.',
      p_extension_minutes,
      case when p_extension_minutes = 1 then '' else 's' end
    ),
    jsonb_build_object(
      'deadlineEvent', 'deadline_updated',
      'updateKind', 'extension',
      'extensionMinutes', p_extension_minutes,
      'extendedAt', v_extended_at,
      'deadlineAt', v_deadline_at
    )
  );

  return jsonb_build_object(
    'match_id', p_match_id,
    'extension_minutes', p_extension_minutes,
    'extended_at', v_extended_at,
    'deadline_at', v_deadline_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.extract_coh3stats_profile_id(p_value text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare
  v_trimmed text;
  v_matches text[];
begin
  v_trimmed = nullif(btrim(p_value), '');

  if v_trimmed is null then
    return null;
  end if;

  if v_trimmed ~ '^[0-9]+$' then
    return v_trimmed;
  end if;

  v_matches = regexp_match(
    v_trimmed,
    '^https?://(www\.)?coh3stats\.com/players/([0-9]+)(/.*)?$',
    'i'
  );

  if v_matches is null then
    return null;
  end if;

  return v_matches[2];
end;
$function$

CREATE OR REPLACE FUNCTION public.finalize_poll_decision(p_poll_id uuid, p_selected_option_ids uuid[], p_rationale text, p_actor_clerk_user_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_actor text := nullif(pg_catalog.btrim(p_actor_clerk_user_id), '');
  v_rationale text := nullif(pg_catalog.btrim(p_rationale), '');
  v_poll public.polls%rowtype;
  v_now timestamptz;
  v_submitted_ballot_count integer;
  v_selected_count integer;
  v_valid_selected_count integer;
  v_selected_ids uuid[];
  v_computed_ids uuid[];
  v_safe_ids uuid[];
  v_cutoff_ids uuid[];
  v_outcome_ids uuid[];
  v_cutoff_count integer;
  v_safe_winner_count integer;
  v_cutoff_slots integer;
  v_cutoff_tie_count integer;
  v_selected_cutoff_count integer;
  v_has_cutoff_tie boolean := false;
  v_basis text;
  v_previous_finalization text :=
    current_setting('ironclad.poll_finalization', true);
  v_tournament_title text;
begin
  perform public.assert_poll_service_role();
  if v_actor is null then
    raise exception 'Poll administrator is required' using errcode = '22023';
  end if;
  if v_rationale is not null and char_length(v_rationale) > 1000 then
    raise exception 'Final rationale cannot exceed 1000 characters'
      using errcode = '22023';
  end if;

  select poll.*
  into v_poll
  from public.polls as poll
  where poll.id = p_poll_id
  for update;

  if not found then
    raise exception 'Poll not found';
  end if;
  v_now := pg_catalog.clock_timestamp();
  if v_poll.purpose <> 'tournament_decision'
    or v_poll.published_at is null
    or v_poll.cancelled_at is not null then
    raise exception 'Tournament Decision is unavailable for final publication'
      using errcode = '55000';
  end if;
  if v_now < v_poll.closes_at then
    raise exception 'A poll cannot be finalized before its database close time'
      using errcode = '55000';
  end if;
  if v_poll.final_decision_published_at is not null then
    raise exception 'Final poll decision is already published'
      using errcode = '55000';
  end if;

  select count(*) filter (
    where eligible.first_voted_at is not null
  )::integer
  into v_submitted_ballot_count
  from public.poll_eligible_voters as eligible
  where eligible.poll_id = p_poll_id;

  if v_poll.authority = 'binding' and v_submitted_ballot_count = 0 then
    raise exception 'Zero-ballot Binding polls must be cancelled and replaced'
      using errcode = '55000';
  end if;

  if coalesce(cardinality(p_selected_option_ids), 0) > 0 then
    if array_position(p_selected_option_ids, null) is not null then
      raise exception 'Final decision options are invalid'
        using errcode = '22023';
    end if;
    select count(distinct option_id)::integer,
      pg_catalog.array_agg(distinct option_id order by option_id)
    into v_selected_count, v_selected_ids
    from unnest(p_selected_option_ids) as option_id;
    if v_selected_count <> cardinality(p_selected_option_ids) then
      raise exception 'Final decision options must be distinct'
        using errcode = '22023';
    end if;
    select count(*)::integer
    into v_valid_selected_count
    from public.poll_options as option
    where option.poll_id = p_poll_id
      and option.id = any(v_selected_ids);
    if v_valid_selected_count <> v_selected_count then
      raise exception 'Final decision options are invalid'
        using errcode = '22023';
    end if;
  else
    v_selected_count := 0;
    v_selected_ids := array[]::uuid[];
  end if;

  with option_counts as (
    select option.id, option.position,
      count(choice.option_id)::integer as vote_count
    from public.poll_options as option
    left join public.poll_ballot_choices as choice
      on choice.poll_id = option.poll_id
      and choice.option_id = option.id
    where option.poll_id = p_poll_id
    group by option.id
  ), ranked as (
    select option_counts.*,
      row_number() over (
        order by option_counts.vote_count desc, option_counts.position
      )::integer as result_rank,
      dense_rank() over (
        order by option_counts.vote_count desc
      )::integer as vote_rank
    from option_counts
  )
  select pg_catalog.array_agg(ranked.id order by ranked.result_rank)
  into v_computed_ids
  from ranked
  where ranked.result_rank <= v_poll.winner_count;

  if v_poll.authority = 'advisory' then
    if v_selected_count <> v_poll.winner_count then
      raise exception 'Advisory final decisions require exactly winner_count options'
        using errcode = '22023';
    end if;

    -- Advisory Admins may publish any option set, but the unqualified poll
    -- result is the deterministic top-K set (votes DESC, published position).
    -- Choosing another set -- including another fill from an aggregate cutoff
    -- tie -- is an Admin override and therefore requires an explanation.
    if not (
      v_selected_ids @> v_computed_ids
      and v_computed_ids @> v_selected_ids
    ) then
      if v_rationale is null then
        raise exception 'An Advisory override requires a rationale'
          using errcode = '22023';
      end if;
      v_basis := 'advisory_admin_override';
    else
      v_basis := 'advisory_poll_result';
    end if;

    with option_counts as (
      select option.id, option.position,
        count(choice.option_id)::integer as vote_count
      from public.poll_options as option
      left join public.poll_ballot_choices as choice
        on choice.poll_id = option.poll_id
        and choice.option_id = option.id
      where option.poll_id = p_poll_id
      group by option.id
    )
    select pg_catalog.array_agg(
      option_counts.id
      order by option_counts.vote_count desc, option_counts.position
    )
    into v_outcome_ids
    from option_counts
    where option_counts.id = any(v_selected_ids);
  else
    with option_counts as (
      select option.id, option.position,
        count(choice.option_id)::integer as vote_count
      from public.poll_options as option
      left join public.poll_ballot_choices as choice
        on choice.poll_id = option.poll_id
        and choice.option_id = option.id
      where option.poll_id = p_poll_id
      group by option.id
    ), ranked as (
      select option_counts.*,
        row_number() over (
          order by option_counts.vote_count desc, option_counts.position
        )::integer as result_rank
      from option_counts
    )
    select ranked.vote_count
    into v_cutoff_count
    from ranked
    where ranked.result_rank = v_poll.winner_count;

    with option_counts as (
      select option.id, option.position,
        count(choice.option_id)::integer as vote_count
      from public.poll_options as option
      left join public.poll_ballot_choices as choice
        on choice.poll_id = option.poll_id
        and choice.option_id = option.id
      where option.poll_id = p_poll_id
      group by option.id
    )
    select coalesce(
        pg_catalog.array_agg(
          option_counts.id
          order by option_counts.vote_count desc, option_counts.position
        ) filter (where option_counts.vote_count > v_cutoff_count),
        array[]::uuid[]
      ),
      coalesce(
        pg_catalog.array_agg(
          option_counts.id order by option_counts.position
        ) filter (where option_counts.vote_count = v_cutoff_count),
        array[]::uuid[]
      )
    into v_safe_ids, v_cutoff_ids
    from option_counts;

    v_safe_winner_count := cardinality(v_safe_ids);
    v_cutoff_tie_count := cardinality(v_cutoff_ids);
    v_cutoff_slots := v_poll.winner_count - v_safe_winner_count;
    v_has_cutoff_tie := v_cutoff_tie_count > v_cutoff_slots;

    if v_has_cutoff_tie then
      if v_selected_count <> v_cutoff_slots
        or exists (
          select 1 from unnest(v_selected_ids) as selected_id
          where not (selected_id = any(v_cutoff_ids))
        ) then
        raise exception 'Cutoff tie selections must come only from the tied cutoff group'
          using errcode = '22023';
      end if;

      select count(*)::integer
      into v_selected_cutoff_count
      from unnest(v_selected_ids) as selected_id
      where selected_id = any(v_cutoff_ids);

      if v_selected_cutoff_count <> v_cutoff_slots then
        raise exception 'Select exactly enough tied cutoff options to fill the remaining winner slots'
          using errcode = '22023';
      end if;

      with option_counts as (
        select option.id, option.position,
          count(choice.option_id)::integer as vote_count
        from public.poll_options as option
        left join public.poll_ballot_choices as choice
          on choice.poll_id = option.poll_id
          and choice.option_id = option.id
        where option.poll_id = p_poll_id
        group by option.id
      )
      select pg_catalog.array_agg(
        option_counts.id
        order by option_counts.vote_count desc, option_counts.position
      )
      into v_outcome_ids
      from option_counts
      where option_counts.id = any(v_safe_ids)
        or option_counts.id = any(v_selected_ids);

      v_basis := 'binding_cutoff_tiebreak';
    else
      if v_selected_count <> 0 then
        raise exception 'Binding outcome is computed unless a cutoff tie requires Admin input'
          using errcode = '22023';
      end if;
      v_outcome_ids := v_computed_ids;
      v_basis := 'binding_computed';
    end if;
  end if;

  perform pg_catalog.set_config(
    'ironclad.poll_finalization',
    'on',
    true
  );

  update public.poll_options as option
  set final_decision_rank = pg_catalog.array_position(v_outcome_ids, option.id),
    final_decision_selected_at = v_now
  where option.poll_id = p_poll_id
    and option.id = any(v_outcome_ids);

  update public.polls
  set final_decision_basis = v_basis,
    final_rationale = v_rationale,
    binding_tie_rule_used = v_has_cutoff_tie,
    final_decision_published_at = v_now,
    final_decision_published_by_clerk_user_id = v_actor,
    updated_by_clerk_user_id = v_actor
  where id = p_poll_id;

  perform pg_catalog.set_config(
    'ironclad.poll_finalization',
    coalesce(v_previous_finalization, ''),
    true
  );

  select tournament.title
  into v_tournament_title
  from public.tournaments as tournament
  where tournament.id = v_poll.tournament_id;

  insert into public.notifications (
    recipient_clerk_user_id,
    recipient_role,
    type,
    title,
    message,
    tournament_id,
    tournament_title,
    metadata,
    event_key
  )
  select
    player.clerk_user_id,
    'player',
    'poll.decision_published',
    'Tournament decision published',
    pg_catalog.format('The final decision for "%s" is now available.', v_poll.question),
    v_poll.tournament_id,
    v_tournament_title,
    pg_catalog.jsonb_build_object(
      'pollId', p_poll_id,
      'purpose', v_poll.purpose,
      'tournamentId', v_poll.tournament_id
    ),
    pg_catalog.format('poll:%s:decision-published', p_poll_id)
  from public.poll_eligible_voters as eligible
  join public.players as player on player.id = eligible.player_id
  where eligible.poll_id = p_poll_id
    and v_poll.purpose = 'tournament_decision'
  order by player.id
  on conflict (recipient_clerk_user_id, event_key)
    where event_key is not null
  do nothing;

  return pg_catalog.jsonb_build_object(
    'poll_id', p_poll_id,
    'final_decision_published_at', v_now,
    'final_decision_basis', v_basis,
    'binding_tie_rule_used', v_has_cutoff_tie,
    'selected_option_ids', pg_catalog.to_jsonb(v_outcome_ids)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.generate_tournament_bracket(p_tournament_bracket_id uuid, p_generated_by text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_approved_count integer;
  v_unresolved_count integer;
  v_max_players integer;
  v_required_count integer;
  v_launched_at timestamptz;
  v_format text;
  v_generated_bracket_id uuid;
  v_round_id uuid;
  v_round_count integer;
  v_round_number integer;
  v_match_count integer;
  v_match_number integer;
  v_round_name text;
  v_first_slot integer;
  v_second_slot integer;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'Not authorized';
  end if;

  if p_generated_by is null or btrim(p_generated_by) = '' then
    raise exception 'Generating administrator is required';
  end if;

  select bracket.max_players, bracket.launched_at
  into v_max_players, v_launched_at
  from public.tournament_brackets as bracket
  where bracket.id = p_tournament_bracket_id
  for update;

  if not found then
    raise exception 'Tournament division not found';
  end if;

  if v_launched_at is not null then
    raise exception 'A launched division bracket cannot be regenerated';
  end if;

  if not public.is_tournament_bracket_regeneration_safe(
    p_tournament_bracket_id
  ) then
    raise exception
      'Bracket regeneration blocked because result activity exists';
  end if;

  v_required_count := least(v_max_players, 8);
  if v_required_count < 2 then
    raise exception 'Tournament division requires at least two players';
  end if;

  select
    count(*) filter (
      where registration.registration_status = 'approved'
    )::integer,
    count(*) filter (
      where registration.registration_status in (
        'pending',
        'manual_review'
      )
        or (
          registration.registration_status = 'waitlisted'
          and registration.waitlist_offer_status = 'offered'
        )
    )::integer
  into v_approved_count, v_unresolved_count
  from public.registrations as registration
  where registration.tournament_bracket_id = p_tournament_bracket_id;

  if v_approved_count <> v_required_count or v_unresolved_count <> 0 then
    raise exception
      'Private bracket generation requires exactly % approved players and no unresolved vacancy',
      v_required_count;
  end if;

  delete from public.generated_brackets
  where tournament_bracket_id = p_tournament_bracket_id;

  v_format := case
    when (v_required_count & (v_required_count - 1)) = 0
      then 'single_elimination'
    else 'round_robin'
  end;

  insert into public.generated_brackets (
    tournament_bracket_id,
    format,
    participant_count,
    slot_count,
    generated_by,
    competition_locked_at
  )
  values (
    p_tournament_bracket_id,
    v_format,
    v_required_count,
    v_required_count,
    p_generated_by,
    null
  )
  returning id into v_generated_bracket_id;

  if v_format = 'single_elimination' then
    v_round_count := log(2, v_required_count)::integer;

    for v_round_number in 1..v_round_count loop
      v_match_count :=
        v_required_count / power(2, v_round_number)::integer;
      v_round_name := case
        when v_match_count = 1 then 'Grand Final'
        when v_match_count = 2 then 'Semi Finals'
        when v_match_count = 4 then 'Quarter Finals'
        else 'Round of ' || (v_match_count * 2)::text
      end;

      insert into public.bracket_rounds (
        generated_bracket_id,
        round_number,
        name
      )
      values (
        v_generated_bracket_id,
        v_round_number,
        v_round_name
      )
      returning id into v_round_id;

      for v_match_number in 1..v_match_count loop
        v_first_slot := ((v_match_number - 1) * 2) + 1;
        v_second_slot := v_first_slot + 1;

        insert into public.tournament_matches (
          generated_bracket_id,
          round_id,
          match_number,
          player_one_slot,
          player_two_slot,
          player_one_registration_id,
          player_two_registration_id
        )
        values (
          v_generated_bracket_id,
          v_round_id,
          v_match_number,
          case when v_round_number = 1 then v_first_slot else null end,
          case when v_round_number = 1 then v_second_slot else null end,
          null,
          null
        );
      end loop;
    end loop;
  else
    insert into public.bracket_rounds (
      generated_bracket_id,
      round_number,
      name
    )
    values (v_generated_bracket_id, 1, 'Round Robin')
    returning id into v_round_id;

    v_match_number := 0;
    for v_first_slot in 1..(v_required_count - 1) loop
      for v_second_slot in (v_first_slot + 1)..v_required_count loop
        v_match_number := v_match_number + 1;
        insert into public.tournament_matches (
          generated_bracket_id,
          round_id,
          match_number,
          player_one_slot,
          player_two_slot,
          player_one_registration_id,
          player_two_registration_id
        )
        values (
          v_generated_bracket_id,
          v_round_id,
          v_match_number,
          v_first_slot,
          v_second_slot,
          null,
          null
        );
      end loop;
    end loop;
  end if;

  return v_generated_bracket_id;
end;
$function$

