  );
end;
$function$

CREATE OR REPLACE FUNCTION public.get_or_create_leaderboard_season(p_date date)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_context_tournament_text text;
  v_context_tournament_id uuid;
  v_date date := coalesce(p_date, current_date);
  v_year integer;
  v_season_number integer;
  v_season_id uuid;
begin
  perform public.leaderboard_require_write_access();
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('ironclad:leaderboard:all-time', 0)
  );

  v_context_tournament_text := nullif(
    pg_catalog.btrim(
      pg_catalog.current_setting(
        'ironclad.leaderboard_tournament_id',
        true
      )
    ),
    ''
  );

  if v_context_tournament_text is not null then
    begin
      v_context_tournament_id := v_context_tournament_text::uuid;
    exception
      when invalid_text_representation then
        raise exception 'Invalid internal leaderboard tournament context'
          using errcode = '22023';
    end;

    select membership.season_id
    into v_season_id
    from public.leaderboard_tournament_season_memberships as membership
    where membership.tournament_id = v_context_tournament_id
      and membership.voided_at is null;

    if v_season_id is not null then
      return v_season_id;
    end if;

    raise exception 'Valid leaderboard tournament membership was not assigned'
      using errcode = '55000';
  end if;

  select season.id
  into v_season_id
  from public.leaderboard_seasons as season
  where season.finalized_at is null
    and (
      select count(*)
      from public.leaderboard_tournament_season_memberships as membership
      where membership.season_id = season.id
        and membership.qualifying_event_number is not null
        and membership.voided_at is null
    ) < 6
  order by season.created_at, season.id
  limit 1;

  if v_season_id is not null then
    return v_season_id;
  end if;

  v_year := extract(year from v_date)::integer;

  select coalesce(max(season.season_number), 0) + 1
  into v_season_number
  from public.leaderboard_seasons as season
  where season.year = v_year;

  insert into public.leaderboard_seasons (
    name,
    year,
    season_number,
    start_date,
    end_date,
    is_active
  )
  values (
    v_year::text || ' Main/Pro Season ' || v_season_number::text,
    v_year,
    v_season_number,
    v_date,
    v_date,
    true
  )
  returning id into v_season_id;

  return v_season_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_not_held_division_child_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_old_bracket_id uuid;
  v_new_bracket_id uuid;
  v_bracket_id uuid;
begin
  if tg_op <> 'INSERT' then
    v_old_bracket_id := old.tournament_bracket_id;
  end if;
  if tg_op <> 'DELETE' then
    v_new_bracket_id := new.tournament_bracket_id;
  end if;

  for v_bracket_id in
    select distinct candidate.bracket_id
    from pg_catalog.unnest(
      array[v_old_bracket_id, v_new_bracket_id]
    ) as candidate(bracket_id)
    where candidate.bracket_id is not null
    order by candidate.bracket_id
  loop
    perform bracket.id
    from public.tournament_brackets as bracket
    where bracket.id = v_bracket_id
    for update;

    if exists (
      select 1
      from public.tournament_division_not_held_closures as closure
      where closure.tournament_bracket_id = v_bracket_id
    ) then
      raise exception 'Competition structure is immutable after a Division is Not Held'
        using errcode = '55000';
    end if;
  end loop;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_not_held_division_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
begin
  if tg_op = 'DELETE' and exists (
    select 1
    from public.tournament_division_not_held_closures as closure
    where closure.tournament_bracket_id = old.id
  ) then
    raise exception 'A Not Held Division cannot be deleted'
      using errcode = '55000';
  end if;

  if tg_op = 'UPDATE' and exists (
    select 1
    from public.tournament_division_not_held_closures as closure
    where closure.tournament_bracket_id = old.id
  ) and (
    pg_catalog.to_jsonb(new) - 'updated_at'
  ) is distinct from (
    pg_catalog.to_jsonb(old) - 'updated_at'
  ) then
    raise exception 'A Not Held Division is immutable'
      using errcode = '55000';
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_not_held_registration_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_old_bracket_id uuid;
  v_new_bracket_id uuid;
  v_bracket_id uuid;
  v_account_closure boolean :=
    (
      session_user = 'postgres'
      or coalesce(auth.role(), '') = 'service_role'
    )
    and coalesce(
      pg_catalog.current_setting('ironclad.account_closure', true),
      ''
    ) = 'on';
begin
  if v_account_closure then
    if tg_op = 'DELETE' then
      return old;
    end if;
    return new;
  end if;

  if tg_op <> 'INSERT' then
    v_old_bracket_id := old.tournament_bracket_id;
  end if;
  if tg_op <> 'DELETE' then
    v_new_bracket_id := new.tournament_bracket_id;
  end if;

  for v_bracket_id in
    select distinct candidate.bracket_id
    from pg_catalog.unnest(
      array[v_old_bracket_id, v_new_bracket_id]
    ) as candidate(bracket_id)
    where candidate.bracket_id is not null
    order by candidate.bracket_id
  loop
    perform bracket.id
    from public.tournament_brackets as bracket
    where bracket.id = v_bracket_id
    for update;

    if exists (
      select 1
      from public.tournament_division_not_held_closures as closure
      where closure.tournament_bracket_id = v_bracket_id
    ) then
      raise exception 'Registrations are immutable after a Division is Not Held'
        using errcode = '55000';
    end if;
  end loop;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_open_player_badge_award()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
begin
  if not exists (
    select 1
    from public.players as player
    where player.id = new.player_id
      and player.account_closed_at is null
  ) then
    raise exception 'Badge ownership cannot be created for a closed account'
      using errcode = '42501';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_player_account_closure_state()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_account_closure boolean :=
    coalesce(
      current_setting('ironclad.account_closure', true),
      ''
    ) = 'on'
    and (
      session_user = 'postgres'
      or coalesce(auth.role(), '') = 'service_role'
    );
begin
  if tg_op = 'INSERT' then
    if new.account_closed_at is not null then
      raise exception 'Account closure state is database-controlled'
        using errcode = '42501';
    end if;

    return new;
  end if;

  if old.account_closed_at is not null and not v_account_closure then
    raise exception 'Closed historical player identity is immutable'
      using errcode = '55000';
  end if;

  if new.account_closed_at is distinct from old.account_closed_at
    and not v_account_closure then
    raise exception 'Account closure state is database-controlled'
      using errcode = '42501';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_poll_ballot_choice_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_poll_id uuid := case when tg_op = 'DELETE' then old.poll_id else new.poll_id end;
  v_poll public.polls%rowtype;
  v_choice_count integer;
begin
  select poll.*
  into v_poll
  from public.polls as poll
  where poll.id = v_poll_id;

  if not found
    or v_poll.published_at is null
    or v_poll.cancelled_at is not null
    or pg_catalog.clock_timestamp() < v_poll.opens_at
    or pg_catalog.clock_timestamp() >= v_poll.closes_at then
    raise exception 'Poll voting is unavailable'
      using errcode = '42501';
  end if;

  if tg_op = 'INSERT' then
    select count(*)::integer + 1
    into v_choice_count
    from public.poll_ballot_choices as choice
    where choice.eligible_voter_id = new.eligible_voter_id;

    if v_choice_count > v_poll.max_selections then
      raise exception 'Ballot exceeds the poll selection limit'
        using errcode = '22023';
    end if;
    return new;
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_poll_eligibility_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_poll_id uuid := case when tg_op = 'DELETE' then old.poll_id else new.poll_id end;
  v_published_at timestamptz;
  v_account_closure boolean :=
    coalesce(current_setting('ironclad.account_closure', true), '') = 'on'
    and (
      session_user = 'postgres'
      or coalesce(auth.role(), '') = 'service_role'
    );
begin
  select poll.published_at
  into v_published_at
  from public.polls as poll
  where poll.id = v_poll_id;

  if v_published_at is null then
    if tg_op = 'DELETE' then
      return old;
    end if;
    return new;
  end if;

  if tg_op <> 'UPDATE' then
    raise exception 'Published poll eligibility is immutable'
      using errcode = '55000';
  end if;

  if old.id is distinct from new.id
    or old.poll_id is distinct from new.poll_id
    or old.eligible_at is distinct from new.eligible_at
    or old.created_at is distinct from new.created_at then
    raise exception 'Published poll eligibility is immutable'
      using errcode = '55000';
  end if;

  if old.player_id is distinct from new.player_id and not (
    v_account_closure
    and old.player_id is not null
    and new.player_id is null
  ) then
    raise exception 'Published poll voter identity is immutable'
      using errcode = '55000';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_poll_option_configuration()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_poll_id uuid := case when tg_op = 'DELETE' then old.poll_id else new.poll_id end;
