CREATE OR REPLACE FUNCTION public.guard_staging_synthetic_uat_registration()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_fixture ironclad_private.staging_synthetic_uat_players%rowtype;
  v_expected_elo integer;
  v_expected_division text;
  v_bracket_name text;
begin
  if coalesce(current_setting('ironclad.account_closure', true), '') = 'on'
    and (
      session_user = 'postgres'
      or coalesce(auth.role(), '') = 'service_role'
    ) then
    return new;
  end if;

  if tg_op = 'INSERT'
    and new.registration_provenance is distinct from
      'staging_synthetic_uat' then
    return new;
  end if;

  if tg_op = 'UPDATE' then
    if old.registration_provenance is null
      and new.registration_provenance is null
      and old.fixture_contract_version is null
      and new.fixture_contract_version is null then
      return new;
    end if;

    if old.registration_provenance is distinct from
        'staging_synthetic_uat'
      or old.fixture_contract_version is distinct from
        'staging-synthetic-v1'
      or new.registration_provenance is distinct from
        old.registration_provenance
      or new.fixture_contract_version is distinct from
        old.fixture_contract_version then
      raise exception 'Synthetic fixture registration provenance is immutable'
        using errcode = '55000';
    end if;
  elsif coalesce(
    current_setting('ironclad.staging_synthetic_uat_enrolling', true),
    ''
  ) <> 'on' or coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'Synthetic fixture registration is unavailable'
      using errcode = '42501';
  end if;

  select fixture.*
  into v_fixture
  from ironclad_private.staging_synthetic_uat_players as fixture
  join public.players as player on player.id = fixture.player_id
  where fixture.player_id = new.profile_id
    and player.clerk_user_id = new.clerk_user_id;

  if not found then
    raise exception 'Synthetic fixture registration facts are invalid'
      using errcode = '23514';
  end if;

  select bracket.name
  into v_bracket_name
  from public.tournament_brackets as bracket
  where bracket.id = new.tournament_bracket_id;

  if not found then
    raise exception 'Synthetic fixture registration facts are invalid'
      using errcode = '23514';
  end if;

  select progression.synthetic_elo, progression.synthetic_division
  into v_expected_elo, v_expected_division
  from ironclad_private.staging_badge_cross_division_enrolments
    as progression
  where progression.registration_id = new.id;

  if not found
    and coalesce(
      current_setting(
        'ironclad.staging_badge_cross_division_enrolling',
        true
      ),
      ''
    ) = 'on'
    and v_fixture.approved_alias = 'TestAcademy1' then
    select definition.synthetic_elo, definition.synthetic_division
    into v_expected_elo, v_expected_division
    from ironclad_private.staging_badge_cross_division_definition(
      v_bracket_name
    ) as definition;
  end if;

  if v_expected_elo is null then
    v_expected_elo := v_fixture.synthetic_elo;
    v_expected_division := v_fixture.synthetic_division;
  end if;

  if new.registration_provenance is distinct from
      'staging_synthetic_uat'
    or new.fixture_contract_version is distinct from
      'staging-synthetic-v1'
    or new.submitted_elo is distinct from v_expected_elo
    or new.elo_status is distinct from 'manual_review'
    or new.steam_name is not null
    or new.coh3_player_card_url is not null
    or new.elo_verified_elo is not null
    or new.elo_difference is not null
    or new.elo_highest_faction is not null
    or new.elo_checked_mode is not null
    or new.elo_checked_at is not null
    or new.elo_verification_source is not null
    or new.elo_verification_error is not null
    or new.elo_verification_payload is not null
    or new.elo_verified_player_name is not null
    or new.elo_identity_status is not null
    or new.elo_identity_error is not null
    or new.elo_verified_division is not null
    or new.elo_calculation_version is not null then
    raise exception 'Synthetic fixture registration facts are invalid'
      using errcode = '23514';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_terminal_competition_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_tournament_id uuid;
  v_old_tournament_id uuid;
  v_new_tournament_id uuid;
  v_trusted_caller boolean :=
    session_user = 'postgres'
    or coalesce(auth.role(), '') = 'service_role';
begin
  if v_trusted_caller and (
    coalesce(
      pg_catalog.current_setting('ironclad.tournament_deletion', true),
      ''
    ) = 'on'
    or coalesce(
      pg_catalog.current_setting('ironclad.account_closure', true),
      ''
    ) = 'on'
  ) then
    if tg_op = 'DELETE' then
      return old;
    end if;
    return new;
  end if;

  if tg_table_name = 'registrations' then
    if tg_op <> 'INSERT' then
      v_old_tournament_id := old.tournament_id;
    end if;
    if tg_op <> 'DELETE' then
      v_new_tournament_id := new.tournament_id;
    end if;
  elsif tg_table_name = 'tournament_brackets' then
    if tg_op <> 'INSERT' then
      v_old_tournament_id := old.tournament_id;
    end if;
    if tg_op <> 'DELETE' then
      v_new_tournament_id := new.tournament_id;
    end if;
  elsif tg_table_name = 'generated_brackets' then
    if tg_op <> 'INSERT' then
      select bracket.tournament_id
      into v_old_tournament_id
      from public.tournament_brackets as bracket
      where bracket.id = old.tournament_bracket_id;
    end if;
    if tg_op <> 'DELETE' then
      select bracket.tournament_id
      into v_new_tournament_id
      from public.tournament_brackets as bracket
      where bracket.id = new.tournament_bracket_id;
    end if;
  elsif tg_table_name = 'bracket_rounds' then
    if tg_op <> 'INSERT' then
      select bracket.tournament_id
      into v_old_tournament_id
      from public.generated_brackets as generated
      join public.tournament_brackets as bracket
        on bracket.id = generated.tournament_bracket_id
      where generated.id = old.generated_bracket_id;
    end if;
    if tg_op <> 'DELETE' then
      select bracket.tournament_id
      into v_new_tournament_id
      from public.generated_brackets as generated
      join public.tournament_brackets as bracket
        on bracket.id = generated.tournament_bracket_id
      where generated.id = new.generated_bracket_id;
    end if;
  elsif tg_table_name in ('tournament_matches', 'tournament_standings') then
    if tg_op <> 'INSERT' then
      select bracket.tournament_id
      into v_old_tournament_id
      from public.generated_brackets as generated
      join public.tournament_brackets as bracket
        on bracket.id = generated.tournament_bracket_id
      where generated.id = old.generated_bracket_id;
    end if;
    if tg_op <> 'DELETE' then
      select bracket.tournament_id
      into v_new_tournament_id
      from public.generated_brackets as generated
      join public.tournament_brackets as bracket
        on bracket.id = generated.tournament_bracket_id
      where generated.id = new.generated_bracket_id;
    end if;
  elsif tg_table_name in (
    'match_result_submissions',
    'match_result_report_groups'
  ) then
    if tg_op <> 'INSERT' then
      select bracket.tournament_id
      into v_old_tournament_id
      from public.tournament_matches as match
      join public.generated_brackets as generated
        on generated.id = match.generated_bracket_id
      join public.tournament_brackets as bracket
        on bracket.id = generated.tournament_bracket_id
      where match.id = old.match_id;
    end if;
    if tg_op <> 'DELETE' then
      select bracket.tournament_id
      into v_new_tournament_id
      from public.tournament_matches as match
      join public.generated_brackets as generated
        on generated.id = match.generated_bracket_id
      join public.tournament_brackets as bracket
        on bracket.id = generated.tournament_bracket_id
      where match.id = new.match_id;
    end if;
  end if;

  for v_tournament_id in
    select distinct candidate.tournament_id
    from unnest(array[v_old_tournament_id, v_new_tournament_id])
      as candidate(tournament_id)
    where candidate.tournament_id is not null
  loop
    if coalesce(
      pg_catalog.current_setting('ironclad.terminal_worker_skip', true),
      ''
    ) = 'on' and v_trusted_caller and exists (
      select 1
      from public.tournaments as tournament
      where tournament.id = v_tournament_id
        and tournament.status in ('cancelled', 'voided')
    ) then
      return null;
    end if;

    perform public.assert_tournament_not_terminal(v_tournament_id);
  end loop;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_tournament_map_pool_terminal_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_old_bracket_id uuid;
  v_new_bracket_id uuid;
  v_tournament_id uuid;
  v_trusted_bypass boolean :=
    (session_user = 'postgres' or coalesce(auth.role(), '') = 'service_role')
    and (
      coalesce(current_setting('ironclad.tournament_deletion', true), '') = 'on'
      or coalesce(current_setting('ironclad.account_closure', true), '') = 'on'
    );
begin
  if v_trusted_bypass then
    if tg_op = 'DELETE' then
      return old;
    end if;
    return new;
  end if;

  if tg_op <> 'INSERT' then
    v_old_bracket_id := old.tournament_bracket_id;
  end if;
  if tg_op <> 'DELETE' then
    v_new_bracket_id := new.tournament_bracket_id;
  end if;

  for v_tournament_id in
    select distinct bracket.tournament_id
    from public.tournament_brackets as bracket
    where bracket.id = any(array[v_old_bracket_id, v_new_bracket_id])
  loop
    perform public.assert_tournament_not_terminal(v_tournament_id);
  end loop;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_tournament_terminal_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_terminal_transition boolean :=
    coalesce(
      pg_catalog.current_setting(
        'ironclad.tournament_terminal_transition',
        true
      ),
      ''
    ) = 'on'
    and (
      session_user = 'postgres'
      or coalesce(auth.role(), '') = 'service_role'
    );
  v_account_closure boolean :=
    coalesce(
      pg_catalog.current_setting('ironclad.account_closure', true),
      ''
    ) = 'on'
    and (
      session_user = 'postgres'
      or coalesce(auth.role(), '') = 'service_role'
    );
begin
  if old.status in ('cancelled', 'voided') then
    if new.status is distinct from old.status then
      raise exception 'A terminal tournament cannot be reopened or changed'
        using errcode = '55000';
    end if;

    if (
      new.terminal_at is distinct from old.terminal_at
      or new.terminal_reason is distinct from old.terminal_reason
      or new.terminated_by_clerk_user_id is distinct from
        old.terminated_by_clerk_user_id
    ) and not v_account_closure then
      raise exception 'Tournament terminal metadata is immutable'
        using errcode = '55000';
    end if;

    new.registration_enabled := false;
    return new;
  end if;

  if new.status in ('cancelled', 'voided') and not v_terminal_transition then
    raise exception 'Use the protected tournament recovery operation'
      using errcode = '55000';
  end if;

  if new.status in ('cancelled', 'voided') then
    new.registration_enabled := false;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.hold_tournament_match_deadline(p_match_id uuid, p_reason text, p_actor_clerk_user_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_match public.tournament_matches%rowtype;
  v_started_at timestamptz;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'Not authorized';
  end if;

  if nullif(btrim(p_reason), '') is null then
    raise exception 'An administrative hold reason is required';
  end if;

  if length(p_reason) > 2000 then
    raise exception 'Hold reason must be 2000 characters or fewer';
  end if;

  if nullif(btrim(p_actor_clerk_user_id), '') is null then
    raise exception 'Holding administrator is required';
  end if;

  select match.*
  into v_match
  from public.tournament_matches as match
  where match.id = p_match_id
  for update;

  if not found then
    raise exception 'Tournament match not found';
  end if;

  if v_match.status <> 'in_progress'
    or v_match.activation_version < 1
    or v_match.deadline_at is null
    or v_match.outcome_type is not null
    or v_match.player_one_registration_id is null
    or v_match.player_two_registration_id is null then
    raise exception 'Only an active two-player matchup can be held';
  end if;

  if v_match.hold_started_at is not null then
    raise exception 'This matchup has already used its administrative hold';
  end if;

  if clock_timestamp() >= v_match.deadline_at then
    raise exception 'An expired matchup cannot be held';
  end if;

  if exists (
    select 1
    from public.match_result_report_groups as report_group
    where report_group.match_id = p_match_id
      and report_group.status in (
        'pending_confirmation',
        'disputed',
        'under_review'
      )
      and report_group.finalized_at is null
  ) or exists (
    select 1
    from public.match_result_submissions as submission
    where submission.match_id = p_match_id
      and submission.status = 'pending'
  ) then
    raise exception 'Resolve the pending result workflow before holding';
  end if;

  v_started_at := clock_timestamp();

  update public.tournament_matches
  set
    hold_started_at = v_started_at,
    hold_reason = btrim(p_reason),
    held_by_clerk_user_id = btrim(p_actor_clerk_user_id)
  where id = p_match_id;

  perform public.create_matchup_notifications(
    p_match_id,
    'hold:started',
    'match.deadline_updated',
    'Match deadline paused',
    'An administrator paused this matchup deadline. Reminders and automatic enforcement are suspended.',
    jsonb_build_object(
      'deadlineEvent', 'deadline_updated',
      'updateKind', 'hold',
      'holdStartedAt', v_started_at
    )
  );

  return jsonb_build_object(
    'match_id', p_match_id,
    'hold_started_at', v_started_at,
    'deadline_at', v_match.deadline_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.initialize_transactional_email_state()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_registration public.registrations%rowtype;
  v_match public.tournament_matches%rowtype;
  v_match_context record;
  v_round_number integer;
  v_round_name text;
  v_max_round_number integer;
  v_bracket_id uuid;
  v_tournament_id uuid;
  v_format text;
  v_launched_at timestamptz;
  v_feeders_valid boolean;
  v_reminder_ordinal integer;
  v_template_key text;
  v_now timestamptz;
begin
  -- Defaults never make an ordinary notification eligible. Only the exact
  -- canonical branches below may repopulate this private state.
  new.email_template_key := null;
  new.email_delivery_status := null;
  new.email_attempt_count := null;
  new.email_next_attempt_at := null;
  new.email_claim_token := null;
  new.email_claim_expires_at := null;
  new.email_sent_at := null;
  new.email_last_error_code := null;
  new.email_provider_message_id := null;

  if nullif(btrim(new.event_key), '') is null then
    return new;
  end if;

  if new.type = 'registration.approved'
    and new.registration_id is not null
    and new.tournament_id is not null
    and nullif(btrim(new.recipient_clerk_user_id), '') is not null
    and new.recipient_role = 'player'
    and new.event_key = format(
      'registration:%s:approved',
      new.registration_id
    ) then
    select registration.*
    into v_registration
    from public.registrations as registration
    where registration.id = new.registration_id
      and registration.tournament_id = new.tournament_id
      and registration.clerk_user_id = new.recipient_clerk_user_id
      and registration.registration_status = 'approved';

    if found
      and v_registration.tournament_bracket_id is not null
      and new.metadata ->> 'nextStatus' = 'approved'
      and new.metadata ->> 'previousStatus' in (
        'pending',
        'manual_review',
        'rejected',
        'waitlisted',
        'withdrawn'
      )
      and new.metadata -> 'registrationId' = to_jsonb(v_registration.id)
      and new.metadata -> 'tournamentId' =
        to_jsonb(v_registration.tournament_id)
      and new.metadata -> 'bracketId' =
        to_jsonb(v_registration.tournament_bracket_id)
      and new.metadata ->> 'bracketName' is not distinct from
        v_registration.bracket_name then
      v_template_key := 'registration_approved';
    end if;
  elsif new.type in ('match.ready', 'match.deadline_reminder')
    and new.match_id is not null
    and new.registration_id is not null
    and new.tournament_id is not null
    and nullif(btrim(new.recipient_clerk_user_id), '') is not null
    and new.recipient_role = 'player' then
    select
      tournament_match as match_row,
      round.round_number as round_number,
      round.name as round_name,
      (
        select max(candidate_round.round_number)
        from public.bracket_rounds as candidate_round
        where candidate_round.generated_bracket_id =
          tournament_match.generated_bracket_id
      ) as max_round_number,
      bracket.id as bracket_id,
      bracket.tournament_id as tournament_id,
      generated.format as bracket_format,
      bracket.launched_at as launched_at
    into v_match_context
    from public.tournament_matches as tournament_match
    join public.bracket_rounds as round
      on round.id = tournament_match.round_id
      and round.generated_bracket_id =
        tournament_match.generated_bracket_id
    join public.generated_brackets as generated
      on generated.id = tournament_match.generated_bracket_id
    join public.tournament_brackets as bracket
      on bracket.id = generated.tournament_bracket_id
    where tournament_match.id = new.match_id
      and bracket.launched_at is not null
      and tournament_match.player_one_registration_id is not null
      and tournament_match.player_two_registration_id is not null
      and tournament_match.outcome_type is null
      and tournament_match.deadline_ruled_at is null;

    if not found then
      return new;
    end if;

    v_match := v_match_context.match_row;
    v_round_number := v_match_context.round_number;
    v_round_name := v_match_context.round_name;
    v_max_round_number := v_match_context.max_round_number;
    v_bracket_id := v_match_context.bracket_id;
    v_tournament_id := v_match_context.tournament_id;
    v_format := v_match_context.bracket_format;
    v_launched_at := v_match_context.launched_at;

    if v_format <> 'single_elimination'
      or v_launched_at is null
      or v_match.status <> 'in_progress'
      -- Version one is the normal activation. Administrative reopen/reset
      -- activations increment it and must remain in-app only.
      or v_match.activation_version <> 1
      or v_match.activated_at is null
      or v_match.deadline_at is null
      or v_match.player_one_registration_id is null
      or v_match.player_two_registration_id is null
      or v_match.player_one_registration_id =
        v_match.player_two_registration_id
      or v_match.outcome_type is not null
      or v_match.deadline_ruled_at is not null
      or v_match.player_one_score is not null
      or v_match.player_two_score is not null
      or v_match.winner_registration_id is not null
      or v_match.official_result_submission_id is not null
      or v_match.official_result_decided_by is not null
      or v_match.official_result_decided_at is not null
      or v_match.hold_started_at is not null
        and v_match.hold_released_at is null
      or new.tournament_id is distinct from v_tournament_id
      or new.metadata -> 'tournamentId' is distinct from
        to_jsonb(v_tournament_id)
      or new.metadata -> 'bracketId' is distinct from to_jsonb(v_bracket_id)
      or new.metadata -> 'matchId' is distinct from to_jsonb(v_match.id)
      or new.metadata -> 'activationVersion' is distinct from
        to_jsonb(v_match.activation_version)
      or new.metadata ->> 'roundName' is distinct from v_round_name
      or not exists (
        select 1
        from public.registrations as recipient
        where recipient.id = new.registration_id
          and recipient.clerk_user_id = new.recipient_clerk_user_id
          and recipient.id in (
            v_match.player_one_registration_id,
            v_match.player_two_registration_id
          )
      ) then
      return new;
    end if;

    if new.type = 'match.ready' then
      if new.event_key <> format(
          'match:%s:activation:%s:ready',
          v_match.id,
          v_match.activation_version
        )
        or new.metadata ->> 'deadlineEvent' is distinct from 'ready'
        or new.metadata -> 'roundNumber' is distinct from
          to_jsonb(v_round_number)
        or new.metadata -> 'activatedAt' is distinct from
          to_jsonb(v_match.activated_at)
        or new.metadata -> 'deadlineAt' is distinct from
          to_jsonb(v_match.deadline_at)
        or new.metadata ? 'reopened'
        or exists (
          select 1
          from public.match_result_report_groups as report_group
          where report_group.match_id = v_match.id
        )
        or exists (
          select 1
          from public.match_result_submissions as submission
          where submission.match_id = v_match.id
        ) then
        return new;
      end if;

      if v_round_number = 1 then
        v_template_key := 'division_started_first_match';
      elsif v_round_number > 1
        and v_round_number >= v_max_round_number - 1 then
        select
          count(*) = 2
          and bool_and(
            (
              feeder.match_number = (v_match.match_number * 2) - 1
              and feeder.winner_registration_id =
                v_match.player_one_registration_id
            )
            or (
              feeder.match_number = v_match.match_number * 2
              and feeder.winner_registration_id =
                v_match.player_two_registration_id
            )
          )
        into v_feeders_valid
        from public.bracket_rounds as prior_round
        join public.tournament_matches as feeder
          on feeder.round_id = prior_round.id
          and feeder.generated_bracket_id =
            v_match.generated_bracket_id
          and feeder.match_number in (
            (v_match.match_number * 2) - 1,
            v_match.match_number * 2
          )
        where prior_round.generated_bracket_id =
            v_match.generated_bracket_id
          and prior_round.round_number = v_round_number - 1
          and feeder.status = 'completed'
          and feeder.outcome_type is null
          and feeder.deadline_ruled_at is null
          and feeder.winner_registration_id is not null;

        if coalesce(v_feeders_valid, false) then
          v_template_key := 'later_round_match_ready';
        end if;
      end if;
    elsif new.type = 'match.deadline_reminder' then
      if new.metadata -> 'reminderOrdinal' = to_jsonb(1) then
        v_reminder_ordinal := 1;
      elsif new.metadata -> 'reminderOrdinal' = to_jsonb(2) then
        v_reminder_ordinal := 2;
      else
        return new;
      end if;

      if new.event_key <> format(
          'match:%s:activation:%s:reminder:%s',
          v_match.id,
          v_match.activation_version,
          v_reminder_ordinal
        )
        or new.metadata ->> 'deadlineEvent' is distinct from 'reminder'
        or new.metadata -> 'deadlineAt' is distinct from
          to_jsonb(v_match.deadline_at)
        or exists (
          select 1
          from public.match_result_report_groups as report_group
          where report_group.match_id = v_match.id
            and (
              (
                report_group.status in (
                  'pending_confirmation',
                  'disputed',
                  'under_review'
                )
                and report_group.finalized_at is null
              )
              or report_group.status in (
                'confirmed',
                'auto_approved',
                'approved'
              )
            )
        )
        or exists (
          select 1
          from public.match_result_submissions as submission
          where submission.match_id = v_match.id
            and submission.status = 'pending'
        ) then
        return new;
      end if;

      v_now := clock_timestamp();
      if v_reminder_ordinal = 1
        and v_match.deadline_at > v_now + interval '24 hours'
        and v_match.deadline_at <= v_now + interval '72 hours' then
        v_template_key := 'deadline_reminder_72h';
      elsif v_reminder_ordinal = 2
        and v_match.deadline_at > v_now
        and v_match.deadline_at <= v_now + interval '24 hours' then
        v_template_key := 'deadline_reminder_24h';
      end if;
    end if;
  end if;

  if v_template_key is not null then
    new.email_template_key := v_template_key;
    new.email_delivery_status := 'pending';
    new.email_attempt_count := 0;
    new.email_next_attempt_at := clock_timestamp();
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.initialize_web_push_state()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_eligible boolean := false;
  v_now timestamptz;
begin
  -- Historical rows and ordinary in-site-only notifications remain null.
  -- Only this trigger can enroll a newly inserted canonical notification.
  new.push_delivery_status := null;
  new.push_attempt_count := null;
  new.push_next_attempt_at := null;
  new.push_claim_token := null;
  new.push_claim_expires_at := null;
  new.push_enqueued_at := null;
  new.push_completed_at := null;
  new.push_last_error_code := null;

  if nullif(btrim(new.event_key), '') is null then
    return new;
  end if;

  if new.recipient_role = 'admin'
    and new.recipient_clerk_user_id is null
    and new.type in (
      'match.dispute_opened',
      'match.no_show_disputed',
      'match.admin_assistance_requested'
    ) then
    v_eligible := true;
  elsif new.recipient_role = 'player'
    and nullif(btrim(new.recipient_clerk_user_id), '') is not null
    and (
      new.type in (
        'registration.approved',
        'registration.rejected',
        'registration.waitlist_offer',
        'registration.waitlist_closed',
        'tournament.cancelled',
        'tournament.voided',
        'match.ready',
        'match.message_received',
        'match.automatic_advance',
        'match.deadline_updated',
        'match.deadline_reminder',
        'match.deadline_ruling',
        'match.confirmation_required',
        'match.no_show_reported',
        'match.no_show_confirmed',
        'match.no_show_disputed',
        'match.no_show_approved',
        'match.no_show_rejected',
        'match.no_show_review_required',
        'match.result_approved',
        'match.result_review_required',
        'poll.decision_published'
      )
      or (
        new.type = 'poll.published'
        and new.metadata ->> 'purpose' = 'tournament_decision'
      )
    ) then
    v_eligible := true;
  end if;

  if not v_eligible then
    return new;
  end if;

  v_now := clock_timestamp();
  new.push_delivery_status := 'pending';
  new.push_attempt_count := 0;
  new.push_next_attempt_at := v_now;
  new.push_enqueued_at := v_now;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.invoke_transactional_email_worker()
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_worker_url text;
  v_worker_secret text;
  v_vercel_bypass_secret text;
begin
  select secret.decrypted_secret
  into v_worker_url
  from vault.decrypted_secrets as secret
  where secret.name = 'ironclad_transactional_email_worker_url'
  limit 1;

  select secret.decrypted_secret
  into v_worker_secret
  from vault.decrypted_secrets as secret
  where secret.name = 'ironclad_transactional_email_worker_secret'
  limit 1;

  select secret.decrypted_secret
  into v_vercel_bypass_secret
  from vault.decrypted_secrets as secret
  where secret.name = 'ironclad_transactional_email_vercel_bypass_secret'
  limit 1;

  v_worker_url := nullif(btrim(v_worker_url), '');
  v_worker_secret := nullif(btrim(v_worker_secret), '');
  v_vercel_bypass_secret := nullif(btrim(v_vercel_bypass_secret), '');

  if v_worker_url is null
    or v_worker_secret is null
    or v_vercel_bypass_secret is null then
    return null;
  end if;

  if v_worker_url !~
      '^https://[^/?#@[:space:]]+/api/internal/transactional-email$'
    or position('?' in v_worker_url) > 0
    or position('#' in v_worker_url) > 0
    or position('@' in v_worker_url) > 0 then
    return null;
  end if;

  return net.http_post(
    url := v_worker_url,
    headers := jsonb_build_object(
      'Authorization', 'Bearer ' || v_worker_secret,
      'Content-Type', 'application/json',
      'x-vercel-protection-bypass', v_vercel_bypass_secret
    ),
    body := jsonb_build_object('source', 'pg_cron'),
    timeout_milliseconds := 70000
  );
end;
$function$

