CREATE OR REPLACE FUNCTION public.is_elo_eligible(p_current_elo integer, p_elo_rules text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare
  v_rule text;
  v_match text[];
  v_minimum integer;
  v_maximum integer;
begin
  if p_current_elo is null or p_elo_rules is null then
    return null;
  end if;

  v_rule := lower(
    btrim(
      regexp_replace(
        replace(
          replace(
            replace(p_elo_rules, ',', ''),
            chr(8211),
            '-'
          ),
          chr(8212),
          '-'
        ),
        '[[:space:]]+',
        ' ',
        'g'
      )
    )
  );

  if v_rule in (
    'open',
    'any elo',
    'all elo',
    'all ratings',
    'no elo restriction',
    'unrestricted'
  ) then
    return true;
  end if;

  v_match := regexp_match(
    v_rule,
    '([0-9]+)[[:space:]]*(-|to|through)[[:space:]]*([0-9]+)'
  );
  if v_match is not null then
    v_minimum := v_match[1]::integer;
    v_maximum := v_match[3]::integer;
    if v_minimum > v_maximum then
      return null;
    end if;
    return p_current_elo between v_minimum and v_maximum;
  end if;

  v_match := regexp_match(
    v_rule,
    '(>=|at least|minimum|min)[[:space:]]*(elo[[:space:]]*)?([0-9]+)'
  );
  if v_match is not null then
    return p_current_elo >= v_match[3]::integer;
  end if;

  v_match := regexp_match(
    v_rule,
    '([0-9]+)[[:space:]]*(\+|and (above|higher)|or (above|higher))'
  );
  if v_match is not null then
    return p_current_elo >= v_match[1]::integer;
  end if;

  v_match := regexp_match(
    v_rule,
    '(>|above|over)[[:space:]]*(elo[[:space:]]*)?([0-9]+)'
  );
  if v_match is not null then
    return p_current_elo > v_match[3]::integer;
  end if;

  v_match := regexp_match(
    v_rule,
    '(<=|at most|maximum|max)[[:space:]]*(elo[[:space:]]*)?([0-9]+)'
  );
  if v_match is not null then
    return p_current_elo <= v_match[3]::integer;
  end if;

  v_match := regexp_match(
    v_rule,
    '([0-9]+)[[:space:]]*(and (below|under)|or (below|under))'
  );
  if v_match is not null then
    return p_current_elo <= v_match[1]::integer;
  end if;

  v_match := regexp_match(
    v_rule,
    '(<|below|under|less than)[[:space:]]*(elo[[:space:]]*)?([0-9]+)'
  );
  if v_match is not null then
    return p_current_elo < v_match[3]::integer;
  end if;

  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.is_generated_bracket_complete(p_generated_bracket_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_format text;
  v_match_count integer;
  v_incomplete_count integer;
  v_final_completed boolean;
begin
  select generated.format
  into v_format
  from public.generated_brackets as generated
  where generated.id = p_generated_bracket_id;

  if not found then
    return false;
  end if;

  if v_format = 'round_robin' then
    select
      count(*)::integer,
      count(*) filter (
        where match.status <> 'completed'
          or match.winner_registration_id is null
      )::integer
    into v_match_count, v_incomplete_count
    from public.tournament_matches as match
    where match.generated_bracket_id = p_generated_bracket_id;

    return v_match_count > 0 and v_incomplete_count = 0;
  end if;

  select
    match.status = 'completed'
      and (
        match.winner_registration_id is not null
        or match.outcome_type in (
          'deadline_double_forfeit',
          'empty_feeder'
        )
      )
  into v_final_completed
  from public.tournament_matches as match
  join public.bracket_rounds as round
    on round.id = match.round_id
  where match.generated_bracket_id = p_generated_bracket_id
  order by round.round_number desc, match.match_number desc
  limit 1;

  return coalesce(v_final_completed, false);
end;
$function$

CREATE OR REPLACE FUNCTION public.launch_tournament_division(p_tournament_bracket_id uuid, p_actor_clerk_user_id text)
 RETURNS TABLE(tournament_id uuid, tournament_bracket_id uuid, launched_at timestamp with time zone, already_launched boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_launch record;
  v_generated_bracket_id uuid;
  v_match_id uuid;
  v_max_players integer;
  v_map_pool_published_at timestamptz;
  v_entry_count integer;
  v_distinct_map_count integer;
  v_eligible_map_count integer;
begin
  select result.*
  into v_launch
  from public.launch_tournament_division_without_matchup_activation(
    p_tournament_bracket_id,
    p_actor_clerk_user_id
  ) as result;

  if not found then
    raise exception 'Division launch did not return a result';
  end if;

  if not v_launch.already_launched then
    select
      bracket.max_players,
      bracket.map_pool_published_at
    into
      v_max_players,
      v_map_pool_published_at
    from public.tournament_brackets as bracket
    where bracket.id = p_tournament_bracket_id;

    if v_max_players <> 8 then
      raise exception 'Division launch capacity must be exactly eight players';
    end if;

    if v_map_pool_published_at is null then
      raise exception 'Publish the Division map pool before launch';
    end if;

    perform entry.id
    from public.tournament_bracket_map_pool_entries as entry
    where entry.tournament_bracket_id = p_tournament_bracket_id
      and entry.removed_at is null
    order by entry.id
    for update;

    perform map.id
    from public.coh3_maps as map
    join public.tournament_bracket_map_pool_entries as entry
      on entry.coh3_map_id = map.id
    where entry.tournament_bracket_id = p_tournament_bracket_id
      and entry.removed_at is null
    order by map.id
    for update of map;

    select
      count(*)::integer,
      count(distinct entry.coh3_map_id)::integer,
      count(*) filter (
        where map.status = 'active'
          and map.game_mode = '1v1'
      )::integer
    into
      v_entry_count,
      v_distinct_map_count,
      v_eligible_map_count
    from public.tournament_bracket_map_pool_entries as entry
    join public.coh3_maps as map
      on map.id = entry.coh3_map_id
    where entry.tournament_bracket_id = p_tournament_bracket_id
      and entry.removed_at is null;

    if v_entry_count < 5
      or v_distinct_map_count <> v_entry_count
      or v_eligible_map_count <> v_entry_count then
      raise exception
        'Division launch requires at least five distinct active 1v1 pool maps';
    end if;
  end if;

  select generated.id
  into v_generated_bracket_id
  from public.generated_brackets as generated
  where generated.tournament_bracket_id = p_tournament_bracket_id;

  for v_match_id in
    select match.id
    from public.tournament_matches as match
    join public.bracket_rounds as round
      on round.id = match.round_id
    where match.generated_bracket_id = v_generated_bracket_id
      and round.round_number = 1
    order by match.match_number, match.id
  loop
    perform public.activate_tournament_match_if_ready(v_match_id, false);
  end loop;

  tournament_id := v_launch.tournament_id;
  tournament_bracket_id := v_launch.tournament_bracket_id;
  launched_at := v_launch.launched_at;
  already_launched := v_launch.already_launched;
  return next;
end;
$function$

CREATE OR REPLACE FUNCTION public.leaderboard_require_write_access()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
begin
  if session_user = 'postgres' or pg_catalog.pg_trigger_depth() > 0 then
    return;
  end if;

  if coalesce(auth.role(), '') = 'service_role' then
    return;
  end if;

  if coalesce(auth.role(), '') = 'authenticated'
    and public.is_admin_jwt() then
    return;
  end if;

  raise exception 'Leaderboard administrator permission is required'
    using errcode = '42501';
end;
$function$

CREATE OR REPLACE FUNCTION public.link_match_room_retention_case(p_room_id uuid, p_case_reference uuid, p_case_kind text, p_closed_at timestamp with time zone, p_actor_clerk_user_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET lock_timeout TO '2s'
 SET statement_timeout TO '60s'
AS $function$
declare v_actor uuid;
begin
  v_actor:=ironclad_private.match_room_privacy_actor(p_actor_clerk_user_id);
  if p_case_reference is null or p_case_kind is null or p_case_kind not in('support','complaint','privacy','abuse_security','dispute','no_show','competition_integrity')
    or p_closed_at>now() then raise exception 'Invalid authoritative case metadata' using errcode='22023'; end if;
  perform ironclad_private.lock_match_room_privacy(p_room_id);
  perform ironclad_private.match_room_privacy_actor(p_actor_clerk_user_id);
  if exists(select 1 from ironclad_private.match_room_retention_cases where room_id=p_room_id and case_reference=p_case_reference and case_kind<>p_case_kind) then
    raise exception 'Case kind is immutable' using errcode='22023'; end if;
  insert into ironclad_private.match_room_retention_cases(room_id,case_reference,case_kind,closed_at)
    values(p_room_id,p_case_reference,p_case_kind,p_closed_at)
  on conflict(room_id,case_reference) do update set closed_at=excluded.closed_at,updated_at=clock_timestamp();
  insert into ironclad_private.match_room_privacy_audit(room_id,operation,actor_player_id,reference_id)
    values(p_room_id,'case_link',v_actor,p_case_reference);
  return jsonb_build_object('roomId',p_room_id,'caseReference',p_case_reference,'caseKind',p_case_kind,'closedAt',p_closed_at);
end $function$

CREATE OR REPLACE FUNCTION public.list_admin_polls(p_tournament_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_polls jsonb;
begin
  perform public.assert_poll_service_role();

  select coalesce(
    pg_catalog.jsonb_agg(
      public.build_poll_payload(poll.id, null, 'admin')
      order by poll.created_at desc, poll.id
    ),
    '[]'::jsonb
  )
  into v_polls
  from public.polls as poll
  where p_tournament_id is null or poll.tournament_id = p_tournament_id;

  return pg_catalog.jsonb_build_object('polls', v_polls);
end;
$function$

CREATE OR REPLACE FUNCTION public.list_match_room_assistance_requests(p_limit integer DEFAULT 200)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare v_requests jsonb; v_count bigint;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'Not authorized' using errcode = '42501';
  end if;
  if p_limit is null or p_limit not between 1 and 5000 then
    raise exception 'Invalid assistance list limit' using errcode = '22023';
  end if;
  -- Count and page share one statement snapshot, including under concurrent
  -- resolution/reopening; an overflow remains explicit in totalCount.
  with requested as materialized (
    select * from public.match_room_assistance where status = 'requested'
  ), limited as (
    select * from requested order by requested_at, room_id limit p_limit
  ), projected as (
    select a.room_id, a.requested_at, jsonb_build_object(
      'roomId', a.room_id, 'matchId', r.match_id, 'tournamentId', reg.tournament_id,
      'tournamentTitle', coalesce(t.title, reg.tournament_title, 'Tournament'),
      'status', a.status, 'requestVersion', a.request_version, 'requestedAt', a.requested_at
    ) row_data
    from limited a join public.match_rooms r on r.id = a.room_id
    left join public.registrations reg on reg.id = r.player_one_registration_id
    left join public.tournaments t on t.id = reg.tournament_id
  )
  select (select count(*) from requested),
    coalesce((select jsonb_agg(row_data order by requested_at, room_id) from projected), '[]'::jsonb)
  into v_count, v_requests;
  return jsonb_build_object('requests', v_requests, 'totalCount', v_count);
end;
$function$

CREATE OR REPLACE FUNCTION public.mark_announcement_seen(p_clerk_user_id text, p_announcement_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_clerk_user_id text := nullif(btrim(p_clerk_user_id), '');
  v_announcement public.announcements%rowtype;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'Announcement state is unavailable'
      using errcode = '42501';
  end if;

  if v_clerk_user_id is null or p_announcement_id is null then
    raise exception 'Announcement state is unavailable'
      using errcode = '22023';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'ironclad:announcement-account:' || v_clerk_user_id,
      0
    )
  );

  select announcement.*
  into v_announcement
  from public.announcements as announcement
  where announcement.id = p_announcement_id
    and announcement.withdrawn_at is null;

  if not found then
    return pg_catalog.jsonb_build_object('marked', false);
  end if;

  insert into public.announcement_read_states as read_state (
    clerk_user_id,
    last_seen_announcement_id,
    last_seen_published_at,
    updated_at
  ) values (
    v_clerk_user_id,
    v_announcement.id,
    v_announcement.published_at,
    clock_timestamp()
  )
  on conflict (clerk_user_id) do update
  set
    last_seen_announcement_id = excluded.last_seen_announcement_id,
    last_seen_published_at = excluded.last_seen_published_at,
    updated_at = excluded.updated_at
  where (
    read_state.last_seen_published_at,
    read_state.last_seen_announcement_id
  ) < (
    excluded.last_seen_published_at,
    excluded.last_seen_announcement_id
  );

  return pg_catalog.jsonb_build_object(
    'marked', true,
    'latest', pg_catalog.jsonb_build_object(
      'id', v_announcement.id,
      'published_at', v_announcement.published_at
    )
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.mark_match_room_read(p_room_id uuid, p_through_sequence bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare v_sub text := ironclad_private.match_room_actor(); v_room public.match_rooms%rowtype; v_last bigint; v_episode record;
begin
  if p_room_id is null or p_through_sequence is null or p_through_sequence < 0 then
    raise exception 'Invalid Match Room read cursor' using errcode = '22023';
  end if;
  perform ironclad_private.require_match_room_enabled();
  v_room := ironclad_private.match_room_access(p_room_id, v_sub);
  if p_through_sequence > v_room.last_sequence then
    raise exception 'Read cursor is ahead of the room' using errcode = '22023';
  end if;
  insert into public.match_room_reads(room_id, viewer_clerk_user_id, last_read_sequence)
  values(p_room_id, v_sub, p_through_sequence)
  on conflict (room_id, viewer_clerk_user_id) do update
    set last_read_sequence = greatest(match_room_reads.last_read_sequence, excluded.last_read_sequence),
      updated_at = clock_timestamp()
  returning last_read_sequence into v_last;
  if v_last >= v_room.last_sequence then
    for v_episode in
      update public.match_room_notification_episodes e set resolved_at = clock_timestamp()
      where e.room_id = p_room_id and e.resolved_at is null and exists (
        select 1 from public.registrations r where r.id = e.recipient_registration_id and r.clerk_user_id = v_sub
      ) returning notification_id
    loop
      perform ironclad_private.finish_match_room_notification(v_episode.notification_id);
    end loop;
  end if;
  return jsonb_build_object('roomId', p_room_id, 'lastReadSequence', v_last);
end;
$function$

CREATE OR REPLACE FUNCTION public.match_replay_attempt_paths_are_valid(p_match_id uuid, p_attempt_id uuid, p_paths text[])
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_index integer;
begin
  if cardinality(p_paths) <> 5
    or array_position(p_paths, null) is not null
    or (
      select count(distinct replay.path)
      from unnest(p_paths) as replay(path)
    ) <> 5 then
    return false;
  end if;

  for v_index in 1..5 loop
    if p_paths[v_index] !~ (
      '^' || p_match_id::text || '/' || p_attempt_id::text
      || '/game-' || v_index::text
      || '-[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}'
      || '-[89ab][0-9a-f]{3}-[0-9a-f]{12}\.rec$'
    ) then
      return false;
    end if;
  end loop;

  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.prepare_match_replay_upload_attempt(p_match_id uuid, p_submitted_by_clerk_user_id text, p_winner_registration_id uuid, p_player_one_score integer, p_player_two_score integer, p_declared_replay_sizes integer[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_result jsonb;
  v_attempt_id uuid;
begin
  v_result :=
    public.prepare_match_replay_upload_attempt_pre_game_winner_capture(
      p_match_id,
      p_submitted_by_clerk_user_id,
      p_winner_registration_id,
      p_player_one_score,
      p_player_two_score,
      p_declared_replay_sizes
    );

  if v_result->>'outcome' in ('prepared', 'recycle_required') then
    v_attempt_id := (v_result->>'attempt_id')::uuid;

    update public.match_replay_upload_attempts as attempt
    set
      game_winner_registration_ids = array[]::uuid[],
      updated_at = clock_timestamp()
    where attempt.id = v_attempt_id
      and attempt.match_id = p_match_id;

    if not found then
      raise exception 'Replay attempt no longer matches this match';
    end if;
  end if;

  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.prepare_match_replay_upload_attempt(p_match_id uuid, p_submitted_by_clerk_user_id text, p_winner_registration_id uuid, p_player_one_score integer, p_player_two_score integer, p_declared_replay_sizes integer[], p_game_winner_registration_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_result jsonb;
  v_outcome text;
  v_attempt_id uuid;
begin
  perform ironclad_private.validate_match_game_winner_sequence(
    p_match_id,
    p_winner_registration_id,
    p_player_one_score,
    p_player_two_score,
    p_game_winner_registration_ids
  );

  v_result := public.prepare_match_replay_upload_attempt(
    p_match_id,
    p_submitted_by_clerk_user_id,
    p_winner_registration_id,
    p_player_one_score,
    p_player_two_score,
    p_declared_replay_sizes
  );

  v_outcome := v_result->>'outcome';

  if v_outcome in ('prepared', 'recycle_required') then
    v_attempt_id := (v_result->>'attempt_id')::uuid;

    update public.match_replay_upload_attempts as attempt
    set
      game_winner_registration_ids = p_game_winner_registration_ids,
      updated_at = clock_timestamp()
    where attempt.id = v_attempt_id
      and attempt.match_id = p_match_id;

    if not found then
      raise exception 'Replay attempt no longer matches this match';
    end if;
  end if;

  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.prepare_match_replay_upload_attempt_pre_game_winner_capture(p_match_id uuid, p_submitted_by_clerk_user_id text, p_winner_registration_id uuid, p_player_one_score integer, p_player_two_score integer, p_declared_replay_sizes integer[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_match public.tournament_matches%rowtype;
  v_tournament_id uuid;
  v_launched_at timestamptz;
  v_reporter_registration_id uuid;
  v_required_replay_count integer;
  v_wins_required integer;
  v_winner_score integer;
  v_loser_score integer;
  v_attempt public.match_replay_upload_attempts%rowtype;
  v_attempt_id uuid;
  v_paths text[] := array[]::text[];
  v_cleanup_claim_id uuid;
  v_recycle_claim_id uuid;
  v_noncommitted_count integer;
  v_earliest_reuse_at timestamptz;
  v_index integer;
  v_now timestamptz := clock_timestamp();
  v_retry_after integer;
begin
  if p_submitted_by_clerk_user_id is null
    or btrim(p_submitted_by_clerk_user_id) = '' then
    raise exception 'Submitting player is required';
  end if;

  if p_player_one_score is null
    or p_player_two_score is null
    or p_player_one_score < 0
    or p_player_two_score < 0
    or p_player_one_score = p_player_two_score then
    raise exception 'Enter a valid non-tied final score';
  end if;

  v_required_replay_count := p_player_one_score + p_player_two_score;
  if p_declared_replay_sizes is null
    or v_required_replay_count not between 1 and 5
    or cardinality(p_declared_replay_sizes) <> v_required_replay_count
    or not public.match_replay_attempt_sizes_are_valid(p_declared_replay_sizes) then
    raise exception 'Replay upload sizes do not match the final score';
  end if;

  select match.*
  into v_match
  from public.tournament_matches as match
  where match.id = p_match_id
  for update;

  if not found then
    raise exception 'This tournament match is not open for replay submission';
  end if;

  select bracket.tournament_id, bracket.launched_at
  into v_tournament_id, v_launched_at
  from public.tournament_matches as match
  join public.generated_brackets as generated
    on generated.id = match.generated_bracket_id
  join public.tournament_brackets as bracket
    on bracket.id = generated.tournament_bracket_id
  where match.id = v_match.id;

  if not found or v_launched_at is null then
    raise exception 'This tournament match is not open for replay submission';
  end if;

  perform public.assert_tournament_not_terminal(v_tournament_id);

  if v_match.status = 'completed'
    or v_match.official_result_submission_id is not null then
    raise exception 'This match already has an official result';
  end if;

  if v_match.player_one_registration_id is null
    or v_match.player_two_registration_id is null then
    raise exception 'Both match participants must be assigned';
  end if;

  select registration.id
  into v_reporter_registration_id
  from public.registrations as registration
  where registration.id in (
    v_match.player_one_registration_id,
    v_match.player_two_registration_id
  )
    and registration.clerk_user_id = p_submitted_by_clerk_user_id;

  if v_reporter_registration_id is null then
    raise exception 'Player is not a participant in this match';
  end if;

  if p_winner_registration_id not in (
    v_match.player_one_registration_id,
    v_match.player_two_registration_id
  ) then
    raise exception 'Winner must be a participant in this match';
  end if;

  v_wins_required := (v_match.series_best_of / 2) + 1;
  v_winner_score := case
    when p_winner_registration_id = v_match.player_one_registration_id
      then p_player_one_score
    else p_player_two_score
  end;
  v_loser_score := case
    when p_winner_registration_id = v_match.player_one_registration_id
      then p_player_two_score
    else p_player_one_score
  end;

  if v_winner_score <> v_wins_required or v_loser_score >= v_wins_required then
    raise exception 'The final score is invalid for this series';
  end if;

  if exists (
    select 1
    from public.match_result_report_groups as report_group
    where report_group.match_id = p_match_id
      and report_group.status in (
        'pending_confirmation',
        'disputed',
        'under_review'
      )
      and report_group.finalized_at is null
  ) or exists (
    select 1
    from public.match_result_submissions as submission
    where submission.match_id = p_match_id
      and submission.status = 'pending'
      and submission.report_group_id is null
  ) then
    raise exception 'This match already has active result activity';
  end if;

  select attempt.*
  into v_attempt
  from public.match_replay_upload_attempts as attempt
  where attempt.match_id = p_match_id
    and attempt.submitting_registration_id = v_reporter_registration_id
    and attempt.status in ('prepared', 'finalizing', 'cleaning', 'recycling')
  order by attempt.created_at desc
  limit 1
  for update;

  if found then
    if v_attempt.status = 'prepared' then
      v_retry_after := greatest(
        0,
        ceil(extract(epoch from (
          v_attempt.capability_issued_at + interval '60 seconds' - v_now
        )))::integer
      );
      if v_retry_after > 0 then
        raise exception 'A replay upload attempt is already active; retry in % seconds',
          v_retry_after;
      end if;

      v_cleanup_claim_id := gen_random_uuid();
      update public.match_replay_upload_attempts as attempt
      set
        status = 'cleaning',
        cleanup_claim_id = v_cleanup_claim_id,
        cleanup_lease_expires_at = v_now + interval '5 minutes',
        updated_at = v_now
      where attempt.id = v_attempt.id;

      return jsonb_build_object(
        'outcome', 'cleanup_required',
        'attempt_id', v_attempt.id,
        'cleanup_claim_id', v_cleanup_claim_id,
        'replay_storage_paths', to_jsonb(v_attempt.replay_storage_paths)
      );
    end if;

    if v_attempt.status = 'finalizing' then
      if v_attempt.finalization_lease_expires_at > v_now then
        raise exception 'Replay finalization is already in progress';
      end if;

      v_cleanup_claim_id := gen_random_uuid();
      update public.match_replay_upload_attempts as attempt
      set
        status = 'cleaning',
        finalization_claim_id = null,
        finalization_lease_expires_at = null,
        cleanup_claim_id = v_cleanup_claim_id,
        cleanup_lease_expires_at = v_now + interval '5 minutes',
        updated_at = v_now
      where attempt.id = v_attempt.id;

      return jsonb_build_object(
        'outcome', 'cleanup_required',
        'attempt_id', v_attempt.id,
        'cleanup_claim_id', v_cleanup_claim_id,
        'replay_storage_paths', to_jsonb(v_attempt.replay_storage_paths)
      );
    end if;

    if v_attempt.status = 'cleaning' then
      if v_attempt.cleanup_lease_expires_at > v_now then
        raise exception 'Replay cleanup is already in progress';
      end if;

      v_cleanup_claim_id := gen_random_uuid();
      update public.match_replay_upload_attempts as attempt
      set
        cleanup_claim_id = v_cleanup_claim_id,
        cleanup_lease_expires_at = v_now + interval '5 minutes',
        updated_at = v_now
      where attempt.id = v_attempt.id;

      return jsonb_build_object(
        'outcome', 'cleanup_required',
        'attempt_id', v_attempt.id,
        'cleanup_claim_id', v_cleanup_claim_id,
        'replay_storage_paths', to_jsonb(v_attempt.replay_storage_paths)
      );
    end if;

    if v_attempt.recycle_lease_expires_at > v_now then
      raise exception 'Replay attempt recycling is already in progress';
    end if;

    v_recycle_claim_id := gen_random_uuid();
    update public.match_replay_upload_attempts as attempt
    set
      winner_registration_id = p_winner_registration_id,
      player_one_score = p_player_one_score,
      player_two_score = p_player_two_score,
      required_replay_count = v_required_replay_count,
      declared_replay_sizes = p_declared_replay_sizes,
      recycle_claim_id = v_recycle_claim_id,
      recycle_lease_expires_at = v_now + interval '5 minutes',
      updated_at = v_now
    where attempt.id = v_attempt.id;

    return jsonb_build_object(
      'outcome', 'recycle_required',
      'attempt_id', v_attempt.id,
      'recycle_claim_id', v_recycle_claim_id,
      'replay_storage_paths', to_jsonb(v_attempt.replay_storage_paths)
    );
  end if;

  select count(*)
  into v_noncommitted_count
  from public.match_replay_upload_attempts as attempt
  where attempt.match_id = p_match_id
    and attempt.submitting_registration_id = v_reporter_registration_id
    and attempt.status <> 'committed';

  if v_noncommitted_count < 3 then
    v_attempt_id := gen_random_uuid();
    for v_index in 1..5 loop
      v_paths := array_append(
        v_paths,
        format(
          '%s/%s/game-%s-%s.rec',
          p_match_id,
          v_attempt_id,
          v_index,
          gen_random_uuid()
        )
      );
    end loop;

    insert into public.match_replay_upload_attempts (
      id,
      match_id,
      submitting_registration_id,
      winner_registration_id,
      player_one_score,
      player_two_score,
      required_replay_count,
      replay_storage_paths,
      declared_replay_sizes,
      status,
      capability_issued_at,
      capability_not_before_reuse_at
    ) values (
      v_attempt_id,
      p_match_id,
      v_reporter_registration_id,
      p_winner_registration_id,
      p_player_one_score,
      p_player_two_score,
      v_required_replay_count,
      v_paths,
      p_declared_replay_sizes,
      'prepared',
      v_now,
      v_now + interval '2 hours 5 minutes'
    ) returning * into v_attempt;
  else
    select attempt.*
    into v_attempt
    from public.match_replay_upload_attempts as attempt
    where attempt.match_id = p_match_id
      and attempt.submitting_registration_id = v_reporter_registration_id
      and attempt.status = 'cleaned'
      and attempt.capability_not_before_reuse_at <= v_now
    order by attempt.capability_not_before_reuse_at, attempt.created_at
    limit 1
    for update;

    if not found then
      select min(attempt.capability_not_before_reuse_at)
      into v_earliest_reuse_at
      from public.match_replay_upload_attempts as attempt
      where attempt.match_id = p_match_id
        and attempt.submitting_registration_id = v_reporter_registration_id
        and attempt.status = 'cleaned';

      v_retry_after := greatest(
        1,
        ceil(extract(epoch from (v_earliest_reuse_at - v_now)))::integer
      );
      raise exception 'Replay upload retry budget is exhausted; retry in % seconds',
        v_retry_after;
    end if;

    v_recycle_claim_id := gen_random_uuid();
    update public.match_replay_upload_attempts as attempt
    set
      winner_registration_id = p_winner_registration_id,
      player_one_score = p_player_one_score,
      player_two_score = p_player_two_score,
      required_replay_count = v_required_replay_count,
      declared_replay_sizes = p_declared_replay_sizes,
      status = 'recycling',
      recycle_claim_id = v_recycle_claim_id,
      recycle_lease_expires_at = v_now + interval '5 minutes',
      cleaned_at = null,
      updated_at = v_now
    where attempt.id = v_attempt.id;

    return jsonb_build_object(
      'outcome', 'recycle_required',
      'attempt_id', v_attempt.id,
      'recycle_claim_id', v_recycle_claim_id,
      'replay_storage_paths', to_jsonb(v_attempt.replay_storage_paths)
    );
  end if;

  return jsonb_build_object(
    'outcome', 'prepared',
    'attempt_id', v_attempt.id,
    'replay_storage_paths',
      to_jsonb(v_attempt.replay_storage_paths[1:v_required_replay_count]),
    'required_replay_count', v_attempt.required_replay_count,
    'capability_issue_count', v_attempt.capability_issue_count
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.preserve_tournament_first_completed_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
begin
  if tg_op = 'INSERT' then
    if new.status = 'completed' then
      new.first_completed_at := clock_timestamp();
    else
      new.first_completed_at := null;
    end if;
    return new;
  end if;

  if old.first_completed_at is not null
    and new.first_completed_at is distinct from old.first_completed_at then
    raise exception 'Tournament first completion is immutable'
      using errcode = '55000';
  end if;

  if old.first_completed_at is null
    and new.status = 'completed'
    and old.status is distinct from 'completed' then
    new.first_completed_at := clock_timestamp();
  elsif old.first_completed_at is null
    and new.first_completed_at is not null then
    raise exception 'Tournament first completion can only be set by completion'
      using errcode = '55000';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.preview_match_room_retention(p_room_ids uuid[], p_actor_clerk_user_id text, p_after_room_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET lock_timeout TO '2s'
 SET statement_timeout TO '60s'
AS $function$
declare v_rooms jsonb;
begin
  perform ironclad_private.match_room_privacy_actor(p_actor_clerk_user_id);
  if p_room_ids is not null and (cardinality(p_room_ids) not between 1 and 100 or array_position(p_room_ids,null) is not null) then
    raise exception 'Select 1 to 100 rooms' using errcode='22023'; end if;
  -- LIMIT applies before any per-room message/case/hold inspection. The cursor
  -- advances past blocked candidates so they cannot starve later eligible rooms.
  with candidates as materialized (
    select id,created_at from public.match_rooms where (p_room_ids is not null and id=any(p_room_ids))
      or (p_room_ids is null and (p_after_room_id is null or id>p_after_room_id))
    order by id limit 100
  ) select coalesce(jsonb_agg(ironclad_private.match_room_retention_state(id) order by id),'[]') into v_rooms from candidates;
  return jsonb_build_object('rooms',v_rooms,'nextRoomId',case when p_room_ids is null and jsonb_array_length(v_rooms)=100 then v_rooms->-1->>'roomId' end,
    'policy',jsonb_build_object('routineDays',40,'supportMonths',24,'resultMonths',24));
end $function$

CREATE OR REPLACE FUNCTION public.preview_poll_eligibility(p_poll_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_poll public.polls%rowtype;
  v_selected_count integer;
  v_eligible_count integer;
  v_players jsonb;
begin
  perform public.assert_poll_service_role();

  select poll.* into v_poll
  from public.polls as poll
  where poll.id = p_poll_id;

  if not found then
    raise exception 'Poll not found';
  end if;
  if v_poll.published_at is not null then
    raise exception 'Published poll eligibility is already frozen'
      using errcode = '55000';
  end if;

  select count(*)::integer
  into v_selected_count
  from public.poll_eligible_voters as selected
  where selected.poll_id = p_poll_id;

  select count(*)::integer,
    coalesce(
      pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'id', candidate.player_id,
          'display_name', candidate.display_name,
          'in_game_name', candidate.in_game_name
        ) order by candidate.display_name, candidate.player_id
      ),
      '[]'::jsonb
    )
  into v_eligible_count, v_players
  from public.poll_eligible_candidates(p_poll_id) as candidate;

  if v_poll.audience_kind in (
    'selected_tournament_players',
    'selected_active_players'
  ) and v_selected_count <> v_eligible_count then
    raise exception 'Selected audience contains an ineligible player'
      using errcode = '22023';
  end if;

  return pg_catalog.jsonb_build_object(
    'poll_id', p_poll_id,
    'eligible_count', v_eligible_count,
    'players', v_players
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.process_matchup_deadlines(p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_previous_skip text;
  v_result jsonb;
begin
  v_previous_skip := pg_catalog.current_setting(
    'ironclad.terminal_worker_skip',
    true
  );
  perform pg_catalog.set_config(
    'ironclad.terminal_worker_skip',
    'on',
    true
  );

  begin
    v_result :=
      public.process_matchup_deadlines_without_terminal_guard(p_limit);
  exception when others then
    perform pg_catalog.set_config(
      'ironclad.terminal_worker_skip',
      coalesce(v_previous_skip, ''),
      true
    );
    raise;
  end;

  perform pg_catalog.set_config(
    'ironclad.terminal_worker_skip',
    coalesce(v_previous_skip, ''),
    true
  );
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.protect_division_launch_boundary()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
begin
  if tg_op = 'DELETE'
    and (
      current_setting('ironclad.tournament_deletion', true) = 'on'
      or not exists (
        select 1
        from public.tournaments as tournament
        where tournament.id = old.tournament_id
      )
    ) then
    return old;
  end if;

  if tg_op = 'INSERT' then
    if new.launched_at is not null then
      raise exception
        'A tournament division can only launch through Launch Division';
    end if;

    if exists (
      select 1
      from public.tournament_brackets as launched_bracket
      where launched_bracket.tournament_id = new.tournament_id
        and launched_bracket.launched_at is not null
    )
      and not exists (
        select 1
        from public.tournament_brackets as existing_bracket
        where existing_bracket.tournament_id = new.tournament_id
          and existing_bracket.name = new.name
      ) then
      raise exception
        'Configured tournament divisions cannot be added after launch begins';
    end if;
    return new;
  end if;

  if tg_op = 'DELETE' then
    if old.launched_at is not null
      or exists (
        select 1
        from public.tournament_brackets as launched_bracket
        where launched_bracket.tournament_id = old.tournament_id
          and launched_bracket.launched_at is not null
      ) then
      raise exception
        'Configured tournament divisions cannot be removed after launch begins';
    end if;
    return old;
  end if;

  if old.launched_at is not null
    and (
      new.tournament_id is distinct from old.tournament_id
      or new.name is distinct from old.name
      or new.elo_rules is distinct from old.elo_rules
      or new.max_players is distinct from old.max_players
    ) then
    raise exception
      'A launched tournament division configuration is immutable';
  end if;

  if old.launched_at is not null
    and new.launched_at is distinct from old.launched_at then
    raise exception 'Division launch time is immutable';
  end if;

  if old.launched_at is null
    and new.launched_at is not null
    and coalesce(
      current_setting('ironclad.explicit_division_launch', true),
      ''
    ) <> 'on' then
    raise exception 'Use Launch Division to launch a tournament division';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.protect_legal_document_record()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
begin
  if tg_op = 'DELETE' then
    raise exception 'Legal document records are archived, not deleted'
      using errcode = '55000';
  end if;

  if new.id is distinct from old.id
    or new.document_kind is distinct from old.document_kind
    or new.version is distinct from old.version
    or new.immutable_url is distinct from old.immutable_url
    or new.created_at is distinct from old.created_at then
    raise exception 'Versioned legal document identity is immutable'
      using errcode = '55000';
  end if;

  if not (
    (old.status = 'review_draft'
      and new.status in ('review_draft', 'effective', 'superseded'))
    or (old.status = 'effective'
      and new.status in ('effective', 'superseded'))
    or (old.status = 'superseded' and new.status = 'superseded')
  ) then
    raise exception 'Legal document status cannot move backwards'
      using errcode = '55000';
  end if;

  if old.status in ('effective', 'superseded')
    and (
      new.published_at is distinct from old.published_at
      or new.effective_at is distinct from old.effective_at
      or new.sha256 is distinct from old.sha256
    ) then
    raise exception 'Final legal document facts are immutable'
      using errcode = '55000';
  end if;

  new.updated_at = clock_timestamp();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.protect_player_coh3_profile_id()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_requested_profile_id text;
begin
  if (
    coalesce(current_setting('ironclad.account_closure', true), '') = 'on'
    and (
      session_user = 'postgres'
      or coalesce(auth.role(), '') = 'service_role'
    )
  ) or coalesce(auth.role(), '') = 'service_role' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    new.coh3_profile_id = null;
    return new;
  end if;

  if old.coh3_profile_id is not null then
    v_requested_profile_id :=
      public.extract_coh3stats_profile_id(new.coh3_player_card_url);

    if v_requested_profile_id is distinct from old.coh3_profile_id then
      new.coh3_player_card_url = old.coh3_player_card_url;
    end if;
  end if;

  new.coh3_profile_id = old.coh3_profile_id;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.protect_player_relic_verification()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
begin
  if (
    coalesce(current_setting('ironclad.account_closure', true), '') = 'on'
    and (
      session_user = 'postgres'
      or coalesce(auth.role(), '') = 'service_role'
    )
  ) or (
    current_user = 'postgres'
    and coalesce(auth.role(), '') = 'service_role'
  ) then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if num_nonnulls(
      new.current_elo,
      new.relic_verified_elo,
      new.relic_verified_faction,
      new.relic_verified_division,
      new.relic_elo_calculation_version,
      new.relic_elo_verified_at,
      new.relic_elo_last_attempt_at
    ) > 0 then
      raise exception using
        errcode = '42501',
        message = 'Relic verification fields are server-controlled';
    end if;

    return new;
  end if;

  if new.current_elo is distinct from old.current_elo
    or new.relic_verified_elo is distinct from old.relic_verified_elo
    or new.relic_verified_faction is distinct from old.relic_verified_faction
    or new.relic_verified_division is distinct from old.relic_verified_division
    or new.relic_elo_calculation_version
      is distinct from old.relic_elo_calculation_version
    or new.relic_elo_verified_at is distinct from old.relic_elo_verified_at
    or new.relic_elo_last_attempt_at
      is distinct from old.relic_elo_last_attempt_at then
    raise exception using
      errcode = '42501',
      message = 'Relic verification fields are server-controlled';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.protect_registration_history_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
begin
  if current_setting('ironclad.tournament_deletion', true) = 'on' then
    return old;
  end if;

  if coalesce(
      current_setting('ironclad.staging_synthetic_uat_cleanup', true),
      ''
    ) = 'on'
    and coalesce(auth.role(), '') = 'service_role'
    and old.registration_provenance = 'staging_synthetic_uat'
    and old.fixture_contract_version = 'staging-synthetic-v1'
    and exists (
      select 1
      from ironclad_private.staging_synthetic_uat_enrolments as fixture
      where fixture.registration_id = old.id
        and fixture.player_id = old.profile_id
        and fixture.tournament_id = old.tournament_id
        and fixture.tournament_bracket_id = old.tournament_bracket_id
    ) then
    return old;
  end if;

  if old.tournament_id is not null
    and exists (
      select 1
      from public.tournaments as tournament
      where tournament.id = old.tournament_id
    ) then
    raise exception
      'Tournament registration history cannot be deleted; use review or withdrawal';
  end if;

  return old;
end;
$function$

CREATE OR REPLACE FUNCTION public.protect_tournament_lifecycle_boundary()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_has_launched boolean;
  v_has_unlaunched boolean;
  v_has_open_unlaunched boolean;
  v_explicit_transition boolean;
  v_terminal_transition boolean :=
    coalesce(
      pg_catalog.current_setting(
        'ironclad.tournament_terminal_transition',
        true
      ),
      ''
    ) = 'on'
    and (
      session_user = 'postgres'
      or coalesce(auth.role(), '') = 'service_role'
    );
begin
  select
    coalesce(bool_or(bracket.launched_at is not null), false),
    coalesce(bool_or(bracket.launched_at is null), false),
    coalesce(bool_or(
      bracket.launched_at is null
      and not exists (
        select 1
        from public.tournament_division_not_held_closures as closure
        where closure.tournament_bracket_id = bracket.id
      )
    ), false)
  into v_has_launched, v_has_unlaunched, v_has_open_unlaunched
  from public.tournament_brackets as bracket
  where bracket.tournament_id = old.id;

  v_explicit_transition := coalesce(
    pg_catalog.current_setting('ironclad.explicit_division_launch', true),
    ''
  ) = 'on';

  if new.status = 'in_progress'
    and old.status is distinct from 'in_progress'
    and not v_explicit_transition then
    raise exception
      'Use Launch Division to move a tournament into progress';
  end if;

  if v_has_launched
    and new.status in ('upcoming', 'registration_open') then
    raise exception 'A tournament with a launched division cannot be reopened';
  end if;

  -- Parent-event completion is intentionally unchanged until the approved
  -- accounting cutover. A Not Held Division must not create completion facts.
  if new.status = 'completed' and v_has_unlaunched then
    raise exception
      'A tournament cannot complete while a configured division is unlaunched';
  end if;

  if new.registration_enabled is true
    and not v_has_open_unlaunched then
    raise exception
      'Registration cannot reopen after every division is resolved';
  end if;

  if v_has_launched
    and v_has_open_unlaunched
    and not v_explicit_transition
    and not v_terminal_transition
    and new.registration_enabled is distinct from
      old.registration_enabled then
    raise exception
      'Global registration availability must remain unchanged while sibling divisions are unlaunched';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.publish_official_announcement(p_title text, p_body text, p_media_kind text, p_media_path text, p_media_mime_type text, p_media_description text, p_actor_clerk_user_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_actor_clerk_user_id text := nullif(btrim(p_actor_clerk_user_id), '');
  v_announcement public.announcements%rowtype;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'Announcement publication is unavailable'
      using errcode = '42501';
  end if;

  if v_actor_clerk_user_id is null then
    raise exception 'Announcement publication is unavailable'
      using errcode = '22023';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'ironclad:announcement-account:' || v_actor_clerk_user_id,
      0
    )
  );

  insert into public.announcements (
    title,
    body,
    media_kind,
    media_path,
    media_mime_type,
    media_description,
    published_by_clerk_user_id
  ) values (
    p_title,
    p_body,
    p_media_kind,
    p_media_path,
    p_media_mime_type,
    p_media_description,
    v_actor_clerk_user_id
  )
  returning * into v_announcement;

  return pg_catalog.jsonb_build_object(
    'id', v_announcement.id,
    'published_at', v_announcement.published_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.publish_official_announcement_with_tournament(p_title text, p_body text, p_media_kind text, p_media_path text, p_media_mime_type text, p_media_description text, p_actor_clerk_user_id text, p_linked_tournament_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_publication jsonb;
  v_announcement_id uuid;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'Announcement publication is unavailable'
      using errcode = '42501';
  end if;

  if p_linked_tournament_id is null then
    raise exception 'Select an existing Tournament'
      using errcode = '22023';
  end if;

  perform 1
  from public.tournaments as tournament
  where tournament.id = p_linked_tournament_id;

  if not found then
    raise exception 'Select an existing Tournament'
      using errcode = '23503';
  end if;

  v_publication := public.publish_official_announcement(
    p_title,
    p_body,
    p_media_kind,
    p_media_path,
    p_media_mime_type,
    p_media_description,
    p_actor_clerk_user_id
  );
  v_announcement_id := nullif(v_publication ->> 'id', '')::uuid;

  if v_announcement_id is null then
    raise exception 'Announcement publication is unavailable'
      using errcode = 'P0001';
  end if;

  update public.announcements as announcement
  set linked_tournament_id = p_linked_tournament_id
  where announcement.id = v_announcement_id;

  if not found then
    raise exception 'Announcement publication is unavailable'
      using errcode = 'P0001';
  end if;

  return v_publication;
end;
$function$

CREATE OR REPLACE FUNCTION public.publish_poll(p_poll_id uuid, p_actor_clerk_user_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_actor text := nullif(pg_catalog.btrim(p_actor_clerk_user_id), '');
  v_poll public.polls%rowtype;
  v_published_at timestamptz;
  v_option_count integer;
  v_selected_count integer;
  v_eligible_count integer;
  v_tournament_status text;
  v_tournament_title text;
  v_notification_title text;
  v_notification_message text;
begin
  perform public.assert_poll_service_role();
  if v_actor is null then
    raise exception 'Poll administrator is required' using errcode = '22023';
  end if;

  select poll.*
  into v_poll
  from public.polls as poll
  where poll.id = p_poll_id
  for update;

  if not found then
    raise exception 'Poll not found';
  end if;
  v_published_at := pg_catalog.clock_timestamp();
  if v_poll.published_at is not null then
    raise exception 'Poll has already been published' using errcode = '55000';
  end if;
  if v_poll.draft_audience_invalidated then
    raise exception 'Selected audience changed after account closure; review and save the Draft again'
      using errcode = '55000';
  end if;
  if v_published_at >= v_poll.closes_at then
    raise exception 'A poll cannot be published after its database close time'
      using errcode = '55000';
  end if;

  select count(*)::integer
  into v_option_count
  from public.poll_options as option
  where option.poll_id = p_poll_id;

  if v_option_count not between 2 and 24
    or v_poll.max_selections > v_option_count
    or v_poll.winner_count > v_option_count then
    raise exception 'Poll configuration is incomplete'
      using errcode = '22023';
  end if;

  if v_poll.purpose = 'tournament_decision' then
    select tournament.status, tournament.title
    into v_tournament_status, v_tournament_title
    from public.tournaments as tournament
    where tournament.id = v_poll.tournament_id
    for share;

    if not found then
      raise exception 'Tournament not found';
    end if;
    if v_tournament_status in ('completed', 'cancelled', 'voided') then
      raise exception 'New Tournament Decisions cannot be published for a terminal tournament'
        using errcode = '55000';
    end if;

    perform registration.id
    from public.registrations as registration
    where registration.tournament_id = v_poll.tournament_id
      and (
        v_poll.audience_kind <> 'tournament_division_approved'
        or registration.tournament_bracket_id = v_poll.tournament_bracket_id
      )
    order by registration.id
    for share;
  end if;

  perform player.id
  from public.players as player
  where player.id in (
    select candidate.player_id
    from public.poll_eligible_candidates(p_poll_id) as candidate
  )
  order by player.id
  for share;

  if v_poll.audience_kind in (
    'selected_tournament_players',
    'selected_active_players'
  ) then
    select count(*)::integer
    into v_selected_count
    from public.poll_eligible_voters as selected
    where selected.poll_id = p_poll_id;

    select count(*)::integer
    into v_eligible_count
    from public.poll_eligible_candidates(p_poll_id);

    if v_selected_count <> v_eligible_count then
      raise exception 'Selected audience contains an ineligible player'
        using errcode = '22023';
    end if;
  end if;

  if v_poll.option_source = 'coh3_map' then
    -- Keep catalogue rows stable from publication revalidation through the
    -- immutable snapshot write so retirement cannot slip between statements.
    perform map.id
    from public.coh3_maps as map
    join public.poll_options as option on option.coh3_map_id = map.id
    where option.poll_id = p_poll_id
    order by map.id
    for share of map;

    if exists (
      select 1
      from public.poll_options as option
      left join public.coh3_maps as map on map.id = option.coh3_map_id
      where option.poll_id = p_poll_id
        and (
          map.id is null
          or map.status <> 'active'
          or map.game_mode <> '1v1'
        )
    ) then
      raise exception 'Map polls require active 1v1 catalogue maps'
        using errcode = '22023';
    end if;

    update public.poll_options as option
    set label_snapshot = map.display_name,
      map_display_name_snapshot = map.display_name,
      map_slug_snapshot = map.slug
    from public.coh3_maps as map
    where option.poll_id = p_poll_id
      and map.id = option.coh3_map_id;
  elsif exists (
    select 1 from public.poll_options as option
    where option.poll_id = p_poll_id
      and option.coh3_map_id is not null
  ) then
    raise exception 'Text poll options cannot reference maps'
      using errcode = '22023';
  end if;

  if v_poll.audience_kind not in (
    'selected_tournament_players',
    'selected_active_players'
  ) then
    delete from public.poll_eligible_voters
    where poll_id = p_poll_id;

    insert into public.poll_eligible_voters (
      poll_id, player_id, eligible_at
    )
    select p_poll_id, candidate.player_id, v_published_at
    from public.poll_eligible_candidates(p_poll_id) as candidate
    order by candidate.player_id;
    get diagnostics v_eligible_count = row_count;
  else
    update public.poll_eligible_voters
    set eligible_at = v_published_at
    where poll_id = p_poll_id;
    get diagnostics v_eligible_count = row_count;
  end if;

  if v_eligible_count = 0 then
    raise exception 'Poll publication requires at least one eligible player'
      using errcode = '22023';
  end if;

  update public.polls
  set published_at = v_published_at,
    published_by_clerk_user_id = v_actor,
    updated_by_clerk_user_id = v_actor
  where id = p_poll_id;

  v_notification_title := case
    when v_published_at < v_poll.opens_at then 'Poll scheduled'
    else 'Your vote is requested'
  end;
  v_notification_message := case
    when v_published_at < v_poll.opens_at then
      pg_catalog.format(
        '%s Voting opens %s and closes %s.',
        v_poll.question,
        v_poll.opens_at,
        v_poll.closes_at
      )
    else
      pg_catalog.format(
        '%s Vote before %s.',
        v_poll.question,
        v_poll.closes_at
      )
  end;

  insert into public.notifications (
    recipient_clerk_user_id,
    recipient_role,
    type,
    title,
    message,
    tournament_id,
    tournament_title,
    metadata,
    event_key
  )
  select
    player.clerk_user_id,
    'player',
    'poll.published',
    v_notification_title,
    v_notification_message,
    v_poll.tournament_id,
    v_tournament_title,
    pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
      'pollId', p_poll_id,
      'purpose', v_poll.purpose,
      'tournamentId', v_poll.tournament_id,
      'opensAt', v_poll.opens_at,
      'closesAt', v_poll.closes_at
    )),
    pg_catalog.format('poll:%s:published', p_poll_id)
  from public.poll_eligible_voters as eligible
  join public.players as player on player.id = eligible.player_id
  where eligible.poll_id = p_poll_id
  order by player.id
  on conflict (recipient_clerk_user_id, event_key)
    where event_key is not null
  do nothing;

  return pg_catalog.jsonb_build_object(
    'poll_id', p_poll_id,
    'published_at', v_published_at,
    'eligible_count', v_eligible_count
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.publish_tournament_bracket_map_pools(p_tournament_id uuid, p_bracket_ids uuid[], p_map_ids uuid[], p_actor_clerk_user_id text)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_actor text := nullif(btrim(p_actor_clerk_user_id), '');
  v_tournament_status text;
  v_requested_bracket_count integer;
  v_matching_bracket_count integer;
  v_map_count integer;
  v_eligible_map_count integer;
  v_published_at timestamptz := clock_timestamp();
begin
  if session_user <> 'postgres'
    and coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'Map-pool publication requires the trusted server boundary'
      using errcode = '42501';
  end if;

  if v_actor is null then
    raise exception 'Publishing administrator is required'
      using errcode = '22023';
  end if;

  if p_tournament_id is null
    or coalesce(cardinality(p_bracket_ids), 0) = 0
    or array_position(p_bracket_ids, null) is not null then
    raise exception 'Select at least one valid tournament Division';
  end if;

  select count(distinct bracket_id)::integer
  into v_requested_bracket_count
  from unnest(p_bracket_ids) as bracket_id;

  if v_requested_bracket_count <> cardinality(p_bracket_ids) then
    raise exception 'Select each tournament Division only once';
  end if;

  if coalesce(cardinality(p_map_ids), 0) < 5
    or array_position(p_map_ids, null) is not null then
    raise exception 'A published Division pool requires five distinct maps';
  end if;

  select count(distinct map_id)::integer
  into v_map_count
  from unnest(p_map_ids) as map_id;

  if v_map_count <> cardinality(p_map_ids) then
    raise exception 'A published Division pool cannot contain duplicate maps';
  end if;

  select tournament.status
  into v_tournament_status
  from public.tournaments as tournament
  where tournament.id = p_tournament_id
  for update;

  if not found then
    raise exception 'Tournament not found';
  end if;

  if v_tournament_status in ('cancelled', 'voided', 'completed') then
    raise exception 'This tournament is read-only';
  end if;

  perform bracket.id
  from public.tournament_brackets as bracket
  where bracket.id = any(p_bracket_ids)
    and bracket.tournament_id = p_tournament_id
  order by bracket.id
  for update;

  select count(*)::integer
  into v_matching_bracket_count
  from public.tournament_brackets as bracket
  where bracket.id = any(p_bracket_ids)
    and bracket.tournament_id = p_tournament_id
    and bracket.launched_at is null
    and bracket.max_players = 8;

  if v_matching_bracket_count <> v_requested_bracket_count then
    raise exception
      'Every selected Division must belong to the tournament, be unlaunched, and have an eight-player capacity';
  end if;

  perform entry.id
  from public.tournament_bracket_map_pool_entries as entry
  where entry.tournament_bracket_id = any(p_bracket_ids)
    and entry.removed_at is null
  order by entry.tournament_bracket_id, entry.id
  for update;

  perform map.id
  from public.coh3_maps as map
  where map.id = any(p_map_ids)
  order by map.id
  for update;

  select
    count(*)::integer,
    count(*) filter (
      where map.status = 'active'
        and map.game_mode = '1v1'
    )::integer
  into v_map_count, v_eligible_map_count
  from public.coh3_maps as map
  where map.id = any(p_map_ids);

  if v_map_count <> cardinality(p_map_ids)
    or v_eligible_map_count <> cardinality(p_map_ids) then
    raise exception 'Published pools require existing active 1v1 maps only';
  end if;

  update public.tournament_bracket_map_pool_entries as entry
  set removed_at = v_published_at
  where entry.tournament_bracket_id = any(p_bracket_ids)
    and entry.removed_at is null
    and not (entry.coh3_map_id = any(p_map_ids));

  insert into public.tournament_bracket_map_pool_entries (
    tournament_bracket_id,
    coh3_map_id,
    added_at
  )
  select bracket_id, map_id, v_published_at
  from unnest(p_bracket_ids) as bracket_id
  cross join unnest(p_map_ids) as map_id
  where not exists (
    select 1
    from public.tournament_bracket_map_pool_entries as current_entry
    where current_entry.tournament_bracket_id = bracket_id
      and current_entry.coh3_map_id = map_id
      and current_entry.removed_at is null
  );

  update public.tournament_brackets as bracket
  set map_pool_published_at = v_published_at
  where bracket.id = any(p_bracket_ids);

  return v_published_at;
end;
$function$

CREATE OR REPLACE FUNCTION public.purge_match_room_retention(p_room_ids uuid[], p_actor_clerk_user_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET lock_timeout TO '2s'
 SET statement_timeout TO '60s'
AS $function$
declare v_actor uuid; v_room uuid; s jsonb; n integer; v_count integer:=0; v_messages integer:=0;
  v_before int[]; v_reads integer:=0; v_episodes integer:=0; v_assistance integer:=0; v_notifications integer:=0; v_notices uuid[];
begin
  v_actor:=ironclad_private.match_room_privacy_actor(p_actor_clerk_user_id);
  if p_room_ids is null or cardinality(p_room_ids) not between 1 and 100 or array_position(p_room_ids,null) is not null then
    raise exception 'Select 1 to 100 rooms' using errcode='22023'; end if;
  for v_room in select distinct unnest(p_room_ids) order by 1 loop
    perform ironclad_private.lock_match_room_privacy(v_room);
    perform ironclad_private.match_room_privacy_actor(p_actor_clerk_user_id);
    s:=ironclad_private.match_room_retention_state(v_room);
    if s->>'blockedReason' is not null then continue; end if;
    v_before:=array[v_messages,v_reads,v_episodes,v_assistance,v_notifications];
    -- Delete at most 1000 bodies per room per call. Repeating the same bounded
    -- batch resumes safely; last_sequence and immutable room identity remain.
    delete from public.match_messages where id in (
      select m.id from public.match_messages m where m.room_id=v_room and not exists(
        select 1 from ironclad_private.match_room_retention_holds h where h.room_id=v_room
          and h.released_at is null and h.expires_at>now() and (h.message_ids is null or m.id=any(h.message_ids)))
      order by m.sequence limit 1000);
    get diagnostics n=row_count; v_messages:=v_messages+n;
    if not exists(select 1 from public.match_messages where room_id=v_room) then
      select array_agg(id) into v_notices from (
        (select notification_id id from public.match_room_notification_episodes where room_id=v_room order by id limit 1000)
        union select notification_id from public.match_room_assistance where room_id=v_room) ids where id is not null;
      delete from public.match_room_reads where (room_id,viewer_clerk_user_id) in (select room_id,viewer_clerk_user_id from public.match_room_reads where room_id=v_room order by viewer_clerk_user_id limit 1000); get diagnostics n=row_count; v_reads:=v_reads+n;
      delete from public.match_room_notification_episodes where id in (select id from public.match_room_notification_episodes where room_id=v_room order by id limit 1000); get diagnostics n=row_count; v_episodes:=v_episodes+n;
      delete from public.match_room_assistance where room_id=v_room; get diagnostics n=row_count; v_assistance:=v_assistance+n;
      delete from public.notifications where id in (select id from public.notifications
        where (id=any(v_notices) or (metadata->>'roomId'=v_room::text
          and match_id=(select match_id from public.match_rooms where id=v_room)
          and type in ('match.message_received','match.admin_assistance_requested')))
        order by id limit 1000); get diagnostics n=row_count; v_notifications:=v_notifications+n;
      if not exists(select 1 from public.match_room_reads where room_id=v_room)
        and not exists(select 1 from public.match_room_notification_episodes where room_id=v_room)
        and not exists(select 1 from public.notifications where metadata->>'roomId'=v_room::text
          and match_id=(select match_id from public.match_rooms where id=v_room)
          and type in ('match.message_received','match.admin_assistance_requested')) then
      update public.match_rooms set content_purged_at=coalesce(content_purged_at,clock_timestamp()),
        closed_at=coalesce(closed_at,clock_timestamp()),closure_reason=coalesce(closure_reason,'tournament_closed') where id=v_room;
      end if;
      delete from ironclad_private.match_room_retention_cases where (room_id,case_reference) in (select room_id,case_reference from ironclad_private.match_room_retention_cases where room_id=v_room and closed_at<now()-interval '24 months' order by case_reference limit 1000);
      delete from ironclad_private.match_room_retention_holds where id in(select id from ironclad_private.match_room_retention_holds where room_id=v_room and coalesce(released_at,expires_at)<now()-interval '24 months' order by id limit 1000);
      delete from ironclad_private.match_room_privacy_audit where id in(select id from ironclad_private.match_room_privacy_audit where room_id=v_room and occurred_at<now()-interval '24 months' order by id limit 1000);
    end if;
    v_count:=v_count+1;
    if array[v_messages,v_reads,v_episodes,v_assistance,v_notifications] is distinct from v_before then
      insert into ironclad_private.match_room_privacy_audit(room_id,operation,actor_player_id,counts)
      values(v_room,'purge',v_actor,jsonb_build_object('messagesDeleted',v_messages-v_before[1],
        'readsDeleted',v_reads-v_before[2],'episodesDeleted',v_episodes-v_before[3],
        'assistanceDeleted',v_assistance-v_before[4],'notificationsDeleted',v_notifications-v_before[5]));
    end if;
  end loop;
  return jsonb_build_object('roomsProcessed',v_count,'messagesDeleted',v_messages,'readsDeleted',v_reads,
    'episodesDeleted',v_episodes,'assistanceDeleted',v_assistance,'notificationsDeleted',v_notifications);
end $function$

CREATE OR REPLACE FUNCTION public.queue_badge_reconciliation_from_leaderboard_player()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_reason text;
  v_source_type text;
  v_source_id text;
begin
  if tg_table_name = 'leaderboard_point_events' then
    v_reason := 'leaderboard_recalculation';
    v_source_type := 'tournament';
    v_source_id := new.tournament_id::text;
  else
    v_reason := 'season_finalization';
    v_source_type := 'season';
    v_source_id := new.season_id::text;
  end if;

  perform ironclad_private.enqueue_badge_reconciliation_target(
    new.player_id,
    v_reason,
    v_source_type,
    v_source_id
  );

  return new;
exception
  when others then
    raise warning 'Badge leaderboard reconciliation enqueue failed [%]', sqlstate;
    return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.queue_badge_reconciliation_from_participant_authority()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_player_id uuid;
begin
  select registration.profile_id
  into v_player_id
  from public.registrations as registration
  where registration.id = new.registration_id;

  if v_player_id is not null then
    perform ironclad_private.enqueue_badge_reconciliation_target(
      v_player_id,
      'match_authority',
      'match',
      new.match_id::text
    );
  end if;

  return new;
exception
  when others then
    raise warning 'Badge participant reconciliation enqueue failed [%]', sqlstate;
    return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.queue_badge_reconciliation_from_tournament_completion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_player_id uuid;
begin
  if old.status is not distinct from new.status or new.status <> 'completed' then
    return new;
  end if;

  for v_player_id in
    select distinct registration.profile_id
    from public.registrations as registration
    where registration.tournament_id = new.id
      and registration.profile_id is not null
      and registration.registration_status = 'approved'
  loop
    perform ironclad_private.enqueue_badge_reconciliation_target(
      v_player_id,
      'tournament_completion',
      'tournament',
      new.id::text
    );
  end loop;

  return new;
exception
  when others then
    raise warning 'Badge tournament reconciliation enqueue failed [%]', sqlstate;
    return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.recalculate_leaderboard_all_time(p_triggered_by_clerk_user_id text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
begin
  perform public.leaderboard_require_write_access();
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('ironclad:leaderboard:all-time', 0)
  );

  return public.recalculate_leaderboard_all_time_without_concurrency_lock(
    p_triggered_by_clerk_user_id
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.recalculate_leaderboard_for_season(p_season_id uuid, p_triggered_by_clerk_user_id text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_finalized_at timestamptz;
  v_run_id uuid;
  v_run_status text;
  v_all_time_run_id uuid;
  v_all_time_status text;
  v_all_time_notes text;
begin
  perform public.leaderboard_require_write_access();
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('ironclad:leaderboard:all-time', 0)
  );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'ironclad:leaderboard:season:' || coalesce(p_season_id::text, 'null'),
      0
    )
  );

  select season.finalized_at
  into v_finalized_at
  from public.leaderboard_seasons as season
  where season.id = p_season_id;

  if not found then
    raise exception 'Leaderboard season not found';
  end if;

  if v_finalized_at is not null then
    drop table if exists pg_temp.leaderboard_finalized_main_stats;
    create temporary table leaderboard_finalized_main_stats
    on commit drop
    as
    select *
    from public.leaderboard_player_season_stats as season_stats
    where season_stats.season_id = p_season_id
      and season_stats.bracket_type = 'main';
  end if;

  v_run_id := public.recalculate_leaderboard_for_season_pr2_core(
    p_season_id,
    p_triggered_by_clerk_user_id
  );

  select run.status
  into v_run_status
  from public.leaderboard_recalculation_runs as run
  where run.id = v_run_id;

  if v_finalized_at is null then
    return v_run_id;
  end if;

  delete from public.leaderboard_player_season_stats
  where season_id = p_season_id
    and bracket_type = 'main';

  insert into public.leaderboard_player_season_stats (
    id,
    season_id,
    player_id,
    bracket_type,
    total_points,
    tournaments_played,
    rounds_passed,
    tournament_wins,
    matches_played,
    matches_won,
    matches_lost,
    win_rate,
    last_tournament_id,
    last_tournament_points,
    current_rank,
    previous_rank,
    rank_movement,
    updated_at
  )
  select
    id,
    season_id,
    player_id,
    bracket_type,
    total_points,
    tournaments_played,
    rounds_passed,
    tournament_wins,
    matches_played,
    matches_won,
    matches_lost,
    win_rate,
    last_tournament_id,
    last_tournament_points,
    current_rank,
    previous_rank,
    rank_movement,
    updated_at
  from pg_temp.leaderboard_finalized_main_stats;

  if v_run_status is distinct from 'completed' then
    return v_run_id;
  end if;

  v_all_time_run_id := public.recalculate_leaderboard_all_time(
    p_triggered_by_clerk_user_id
  );

  select run.status, run.notes
  into v_all_time_status, v_all_time_notes
  from public.leaderboard_recalculation_runs as run
  where run.id = v_all_time_run_id;

  if v_all_time_status is distinct from 'completed' then
    update public.leaderboard_recalculation_runs
    set
      status = 'failed',
      finished_at = now(),
      notes = format(
        'Finalized Main/Pro restoration all-time recalculation failed: %s',
        coalesce(
          nullif(v_all_time_notes, ''),
          v_all_time_status,
          'unknown'
        )
      )
    where id = v_run_id;
  end if;

  return v_run_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.recalculate_leaderboard_for_tournament(p_tournament_id uuid, p_triggered_by_clerk_user_id text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_run_id uuid;
  v_status text;
  v_bracket record;
  v_reconciled integer := 0;
  v_error_state text;
begin
  perform public.leaderboard_require_write_access();
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('ironclad:leaderboard:all-time', 0)
  );

  select tournament.status
  into v_status
  from public.tournaments as tournament
  where tournament.id = p_tournament_id
  for update;

  if not found then
    raise exception 'Tournament not found';
  end if;
  if v_status in ('cancelled', 'voided') then
    raise exception 'A terminal Event cannot be reconciled'
      using errcode = '55000';
  end if;

  insert into public.leaderboard_recalculation_runs (
    tournament_id,
    scope,
    status,
    triggered_by_clerk_user_id
  )
  values (
    p_tournament_id,
    'tournament',
    'pending',
    nullif(pg_catalog.btrim(p_triggered_by_clerk_user_id), '')
  )
  returning id into v_run_id;

  begin
    for v_bracket in
      select bracket.id
      from public.tournament_brackets as bracket
      join public.generated_brackets as generated
        on generated.tournament_bracket_id = bracket.id
      where bracket.tournament_id = p_tournament_id
        and bracket.launched_at is not null
        and bracket.name in ('Academy', 'Challenge', 'Main')
        and public.is_generated_bracket_complete(generated.id)
        and not exists (
          select 1
          from public.tournament_division_not_held_closures as closure
          where closure.tournament_bracket_id = bracket.id
        )
      order by bracket.id
    loop
      perform public.settle_leaderboard_division(
        v_bracket.id,
        p_triggered_by_clerk_user_id
      );
      v_reconciled := v_reconciled + 1;
    end loop;

    update public.leaderboard_recalculation_runs
    set
      status = 'completed',
      finished_at = clock_timestamp(),
      notes = format(
        'Reconciled %s completed Division(s) through the canonical Division writer.',
        v_reconciled
      )
    where id = v_run_id;
  exception
    when query_canceled or assert_failure or others then
      get stacked diagnostics v_error_state = returned_sqlstate;
      update public.leaderboard_recalculation_runs
      set
        status = 'failed',
        finished_at = clock_timestamp(),
        notes = format(
          'Division coordinator failed: SQLSTATE %s',
          coalesce(v_error_state, 'unknown')
        )
      where id = v_run_id;
  end;

  return v_run_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.recalculate_leaderboard_for_tournament_without_terminal_guard(p_tournament_id uuid, p_triggered_by_clerk_user_id text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_run_id uuid;
  v_run_status text;
  v_season_id uuid;
  v_event_number smallint;
  v_previous_tournament_context text;
  v_deleted_participation_count integer;
  v_affected_season record;
  v_season_run_id uuid;
  v_season_run_status text;
  v_season_run_notes text;
  v_error_state text;
begin
  perform public.leaderboard_require_write_access();
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('ironclad:leaderboard:all-time', 0)
  );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'ironclad:leaderboard:tournament:'
        || coalesce(p_tournament_id::text, 'null'),
      0
    )
  );

  v_previous_tournament_context := pg_catalog.current_setting(
    'ironclad.leaderboard_tournament_id',
    true
  );
  perform pg_catalog.set_config(
    'ironclad.leaderboard_tournament_id',
    '',
    true
  );

  select assigned.season_id, assigned.qualifying_event_number
  into v_season_id, v_event_number
  from public.assign_leaderboard_tournament_season(p_tournament_id)
    as assigned;

  if v_event_number is not null then
    update public.leaderboard_tournament_season_memberships
    set scored_at = null
    where tournament_id = p_tournament_id;
  end if;

  begin
    perform pg_catalog.set_config(
      'ironclad.leaderboard_tournament_id',
      p_tournament_id::text,
      true
    );

    -- Preserve PR 2 administrative-progression interpretation while the
    -- hidden core produces the existing participation/progression awards.
    perform count(*)
    from public.tournament_matches as match
    join public.generated_brackets as generated
      on generated.id = match.generated_bracket_id
    join public.tournament_brackets as bracket
      on bracket.id = generated.tournament_bracket_id
    where bracket.tournament_id = p_tournament_id
      and match.outcome_type in (
        'automatic_bye',
        'deadline_double_forfeit',
        'empty_feeder'
      );

    v_run_id :=
      public.recalculate_leaderboard_for_tournament_without_matchup_outcomes(
        p_tournament_id,
        p_triggered_by_clerk_user_id
      );

    perform pg_catalog.set_config(
      'ironclad.leaderboard_tournament_id',
      coalesce(v_previous_tournament_context, ''),
      true
    );

    select run.status
    into v_run_status
    from public.leaderboard_recalculation_runs as run
    where run.id = v_run_id;

    if v_run_status is distinct from 'completed' then
      return v_run_id;
    end if;

    with result_match_counts as (
      select
        generated.tournament_bracket_id,
        participant.registration_id,
        count(distinct match.id)::integer as result_match_count
      from public.generated_brackets as generated
      join public.tournament_brackets as bracket
        on bracket.id = generated.tournament_bracket_id
        and bracket.tournament_id = p_tournament_id
      join public.tournament_matches as match
        on match.generated_bracket_id = generated.id
        and match.status = 'completed'
        and match.outcome_type is null
        and match.player_one_registration_id is not null
        and match.player_two_registration_id is not null
        and match.player_one_score is not null
        and match.player_two_score is not null
        and match.winner_registration_id is not null
      join lateral (
        values
          (match.player_one_registration_id),
          (match.player_two_registration_id)
      ) as participant(registration_id)
        on participant.registration_id is not null
      group by
        generated.tournament_bracket_id,
        participant.registration_id
    ),
    ranked_participation as (
      select
        event.id,
        row_number() over (
          partition by
            event.registration_id,
            event.tournament_bracket_id
          order by event.created_at, event.id
        ) as participation_number,
        coalesce(result_count.result_match_count, 0) as result_match_count
      from public.leaderboard_point_events as event
      left join result_match_counts as result_count
        on result_count.tournament_bracket_id = event.tournament_bracket_id
        and result_count.registration_id = event.registration_id
      where event.tournament_id = p_tournament_id
        and event.event_type = 'participation'
        and event.source in ('system', 'recalculation')
        and event.registration_id is not null
        and event.tournament_bracket_id is not null
    )
    delete from public.leaderboard_point_events as event
    using ranked_participation as ranked
    where event.id = ranked.id
      and ranked.participation_number > ranked.result_match_count;

    get diagnostics v_deleted_participation_count = row_count;

    perform public.award_leaderboard_late_entry_bonuses(
      p_tournament_id,
      p_triggered_by_clerk_user_id
    );

    if v_deleted_participation_count > 0 then
      insert into pg_temp.leaderboard_late_entry_affected_seasons (season_id)
      values (v_season_id)
      on conflict (season_id) do nothing;
    end if;

    for v_affected_season in
      select affected.season_id
      from pg_temp.leaderboard_late_entry_affected_seasons as affected
      order by affected.season_id
    loop
      v_season_run_id := public.recalculate_leaderboard_for_season(
        v_affected_season.season_id,
        p_triggered_by_clerk_user_id
      );

      select run.status, run.notes
      into v_season_run_status, v_season_run_notes
      from public.leaderboard_recalculation_runs as run
      where run.id = v_season_run_id;

      if v_season_run_status is distinct from 'completed' then
        raise exception 'Career bonus/participation recalculation failed: %',
          coalesce(
            nullif(v_season_run_notes, ''),
            v_season_run_status,
            'unknown'
          );
      end if;
    end loop;

    if v_event_number is not null then
      update public.leaderboard_tournament_season_memberships
      set scored_at = clock_timestamp()
      where tournament_id = p_tournament_id;

      perform public.finalize_leaderboard_main_season_if_ready(v_season_id);
    end if;

    return v_run_id;
  exception
    when query_canceled or assert_failure or others then
      get stacked diagnostics v_error_state = returned_sqlstate;

      perform pg_catalog.set_config(
        'ironclad.leaderboard_tournament_id',
        coalesce(v_previous_tournament_context, ''),
        true
      );

      insert into public.leaderboard_recalculation_runs (
        tournament_id,
        season_id,
        scope,
        status,
        finished_at,
        triggered_by_clerk_user_id,
        notes
      )
      values (
        p_tournament_id,
        v_season_id,
        'tournament',
        'failed',
        now(),
        nullif(pg_catalog.btrim(p_triggered_by_clerk_user_id), ''),
        format(
          'Tournament leaderboard recalculation failed after season assignment: SQLSTATE %s',
          coalesce(v_error_state, 'unknown')
        )
      )
      returning id into v_run_id;

      return v_run_id;
  end;
end;
$function$

CREATE OR REPLACE FUNCTION public.recalculate_leaderboard_on_tournament_completion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_status text;
  v_run_id uuid;
  v_run_status text;
  v_error_state text;
begin
  -- Leaderboard caches are a derived projection. Preserve the authoritative
  -- result transaction if projection repair fails, while leaving either the
  -- recalculation function's failed run or a best-effort sanitized fallback
  -- run for the existing manual administrator recovery path.
  begin
    select tournament.status
    into v_status
    from public.tournaments as tournament
    where tournament.id = new.id;

    if v_status = 'completed' then
      v_run_id := public.recalculate_leaderboard_for_tournament(new.id, null);

      select run.status
      into v_run_status
      from public.leaderboard_recalculation_runs as run
      where run.id = v_run_id;

      if v_run_status is distinct from 'completed' then
        return null;
      end if;
    end if;
  exception
    when query_canceled or assert_failure or others then
      get stacked diagnostics v_error_state = returned_sqlstate;

      begin
        insert into public.leaderboard_recalculation_runs (
          tournament_id,
          scope,
          status,
          finished_at,
          notes
        )
        values (
          new.id,
          'tournament',
          'failed',
          now(),
          format(
            'Automatic tournament leaderboard recalculation failed: SQLSTATE %s',
            coalesce(v_error_state, 'unknown')
          )
        );
      exception
        when query_canceled or assert_failure or others then
          raise warning using message = format(
            'Automatic leaderboard failure audit could not be persisted: SQLSTATE %s',
            coalesce(v_error_state, 'unknown')
          );
      end;
  end;

  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.recompute_tournament_lifecycle_status(p_tournament_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_current_status text;
  v_bracket_count integer;
begin
  select tournament.status
  into v_current_status
  from public.tournaments as tournament
  where tournament.id = p_tournament_id
  for update;

  if not found or v_current_status in ('cancelled', 'voided') then
    return;
  end if;

  select count(*)::integer
  into v_bracket_count
  from public.tournament_brackets as bracket
  where bracket.tournament_id = p_tournament_id;

  if v_bracket_count = 0 then
    return;
  end if;

  if exists (
    select 1
    from public.tournament_brackets as bracket
    where bracket.tournament_id = p_tournament_id
      and bracket.launched_at is null
  ) then
    if v_current_status = 'completed' then
      perform pg_catalog.set_config(
        'ironclad.explicit_division_launch',
        'on',
        true
      );
      update public.tournaments
      set status = 'in_progress'
      where id = p_tournament_id;
    end if;
    return;
  end if;

  if exists (
    select 1
    from public.tournament_brackets as bracket
    left join public.generated_brackets as generated
      on generated.tournament_bracket_id = bracket.id
    where bracket.tournament_id = p_tournament_id
      and (
        generated.id is null
        or public.is_generated_bracket_complete(generated.id)
          is distinct from true
      )
  ) then
    if v_current_status = 'completed' then
      perform pg_catalog.set_config(
        'ironclad.explicit_division_launch',
        'on',
        true
      );
      update public.tournaments
      set status = 'in_progress'
      where id = p_tournament_id;
    end if;
    return;
  end if;

  update public.tournaments
  set
    status = 'completed',
    registration_enabled = false
  where id = p_tournament_id
    and status <> 'completed';
end;
$function$

CREATE OR REPLACE FUNCTION public.reconcile_downstream_match(p_source_match_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_source public.tournament_matches%rowtype;
  v_source_round_number integer;
  v_format text;
  v_next_round_id uuid;
  v_next_match_number integer;
  v_next public.tournament_matches%rowtype;
  v_left public.tournament_matches%rowtype;
  v_right public.tournament_matches%rowtype;
  v_single_winner uuid;
  v_now timestamptz;
  v_next_is_final boolean;
begin
  select match.*
  into v_source
  from public.tournament_matches as match
  where match.id = p_source_match_id;

  if not found or v_source.status <> 'completed' then
    return;
  end if;

  select round.round_number, generated.format
  into v_source_round_number, v_format
  from public.bracket_rounds as round
  join public.generated_brackets as generated
    on generated.id = round.generated_bracket_id
  where round.id = v_source.round_id;

  if v_format <> 'single_elimination' then
    return;
  end if;

  select round.id
  into v_next_round_id
  from public.bracket_rounds as round
  where round.generated_bracket_id = v_source.generated_bracket_id
    and round.round_number = v_source_round_number + 1;

  if v_next_round_id is null then
    return;
  end if;

  v_next_is_final := not exists (
    select 1
    from public.bracket_rounds as round
    where round.generated_bracket_id = v_source.generated_bracket_id
      and round.round_number = v_source_round_number + 2
  );

  v_next_match_number := ceil(v_source.match_number / 2.0)::integer;

  select match.*
  into v_next
  from public.tournament_matches as match
  where match.round_id = v_next_round_id
    and match.match_number = v_next_match_number
  for update;

  if not found then
    raise exception 'Generated downstream match not found';
  end if;

  if v_next.status = 'completed' then
    return;
  end if;

  if v_next.status <> 'scheduled'
    or v_next.activation_version <> 0
    or v_next.activated_at is not null
    or v_next.deadline_at is not null
    or v_next.player_one_score is not null
    or v_next.player_two_score is not null
    or v_next.winner_registration_id is not null
    or v_next.official_result_submission_id is not null
    or v_next.official_result_decided_by is not null
    or v_next.official_result_decided_at is not null
    or v_next.deadline_ruled_at is not null
    or v_next.extension_minutes is not null
    or v_next.hold_started_at is not null
    or exists (
      select 1
      from public.match_result_submissions as submission
      where submission.match_id = v_next.id
    )
    or exists (
      select 1
      from public.match_result_report_groups as report_group
      where report_group.match_id = v_next.id
    ) then
    raise exception
      'Downstream match activity prevents feeder reconciliation';
  end if;

  select match.*
  into v_left
  from public.tournament_matches as match
  where match.round_id = v_source.round_id
    and match.match_number = (v_next_match_number * 2) - 1;

  select match.*
  into v_right
  from public.tournament_matches as match
  where match.round_id = v_source.round_id
    and match.match_number = v_next_match_number * 2;

  if v_left.id is null or v_right.id is null then
    raise exception 'Generated feeder matches not found';
  end if;

  update public.tournament_matches
  set
    player_one_registration_id = case
      when v_left.status = 'completed'
        then v_left.winner_registration_id
      else player_one_registration_id
    end,
    player_two_registration_id = case
      when v_right.status = 'completed'
        then v_right.winner_registration_id
      else player_two_registration_id
    end
  where id = v_next.id;

  if v_left.status <> 'completed' or v_right.status <> 'completed' then
    return;
  end if;

  if v_left.winner_registration_id is not null
    and v_right.winner_registration_id is not null then
    perform public.activate_tournament_match_if_ready(v_next.id, false);
    return;
  end if;

  v_now := clock_timestamp();
  v_single_winner := coalesce(
    v_left.winner_registration_id,
    v_right.winner_registration_id
  );

  if v_single_winner is not null then
    update public.tournament_matches
    set
      status = 'completed',
      winner_registration_id = v_single_winner,
      player_one_score = null,
      player_two_score = null,
      official_result_submission_id = null,
      official_result_decided_by = null,
      official_result_decided_at = null,
      outcome_type = 'automatic_bye',
      deadline_ruled_at = null
    where id = v_next.id;

    perform public.create_matchup_notifications(
      v_next.id,
      format(
        'automatic-advance:left:%s:%s:%s:right:%s:%s:%s',
        v_left.id,
        v_left.activation_version,
        extract(epoch from v_left.updated_at)::numeric(20, 6),
        v_right.id,
        v_right.activation_version,
        extract(epoch from v_right.updated_at)::numeric(20, 6)
      ),
      'match.automatic_advance',
      case
        when v_next_is_final
          then 'You are the division champion by walkover'
        else 'You advanced automatically'
      end,
      case
        when v_next_is_final
          then 'The other Final feeder produced no eligible player, so you became champion by walkover without a played match.'
        else 'The other feeder produced no eligible player, so you advanced without a played match.'
      end,
      jsonb_build_object(
        'deadlineEvent', 'automatic_advance',
        'outcomeType', 'automatic_bye',
        'championByWalkover', v_next_is_final,
        'resolvedAt', v_now
      ),
      array[v_single_winner]
    );
  else
    update public.tournament_matches
    set
      status = 'completed',
      player_one_registration_id = null,
      player_two_registration_id = null,
      player_one_score = null,
      player_two_score = null,
      winner_registration_id = null,
      official_result_submission_id = null,
      official_result_decided_by = null,
      official_result_decided_at = null,
      outcome_type = 'empty_feeder',
      deadline_ruled_at = null
    where id = v_next.id;
  end if;

  perform public.reconcile_downstream_match(v_next.id);
end;
$function$

CREATE OR REPLACE FUNCTION public.reconcile_tournament_waitlist(p_tournament_bracket_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
begin
  if exists (
    select 1
    from public.tournament_brackets as bracket
    join public.tournaments as tournament
      on tournament.id = bracket.tournament_id
    where bracket.id = p_tournament_bracket_id
      and (
        tournament.status in ('cancelled', 'voided')
        or exists (
          select 1
          from public.tournament_division_not_held_closures as closure
          where closure.tournament_bracket_id = bracket.id
        )
      )
  ) then
    return 0;
  end if;

  return public.reconcile_tournament_waitlist_without_terminal_guard(
    p_tournament_bracket_id
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.reconcile_tournament_waitlist_without_terminal_guard(p_tournament_bracket_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_tournament_id uuid;
  v_tournament_title text;
  v_bracket_name text;
  v_launched_at timestamptz;
  v_max_players integer;
  v_required_count integer;
  v_active_count integer;
  v_offered_count integer;
  v_vacancies integer;
  v_registration record;
  v_offer_created_at timestamptz;
  v_offer_expires_at timestamptz;
  v_issued integer := 0;
begin
  select
    bracket.tournament_id,
    tournament.title,
    bracket.name,
    bracket.launched_at,
    bracket.max_players
  into
    v_tournament_id,
    v_tournament_title,
    v_bracket_name,
    v_launched_at,
    v_max_players
  from public.tournament_brackets as bracket
  join public.tournaments as tournament
    on tournament.id = bracket.tournament_id
  where bracket.id = p_tournament_bracket_id
  for update of bracket;

  if not found then
    raise exception 'Tournament division not found';
  end if;

  if v_launched_at is not null then
    return 0;
  end if;

  -- Phase 3 capped the active review cohort at eight even when a legacy
  -- bracket retained a larger display capacity. Smaller historical brackets
  -- continue to honor their configured size.
  v_required_count := least(v_max_players, 8);

  select
    count(*) filter (
      where registration.registration_status in (
        'pending',
        'manual_review',
        'approved'
      )
    )::integer,
    count(*) filter (
      where registration.registration_status = 'waitlisted'
        and registration.waitlist_offer_status = 'offered'
    )::integer
  into v_active_count, v_offered_count
  from public.registrations as registration
  where registration.tournament_bracket_id = p_tournament_bracket_id;

  v_vacancies := greatest(
    v_required_count - v_active_count - v_offered_count,
    0
  );

  if v_vacancies = 0 then
    return 0;
  end if;

  for v_registration in
    select
      registration.id,
      registration.clerk_user_id
    from public.registrations as registration
    where registration.tournament_bracket_id = p_tournament_bracket_id
      and registration.registration_status = 'waitlisted'
      and registration.waitlist_offer_status is null
    order by registration.created_at, registration.id
    limit v_vacancies
    for update of registration
  loop
    v_offer_created_at := clock_timestamp();
    v_offer_expires_at := v_offer_created_at + interval '24 hours';

    update public.registrations
    set
      waitlist_offer_status = 'offered',
      waitlist_offer_created_at = v_offer_created_at,
      waitlist_offer_expires_at = v_offer_expires_at,
      waitlist_offer_resolved_at = null
    where id = v_registration.id
      and registration_status = 'waitlisted'
      and waitlist_offer_status is null;

    if found then
      insert into public.notifications (
        recipient_clerk_user_id,
        recipient_role,
        type,
        title,
        message,
        tournament_id,
        tournament_title,
        registration_id,
        metadata
      )
      values (
        v_registration.clerk_user_id,
        'player',
        'registration.waitlist_offer',
        'A tournament place is available',
        format(
          'A place is available in the %s division of %s. Accept or decline before %s.',
          v_bracket_name,
          v_tournament_title,
          to_char(
            v_offer_expires_at at time zone 'UTC',
            'YYYY-MM-DD HH24:MI "UTC"'
          )
        ),
        v_tournament_id,
        v_tournament_title,
        v_registration.id,
        jsonb_build_object(
          'registrationId', v_registration.id,
          'tournamentId', v_tournament_id,
          'bracketId', p_tournament_bracket_id,
          'bracketName', v_bracket_name,
          'offerExpiresAt', v_offer_expires_at
        )
      );

      v_issued := v_issued + 1;
    end if;
  end loop;

  return v_issued;
end;
$function$

CREATE OR REPLACE FUNCTION public.record_tournament_championship_path_authority()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_tournament_id uuid;
  v_round_number integer;
  v_expected_count integer;
  v_slot_count integer;
  v_round_count integer;
  v_min_round integer;
  v_max_round integer;
  v_topology_valid boolean;
  v_outcome record;
  v_registration_id uuid;
begin
  select bracket.tournament_id, round.round_number
  into v_tournament_id, v_round_number
  from public.bracket_rounds as round
  join public.generated_brackets as generated
    on generated.id = round.generated_bracket_id
  join public.tournament_brackets as bracket
    on bracket.id = generated.tournament_bracket_id
  where round.id = new.round_id
    and generated.format = 'single_elimination'
    and bracket.launched_at is not null
    and bracket.name in ('Academy', 'Challenge', 'Main');

  if v_tournament_id is null or new.outcome_type = 'empty_feeder' then
    return new;
  end if;

  select
    generated.slot_count,
    count(*)::integer,
    min(round.round_number),
    max(round.round_number)
  into v_slot_count, v_round_count, v_min_round, v_max_round
  from public.bracket_rounds as round
  join public.generated_brackets as generated
    on generated.id = round.generated_bracket_id
  where round.generated_bracket_id = new.generated_bracket_id
  group by generated.slot_count;

  v_topology_valid :=
    v_slot_count >= 2
    and v_round_count > 0
    and v_min_round = 1
    and v_max_round = v_round_count
    and v_slot_count = pg_catalog.power(2, v_round_count)::integer;

  -- The supported single-elimination generator uses complete power-of-two
  -- round topology. Unknown or malformed topology remains incomplete.
  if not coalesce(v_topology_valid, false) then
    return new;
  end if;

  v_expected_count := v_round_count;

  foreach v_registration_id in array ARRAY[
    new.player_one_registration_id,
    new.player_two_registration_id
  ] loop
    if v_registration_id is not null then
      select authority.outcome_kind, authority.finalized_at
      into v_outcome
      from public.match_participant_outcome_authority as authority
      where authority.match_id = new.id
        and authority.registration_id = v_registration_id
      order by authority.revision desc, authority.id desc
      limit 1;

      if v_outcome.outcome_kind is not null then
        perform public.append_tournament_championship_path_authority(
          v_tournament_id,
          v_registration_id,
          v_round_number,
          v_round_number,
          v_expected_count,
          new.id,
          new.generated_bracket_id,
          new.round_id,
          v_outcome.outcome_kind,
          'active',
          v_outcome.finalized_at,
          'match_authority',
          new.id,
          jsonb_build_object(
            'pathAuthorityOnly', true,
            'matchStatus', new.status
          )
        );
      end if;
    end if;
  end loop;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.record_tournament_match_authority()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_tournament_id uuid;
  v_source_type text;
  v_source_id uuid;
  v_finalized_at timestamptz;
  v_outcome_kind text;
  v_no_show_registration_id uuid;
  v_no_show_source_id uuid;
  v_report_group_source_id uuid;
  v_distinct_game_count integer := 0;
  v_min_game_number integer;
  v_max_game_number integer;
  v_conflicting_game_claims boolean := false;
  v_game_authority_complete boolean := false;
  v_proven_played boolean := false;
  v_participant_id uuid;
  v_submission record;
begin
  select bracket.tournament_id
  into v_tournament_id
  from public.generated_brackets as generated
  join public.tournament_brackets as bracket
    on bracket.id = generated.tournament_bracket_id
  where generated.id = new.generated_bracket_id;

  if v_tournament_id is null then
    return new;
  end if;

  if new.outcome_type = 'empty_feeder' then
    return new;
  end if;

  if new.outcome_type = 'automatic_bye'
    and new.player_one_registration_id is not null then
    perform public.append_match_participant_outcome_authority(
      new.id,
      v_tournament_id,
      new.player_one_registration_id,
      'automatic_bye',
      coalesce(new.deadline_ruled_at, clock_timestamp()),
      'derived_outcome',
      new.id,
      jsonb_build_object('outcome_type', 'automatic_bye')
    );
    return new;
  end if;

  if new.outcome_type = 'deadline_double_forfeit'
    and new.player_one_registration_id is not null
    and new.player_two_registration_id is not null then
    foreach v_participant_id in array ARRAY[
      new.player_one_registration_id,
      new.player_two_registration_id
    ] loop
      perform public.append_match_participant_outcome_authority(
        new.id,
        v_tournament_id,
        v_participant_id,
        'double_no_show',
        coalesce(new.deadline_ruled_at, clock_timestamp()),
        'derived_outcome',
        new.id,
        jsonb_build_object('outcome_type', 'deadline_double_forfeit')
      );
    end loop;
    return new;
  end if;

  if new.official_result_decided_at is null
    or new.winner_registration_id is null
    or new.outcome_type is not null then
    if (
      old.official_result_decided_at is not null
      and new.official_result_decided_at is null
    ) or (
      old.outcome_type is not null
      and new.outcome_type is null
    ) then
      foreach v_participant_id in array ARRAY[
        old.player_one_registration_id,
        old.player_two_registration_id
      ] loop
        if v_participant_id is not null then
          perform public.append_match_participant_outcome_authority(
            new.id,
            v_tournament_id,
            v_participant_id,
            'unknown',
            clock_timestamp(),
            'match_reset',
            new.id,
            jsonb_build_object('invalidates_previous', true)
          );
        end if;
      end loop;

      insert into public.match_game_result_authority (
        match_id,
        tournament_id,
        game_number,
        series_best_of,
        finalized_game_count,
        game_authority_complete,
        revision,
        supersedes_id,
        authority_state,
        finalized_at,
        source_type,
        source_id,
        source_metadata
      )
      select
        authority.match_id,
        authority.tournament_id,
        authority.game_number,
        authority.series_best_of,
        authority.finalized_game_count,
        authority.game_authority_complete,
        authority.revision + 1,
        authority.id,
        'invalidated',
        clock_timestamp(),
        'match_reset',
        new.id,
        jsonb_build_object('invalidates_previous', true)
      from (
        select distinct on (game.game_number)
          game.*
        from public.match_game_result_authority as game
        where game.match_id = new.id
        order by game.game_number, game.revision desc, game.id desc
      ) as authority
      where authority.authority_state = 'active';
    end if;
    return new;
  end if;

  v_source_type := 'match_finalization';
  v_source_id := coalesce(new.official_result_submission_id, new.id);
  v_finalized_at := new.official_result_decided_at;
  v_outcome_kind := 'unknown';

  select report_group.id,
    count(distinct submission.game_number)::integer,
    min(submission.game_number),
    max(submission.game_number)
  into v_report_group_source_id,
    v_distinct_game_count,
    v_min_game_number,
    v_max_game_number
  from public.match_result_report_groups as report_group
  left join public.match_result_submissions as submission
    on submission.report_group_id = report_group.id
    and submission.status = 'approved'
    and submission.game_number is not null
  where report_group.match_id = new.id
    and report_group.result_type = 'normal'
    and report_group.finalized_at is not null
    and report_group.status in ('confirmed', 'auto_approved', 'approved')
  group by report_group.id, report_group.finalized_at
  order by report_group.finalized_at desc, report_group.id desc
  limit 1;

  v_game_authority_complete :=
    v_report_group_source_id is not null
    and v_distinct_game_count =
      (new.player_one_score + new.player_two_score)
    and v_distinct_game_count > 0
    and v_min_game_number = 1
    and v_max_game_number = v_distinct_game_count;

  select exists (
    select 1
    from public.match_result_submissions as submission
    where submission.match_id = new.id
      and submission.report_group_id = v_report_group_source_id
      and submission.status = 'approved'
      and submission.game_number is not null
    group by submission.game_number
    having count(distinct submission.claimed_winner_registration_id) > 1
  )
  into v_conflicting_game_claims;

  v_game_authority_complete :=
    v_game_authority_complete and not v_conflicting_game_claims;

  v_proven_played := v_game_authority_complete;
  if v_proven_played then
    v_outcome_kind := 'played';
    v_source_id := v_report_group_source_id;
  end if;

  select report_group.no_show_registration_id, report_group.id
  into v_no_show_registration_id, v_no_show_source_id
  from public.match_result_report_groups as report_group
  where report_group.match_id = new.id
    and report_group.result_type = 'no_show'
    and report_group.finalized_at is not null
    and report_group.status in ('confirmed', 'auto_approved', 'approved')
    and report_group.no_show_status in ('confirmed', 'auto_confirmed', 'approved')
  order by report_group.finalized_at desc, report_group.id desc
  limit 1;

  if v_no_show_registration_id is not null then
    v_source_type := 'no_show_finalization';
    v_source_id := v_no_show_source_id;
    v_outcome_kind := 'unknown';
    v_proven_played := false;
  end if;

  foreach v_participant_id in array ARRAY[
    new.player_one_registration_id,
    new.player_two_registration_id
  ] loop
    if v_participant_id is not null then
      if v_no_show_registration_id is not null
        and v_participant_id = v_no_show_registration_id then
        v_outcome_kind := 'player_no_show';
      elsif v_no_show_registration_id is not null then
        v_outcome_kind := 'opponent_no_show';
      elsif v_proven_played then
        v_outcome_kind := 'played';
      else
        v_outcome_kind := 'unknown';
      end if;

      perform public.append_match_participant_outcome_authority(
        new.id,
        v_tournament_id,
        v_participant_id,
        v_outcome_kind,
        v_finalized_at,
        v_source_type,
        v_source_id,
        jsonb_build_object('winner_registration_id', new.winner_registration_id)
      );
    end if;
  end loop;

  if v_no_show_registration_id is null and v_proven_played then
    for v_submission in
      select distinct on (submission.game_number)
        submission.*
      from public.match_result_submissions as submission
      where submission.match_id = new.id
        and submission.report_group_id = v_report_group_source_id
        and submission.status = 'approved'
        and submission.game_number is not null
      order by submission.game_number, submission.id
    loop
      perform public.append_match_game_result_authority(
        new.id,
        v_tournament_id,
        v_submission.game_number,
        v_submission.claimed_winner_registration_id,
        case
          when v_submission.claimed_winner_registration_id =
            new.player_one_registration_id then new.player_two_registration_id
          else new.player_one_registration_id
        end,
        new.series_best_of,
        v_distinct_game_count,
        v_game_authority_complete,
        'match_finalization',
        v_finalized_at,
        v_submission.id,
        jsonb_build_object('submission_status', v_submission.status)
      );
    end loop;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.redact_match_room_messages(p_player_id uuid, p_room_id uuid, p_message_ids uuid[], p_actor_clerk_user_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET lock_timeout TO '2s'
 SET statement_timeout TO '60s'
AS $function$
declare v_actor uuid; n integer; s jsonb;
begin
  v_actor:=ironclad_private.match_room_privacy_actor(p_actor_clerk_user_id);
  if p_player_id is null or p_message_ids is null or cardinality(p_message_ids) not between 1 and 1000 or array_position(p_message_ids,null) is not null then
    raise exception 'Invalid bounded redaction' using errcode='22023'; end if;
  perform ironclad_private.lock_match_room_privacy(p_room_id);
  perform ironclad_private.match_room_privacy_actor(p_actor_clerk_user_id);
  if exists(select 1 from unnest(p_message_ids) as scope(message_id) where not exists(select 1 from public.match_messages m where m.id=scope.message_id and m.room_id=p_room_id and m.author_player_id=p_player_id)) then
    raise exception 'Redaction scope is not authored by subject' using errcode='42501'; end if;
  s:=ironclad_private.match_room_retention_state(p_room_id);
  if (s->>'formalCaseBlocked')::boolean or exists(select 1 from ironclad_private.match_room_retention_holds h where h.room_id=p_room_id
    and h.released_at is null and h.expires_at>now() and (h.message_ids is null or h.message_ids && p_message_ids)) then
    raise exception 'Retained case or hold prevents ordinary redaction' using errcode='55000'; end if;
  perform set_config('ironclad.match_room_privacy_redaction','on',true);
  with changed as (
    update public.match_messages m set body='[removed following privacy request]',actor_clerk_user_id=null
    where m.id=any(p_message_ids) and m.room_id=p_room_id and m.author_player_id=p_player_id and not exists(select 1 from ironclad_private.match_room_redactions r where r.message_id=m.id)
    returning id
  ) insert into ironclad_private.match_room_redactions(message_id) select id from changed;
  get diagnostics n=row_count;
  perform set_config('ironclad.match_room_privacy_redaction','off',true);
  if n>0 then insert into ironclad_private.match_room_privacy_audit(room_id,operation,actor_player_id,counts)
    values(p_room_id,'redact',v_actor,jsonb_build_object('redactedCount',n)); end if;
  return jsonb_build_object('redactedCount',n);
end $function$

CREATE OR REPLACE FUNCTION public.refresh_generated_bracket_on_approval()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_old_bracket_id uuid;
  v_new_bracket_id uuid;
begin
  if current_setting('ironclad.tournament_deletion', true) = 'on' then
    if tg_op = 'DELETE' then
      return old;
    end if;
    return new;
  end if;

  if tg_op = 'DELETE' or tg_op = 'UPDATE' then
    if old.registration_status = 'approved' then
      v_old_bracket_id := old.tournament_bracket_id;
    end if;
  end if;

  if tg_op = 'INSERT' or tg_op = 'UPDATE' then
    if new.registration_status = 'approved' then
      v_new_bracket_id := new.tournament_bracket_id;
    end if;
  end if;

  if tg_op = 'UPDATE' then
    if old.registration_status is not distinct from new.registration_status
      and old.tournament_bracket_id is not distinct from new.tournament_bracket_id then
      return new;
    end if;
  end if;

  if v_old_bracket_id is not null
    and public.is_tournament_bracket_regeneration_safe(v_old_bracket_id) then
    perform public.generate_tournament_bracket(
      v_old_bracket_id,
      'system:approval-change'
    );
  end if;

  if v_new_bracket_id is not null
    and v_new_bracket_id is distinct from v_old_bracket_id
    and public.is_tournament_bracket_regeneration_safe(v_new_bracket_id) then
    perform public.generate_tournament_bracket(
      v_new_bracket_id,
      'system:approval-change'
    );
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.refresh_phase4_registration_state()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_old_bracket_id uuid;
  v_new_bracket_id uuid;
  v_terminal_transition boolean :=
    coalesce(
      pg_catalog.current_setting(
        'ironclad.tournament_terminal_transition',
        true
      ),
      ''
    ) = 'on'
    and (
      session_user = 'postgres'
      or coalesce(auth.role(), '') = 'service_role'
    );
begin
  if v_terminal_transition then
    return new;
  end if;

  if current_setting('ironclad.tournament_deletion', true) = 'on' then
    return new;
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;

  if tg_op = 'INSERT' then
    if new.tournament_bracket_id is not null
      and new.registration_status = 'waitlisted'
      and new.waitlist_offer_status is null then
      perform public.reconcile_tournament_waitlist(
        new.tournament_bracket_id
      );
    end if;
    return new;
  end if;

  v_old_bracket_id := old.tournament_bracket_id;
  v_new_bracket_id := new.tournament_bracket_id;

  if old.registration_status = 'approved'
    and (
      new.registration_status <> 'approved'
      or v_old_bracket_id is distinct from v_new_bracket_id
    )
    and v_old_bracket_id is not null then
    perform public.reset_unlaunched_tournament_bracket_draft(
      v_old_bracket_id
    );
  end if;

  if new.registration_status = 'approved'
    and (
      old.registration_status <> 'approved'
      or v_old_bracket_id is distinct from v_new_bracket_id
    )
    and v_new_bracket_id is not null then
    perform public.reset_unlaunched_tournament_bracket_draft(
      v_new_bracket_id
    );
  end if;

  if v_old_bracket_id is not null
    and (
      (
        old.registration_status in (
          'pending',
          'manual_review',
          'approved'
        )
        and new.registration_status not in (
          'pending',
          'manual_review',
          'approved'
        )
      )
      or (
        old.registration_status = 'waitlisted'
        and old.waitlist_offer_status = 'offered'
        and not (
          new.registration_status = 'pending'
          and new.waitlist_offer_status = 'accepted'
        )
      )
    ) then
    perform public.reconcile_tournament_waitlist(v_old_bracket_id);
  elsif v_new_bracket_id is not null
    and tg_op = 'UPDATE'
    and old.waitlist_offer_status is null
    and new.waitlist_offer_status is null
    and new.registration_status = 'waitlisted' then
    perform public.reconcile_tournament_waitlist(v_new_bracket_id);
  end if;

  return new;
end;
$function$

