CREATE OR REPLACE FUNCTION public.refresh_tournament_registration_after_division_resolution()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_tournament_id uuid;
begin
  if tg_table_name = 'tournament_brackets' then
    if old.launched_at is not null or new.launched_at is null then
      return new;
    end if;
    v_tournament_id := new.tournament_id;
  else
    select bracket.tournament_id
    into v_tournament_id
    from public.tournament_brackets as bracket
    where bracket.id = new.tournament_bracket_id;
  end if;

  if not exists (
    select 1
    from public.tournament_brackets as bracket
    where bracket.tournament_id = v_tournament_id
      and bracket.launched_at is null
      and not exists (
        select 1
        from public.tournament_division_not_held_closures as closure
        where closure.tournament_bracket_id = bracket.id
      )
  ) then
    update public.tournaments as tournament
    set registration_enabled = false
    where tournament.id = v_tournament_id
      and tournament.registration_enabled is true;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.release_match_room_retention_hold(p_hold_id uuid, p_actor_clerk_user_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET lock_timeout TO '2s'
 SET statement_timeout TO '60s'
AS $function$
declare v_actor uuid; v_room uuid; n integer;
begin
  v_actor:=ironclad_private.match_room_privacy_actor(p_actor_clerk_user_id);
  select room_id into v_room from ironclad_private.match_room_retention_holds where id=p_hold_id;
  perform ironclad_private.lock_match_room_privacy(v_room);
  perform ironclad_private.match_room_privacy_actor(p_actor_clerk_user_id);
  update ironclad_private.match_room_retention_holds set released_at=clock_timestamp() where id=p_hold_id and released_at is null;
  get diagnostics n=row_count;
  if n>0 then insert into ironclad_private.match_room_privacy_audit(room_id,operation,actor_player_id,reference_id)
    values(v_room,'release_hold',v_actor,p_hold_id); end if;
  return jsonb_build_object('holdId',p_hold_id,'released',true);
end $function$

CREATE OR REPLACE FUNCTION public.release_tournament_match_deadline(p_match_id uuid, p_actor_clerk_user_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_match public.tournament_matches%rowtype;
  v_released_at timestamptz;
  v_deadline_at timestamptz;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'Not authorized';
  end if;

  if nullif(btrim(p_actor_clerk_user_id), '') is null then
    raise exception 'Releasing administrator is required';
  end if;

  select match.*
  into v_match
  from public.tournament_matches as match
  where match.id = p_match_id
  for update;

  if not found then
    raise exception 'Tournament match not found';
  end if;

  if v_match.status <> 'in_progress'
    or v_match.outcome_type is not null then
    raise exception 'Only an active matchup can be resumed';
  end if;

  if v_match.hold_started_at is null then
    raise exception 'This matchup has not used an administrative hold';
  end if;

  if v_match.hold_released_at is not null then
    raise exception 'This matchup hold has already been released';
  end if;

  v_released_at := clock_timestamp();
  v_deadline_at := v_match.deadline_at
    + (v_released_at - v_match.hold_started_at);

  update public.tournament_matches
  set
    deadline_at = v_deadline_at,
    hold_released_at = v_released_at
  where id = p_match_id;

  perform public.create_matchup_notifications(
    p_match_id,
    'hold:released',
    'match.deadline_updated',
    'Match deadline resumed',
    'The administrative hold ended. Your restored deadline is shown in the match.',
    jsonb_build_object(
      'deadlineEvent', 'deadline_updated',
      'updateKind', 'resumed',
      'holdReleasedAt', v_released_at,
      'deadlineAt', v_deadline_at
    )
  );

  return jsonb_build_object(
    'match_id', p_match_id,
    'hold_released_at', v_released_at,
    'deadline_at', v_deadline_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.repair_generated_bracket_matches(p_generated_bracket_id uuid, p_repaired_by text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_format text;
  v_slot_count integer;
  v_round_id uuid;
  v_round_count integer;
  v_round_number integer;
  v_match_count integer;
  v_match_number integer;
  v_round_name text;
  v_first_slot integer;
  v_second_slot integer;
  v_first_slot_registration_ids uuid[];
  v_second_slot_registration_ids uuid[];
  v_first_slot_occurrences integer;
  v_second_slot_occurrences integer;
  v_player_one_registration_id uuid;
  v_player_two_registration_id uuid;
  v_has_assignments boolean;
  v_inserted integer;
  v_total_inserted integer := 0;
begin
  if p_repaired_by is null or btrim(p_repaired_by) = '' then
    raise exception 'Repairing administrator is required';
  end if;

  select generated.format, generated.slot_count
  into v_format, v_slot_count
  from public.generated_brackets as generated
  where generated.id = p_generated_bracket_id
  for update;

  if not found then
    raise exception 'Generated bracket not found';
  end if;

  if v_slot_count < 2 then
    raise exception 'Generated bracket must contain at least two slots';
  end if;

  if v_format = 'single_elimination' then
    if (v_slot_count & (v_slot_count - 1)) <> 0 then
      raise exception 'Single-elimination slot count must be a power of two';
    end if;

    v_round_count := log(2, v_slot_count)::integer;

    for v_round_number in 1..v_round_count loop
      v_match_count :=
        v_slot_count / power(2, v_round_number)::integer;
      v_round_name := case
        when v_match_count = 1 then 'Grand Final'
        when v_match_count = 2 then 'Semi Finals'
        when v_match_count = 4 then 'Quarter Finals'
        else 'Round of ' || (v_match_count * 2)::text
      end;

      insert into public.bracket_rounds (
        generated_bracket_id,
        round_number,
        name
      )
      values (
        p_generated_bracket_id,
        v_round_number,
        v_round_name
      )
      on conflict (generated_bracket_id, round_number)
      do update set name = excluded.name
      returning id into v_round_id;

      for v_match_number in 1..v_match_count loop
        v_first_slot := ((v_match_number - 1) * 2) + 1;
        v_second_slot := v_first_slot + 1;

        insert into public.tournament_matches (
          generated_bracket_id,
          round_id,
          match_number,
          player_one_slot,
          player_two_slot
        )
        values (
          p_generated_bracket_id,
          v_round_id,
          v_match_number,
          case when v_round_number = 1 then v_first_slot else null end,
          case when v_round_number = 1 then v_second_slot else null end
        )
        on conflict (round_id, match_number) do nothing;

        get diagnostics v_inserted = row_count;
        v_total_inserted := v_total_inserted + v_inserted;
      end loop;
    end loop;
  elsif v_format = 'round_robin' then
    select exists (
      select 1
      from public.tournament_matches as match
      where match.generated_bracket_id = p_generated_bracket_id
        and (
          match.player_one_registration_id is not null
          or match.player_two_registration_id is not null
        )
    )
    into v_has_assignments;

    insert into public.bracket_rounds (
      generated_bracket_id,
      round_number,
      name
    )
    values (p_generated_bracket_id, 1, 'Round Robin')
    on conflict (generated_bracket_id, round_number)
    do update set name = excluded.name
    returning id into v_round_id;

    v_match_number := 0;
    for v_first_slot in 1..(v_slot_count - 1) loop
      for v_second_slot in (v_first_slot + 1)..v_slot_count loop
        v_match_number := v_match_number + 1;

        select coalesce(
          array_agg(slot_assignment.registration_id),
          array[]::uuid[]
        )
        into v_first_slot_registration_ids
        from (
          select match.player_one_registration_id as registration_id
          from public.tournament_matches as match
          where match.generated_bracket_id = p_generated_bracket_id
            and match.player_one_slot = v_first_slot
            and match.player_one_registration_id is not null
          union
          select match.player_two_registration_id
          from public.tournament_matches as match
          where match.generated_bracket_id = p_generated_bracket_id
            and match.player_two_slot = v_first_slot
          and match.player_two_registration_id is not null
        ) as slot_assignment;

        select count(*)
        into v_first_slot_occurrences
        from public.tournament_matches as match
        where match.generated_bracket_id = p_generated_bracket_id
          and (
            match.player_one_slot = v_first_slot
            or match.player_two_slot = v_first_slot
          );

        select coalesce(
          array_agg(slot_assignment.registration_id),
          array[]::uuid[]
        )
        into v_second_slot_registration_ids
        from (
          select match.player_one_registration_id as registration_id
          from public.tournament_matches as match
          where match.generated_bracket_id = p_generated_bracket_id
            and match.player_one_slot = v_second_slot
            and match.player_one_registration_id is not null
          union
          select match.player_two_registration_id
          from public.tournament_matches as match
          where match.generated_bracket_id = p_generated_bracket_id
            and match.player_two_slot = v_second_slot
          and match.player_two_registration_id is not null
        ) as slot_assignment;

        select count(*)
        into v_second_slot_occurrences
        from public.tournament_matches as match
        where match.generated_bracket_id = p_generated_bracket_id
          and (
            match.player_one_slot = v_second_slot
            or match.player_two_slot = v_second_slot
          );

        if cardinality(v_first_slot_registration_ids) > 1 then
          raise exception
            'Cannot repair round-robin bracket because slot % has conflicting participant assignments',
            v_first_slot;
        end if;

        if cardinality(v_second_slot_registration_ids) > 1 then
          raise exception
            'Cannot repair round-robin bracket because slot % has conflicting participant assignments',
            v_second_slot;
        end if;

        v_player_one_registration_id :=
          v_first_slot_registration_ids[1];
        v_player_two_registration_id :=
          v_second_slot_registration_ids[1];

        if v_has_assignments
          and (
            v_first_slot_occurrences = 0
            or v_second_slot_occurrences = 0
          ) then
          raise exception
            'Cannot repair round-robin match % because assignment data for slots % and % could not be recovered',
            v_match_number,
            v_first_slot,
            v_second_slot;
        end if;

        insert into public.tournament_matches (
          generated_bracket_id,
          round_id,
          match_number,
          player_one_slot,
          player_two_slot,
          player_one_registration_id,
          player_two_registration_id
        )
        values (
          p_generated_bracket_id,
          v_round_id,
          v_match_number,
          v_first_slot,
          v_second_slot,
          v_player_one_registration_id,
          v_player_two_registration_id
        )
        on conflict (round_id, match_number) do nothing;

        get diagnostics v_inserted = row_count;
        v_total_inserted := v_total_inserted + v_inserted;
      end loop;
    end loop;
  else
    raise exception 'Unsupported generated bracket format';
  end if;

  return v_total_inserted;
end;
$function$

CREATE OR REPLACE FUNCTION public.request_match_room_assistance(p_room_id uuid, p_expected_request_version bigint DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare v_sub text := ironclad_private.match_room_actor(); v_room public.match_rooms%rowtype;
  v_state public.match_room_assistance%rowtype; v_registration_id uuid; v_version bigint;
  v_tournament_id uuid; v_title text; v_notification_id uuid;
begin
  if p_room_id is null or p_expected_request_version is null or p_expected_request_version not between 0 and 9007199254740991 then
    raise exception 'Invalid assistance request' using errcode = '22023';
  end if;
  perform ironclad_private.require_match_room_enabled();
  v_room := ironclad_private.match_room_access(p_room_id, v_sub);
  perform ironclad_private.require_current_account_legal_acceptance();
  select * into v_state from public.match_room_assistance where room_id = p_room_id for update;
  if v_state.status = 'requested' then
    return ironclad_private.match_room_assistance_projection(p_room_id);
  end if;
  if p_expected_request_version <> coalesce(v_state.request_version, 0) then
    raise exception 'Assistance request changed' using errcode = '40001';
  end if;
  v_version := coalesce(v_state.request_version, 0) + 1;
  select id into v_registration_id from public.registrations
  where id in (v_room.player_one_registration_id, v_room.player_two_registration_id) and clerk_user_id = v_sub;
  select r.tournament_id, t.title into v_tournament_id, v_title
  from public.registrations r join public.tournaments t on t.id = r.tournament_id
  where r.id = v_room.player_one_registration_id;
  insert into public.notifications(recipient_role, type, title, message,
    tournament_id, tournament_title, match_id, event_key, metadata)
  values('admin', 'match.admin_assistance_requested', 'Match Admin Assistance Requested',
    'A Match Room requires administrator assistance.', v_tournament_id, v_title, v_room.match_id,
    'match-room:' || p_room_id || ':assistance:' || v_version,
    jsonb_build_object('source', 'match_room_assistance', 'roomId', p_room_id, 'roomRevision', v_room.room_revision, 'requestVersion', v_version))
  returning id into v_notification_id;
  insert into public.match_room_assistance(room_id, status, request_version, requested_by_registration_id, notification_id)
  values(p_room_id, 'requested', v_version, v_registration_id, v_notification_id)
  on conflict(room_id) do update set status = 'requested', request_version = excluded.request_version,
    requested_by_registration_id = excluded.requested_by_registration_id,
    requested_at = clock_timestamp(), resolved_at = null, resolved_by_clerk_user_id = null,
    notification_id = excluded.notification_id;
  return ironclad_private.match_room_assistance_projection(p_room_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.require_registration_acceptance_on_commit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_has_canonical_acceptance boolean;
  v_has_fixture_evidence boolean;
begin
  if not exists (
    select 1
    from public.registrations as registration
    where registration.id = new.id
  ) then
    if exists (
      select 1
      from public.registration_acceptances as acceptance
      where acceptance.registration_id = new.id
    ) or exists (
      select 1
      from ironclad_private.staging_synthetic_uat_enrolments as fixture
      where fixture.registration_id = new.id
    ) then
      raise exception
        'Registration evidence cannot outlive a registration created in the same transaction'
        using errcode = '23514';
    end if;

    return null;
  end if;

  select exists (
    select 1
    from public.registration_acceptances as acceptance
    where acceptance.registration_id = new.id
      and acceptance.clerk_user_id = new.clerk_user_id
      and acceptance.tournament_id = new.tournament_id
      and acceptance.accepted_at >= new.created_at
  ) into v_has_canonical_acceptance;

  select exists (
    select 1
    from ironclad_private.staging_synthetic_uat_enrolments as fixture
    where fixture.registration_id = new.id
      and fixture.player_id = new.profile_id
      and fixture.tournament_id = new.tournament_id
      and fixture.tournament_bracket_id = new.tournament_bracket_id
      and fixture.synthetic_elo = new.submitted_elo
      and fixture.provenance = new.registration_provenance
      and fixture.contract_version = new.fixture_contract_version
      and fixture.steam_openid_verified is false
      and fixture.steam_ownership_verified is false
      and fixture.relic_live_lookup_verified is false
      and fixture.linked_steam_legal_confirmation is false
  ) into v_has_fixture_evidence;

  if v_has_canonical_acceptance = v_has_fixture_evidence then
    raise exception
      'Every new registration requires exactly one atomic evidence contract'
      using errcode = '23514';
  end if;

  if v_has_canonical_acceptance and (
    new.registration_provenance is not null
    or new.fixture_contract_version is not null
  ) then
    raise exception 'Canonical acceptance cannot mark synthetic provenance'
      using errcode = '23514';
  end if;

  if v_has_fixture_evidence and (
    new.registration_provenance is distinct from 'staging_synthetic_uat'
    or new.fixture_contract_version is distinct from
      'staging-synthetic-v1'
    or new.elo_verification_source is not null
  ) then
    raise exception 'Synthetic fixture evidence is invalid'
      using errcode = '23514';
  end if;

  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.reset_unlaunched_tournament_bracket_draft(p_tournament_bracket_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_launched_at timestamptz;
  v_deleted_count integer;
begin
  select bracket.launched_at
  into v_launched_at
  from public.tournament_brackets as bracket
  where bracket.id = p_tournament_bracket_id
  for update;

  if not found then
    return false;
  end if;

  if v_launched_at is not null then
    raise exception 'Launched division brackets cannot be reset';
  end if;

  if not public.is_tournament_bracket_regeneration_safe(
    p_tournament_bracket_id
  ) then
    raise exception
      'Private bracket reset blocked because result activity exists';
  end if;

  delete from public.generated_brackets
  where tournament_bracket_id = p_tournament_bracket_id;
  get diagnostics v_deleted_count = row_count;

  return v_deleted_count > 0;
end;
$function$

CREATE OR REPLACE FUNCTION public.resolve_match_room(p_match_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_sub text := ironclad_private.match_room_actor(); v_context jsonb; v_room public.match_rooms%rowtype; v_enabled boolean;
begin
  if p_match_id is null then raise exception 'Invalid Match Room request' using errcode = '22023'; end if;
  v_enabled := ironclad_private.match_room_writes_enabled();
  v_context := ironclad_private.match_room_context(p_match_id);
  if v_context is null or (coalesce(auth.jwt() -> 'metadata' ->> 'role', '') <> 'admin'
    and not exists (select 1 from public.registrations r
      where r.id in ((v_context ->> 'playerOne')::uuid, (v_context ->> 'playerTwo')::uuid)
        and r.clerk_user_id = v_sub)) then
    raise exception 'Match Room unavailable' using errcode = '42501';
  end if;
  select * into v_room from public.match_rooms
  where match_id = p_match_id and communication_generation = (v_context ->> 'generation')::bigint;
  if not found then
    if not v_enabled or not (v_context ->> 'eligible')::boolean or not (v_context ->> 'writable')::boolean then
      return jsonb_build_object('room', null);
    end if;
    -- Defensive closure also handles imported legacy communication rows.
    update public.match_rooms set closed_at = clock_timestamp(), closure_reason = 'lifecycle_changed'
    where match_id = p_match_id and closed_at is null;
    insert into public.match_rooms(match_id, room_revision, communication_generation,
      activation_version_snapshot, player_one_registration_id, player_two_registration_id)
    values (p_match_id, (v_context ->> 'generation')::bigint, (v_context ->> 'generation')::bigint,
      (v_context ->> 'activation')::integer, (v_context ->> 'playerOne')::uuid, (v_context ->> 'playerTwo')::uuid)
    returning * into v_room;
  end if;
  v_room := ironclad_private.match_room_access(v_room.id, v_sub);
  return jsonb_build_object('room', ironclad_private.match_room_projection(v_room, v_sub));
end;
$function$

CREATE OR REPLACE FUNCTION public.resolve_match_room_assistance(p_room_id uuid, p_expected_request_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare v_sub text := ironclad_private.match_room_actor(); v_state public.match_room_assistance%rowtype; v_notice record;
begin
  if coalesce(auth.jwt() -> 'metadata' ->> 'role', '') <> 'admin' then
    raise exception 'Match Room unavailable' using errcode = '42501';
  end if;
  if p_room_id is null or p_expected_request_version is null or p_expected_request_version not between 1 and 9007199254740991 then
    raise exception 'Invalid assistance request' using errcode = '22023';
  end if;
  perform ironclad_private.require_match_room_enabled();
  perform ironclad_private.match_room_access(p_room_id, v_sub);
  perform ironclad_private.require_current_account_legal_acceptance();
  select * into v_state from public.match_room_assistance where room_id = p_room_id for update;
  if not found or v_state.request_version <> p_expected_request_version then
    raise exception 'Assistance request changed' using errcode = '40001';
  end if;
  if v_state.status = 'requested' then
    update public.match_room_assistance set status = 'resolved', resolved_at = clock_timestamp(),
      resolved_by_clerk_user_id = v_sub where room_id = p_room_id;
    for v_notice in select id from public.notifications
      where type = 'match.admin_assistance_requested' and metadata ->> 'roomId' = p_room_id::text
        and match_id = (select match_id from public.match_rooms where id = p_room_id)
    loop
      perform ironclad_private.finish_match_room_notification(v_notice.id, true);
    end loop;
  end if;
  return ironclad_private.match_room_assistance_projection(p_room_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.respond_to_tournament_division_invitation(p_invitation_id uuid, p_recipient_clerk_user_id text, p_response text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_invitation public.tournament_division_invitations%rowtype;
  v_recipient public.players%rowtype;
  v_target_tournament_id uuid;
  v_target_tournament_bracket_id uuid;
  v_target_tournament_slug text;
  v_response text := pg_catalog.lower(coalesce(pg_catalog.btrim(p_response), ''));
  v_actor text := nullif(pg_catalog.btrim(p_recipient_clerk_user_id), '');
  v_resolved_at timestamptz;
begin
  if session_user <> 'postgres'
    and coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'Division invitation response requires the trusted server boundary'
      using errcode = '42501';
  end if;

  if p_invitation_id is null
    or v_actor is null
    or pg_catalog.char_length(v_actor) > 256
    or v_response not in ('accept', 'decline') then
    raise exception 'Division invitation response is invalid'
      using errcode = '22023';
  end if;

  select invitation.*
  into v_invitation
  from public.tournament_division_invitations as invitation
  where invitation.id = p_invitation_id;

  if not found then
    raise exception 'Division invitation is unavailable'
      using errcode = 'P0002';
  end if;

  v_target_tournament_bracket_id :=
    v_invitation.target_tournament_bracket_id;

  select player.*
  into v_recipient
  from public.players as player
  where player.id = v_invitation.recipient_player_id
    and player.clerk_user_id = v_actor
    and player.account_closed_at is null
  for update;

  if not found then
    raise exception 'Division invitation is unavailable'
      using errcode = '42501';
  end if;

  select tournament.id, tournament.slug
  into v_target_tournament_id, v_target_tournament_slug
  from public.tournament_brackets as bracket
  join public.tournaments as tournament
    on tournament.id = bracket.tournament_id
  where bracket.id = v_target_tournament_bracket_id
  for update of tournament, bracket;

  if not found then
    raise exception 'Division invitation is unavailable'
      using errcode = 'P0002';
  end if;

  -- Lifecycle writers lock the target before invalidating invitations, while
  -- account closure locks the recipient first. Follow that established order
  -- before taking the invitation lock so response cannot deadlock either path.
  select invitation.*
  into v_invitation
  from public.tournament_division_invitations as invitation
  where invitation.id = p_invitation_id
    and invitation.recipient_player_id = v_recipient.id
    and invitation.target_tournament_bracket_id =
      v_target_tournament_bracket_id
  for update;

  if not found then
    raise exception 'Division invitation is unavailable'
      using errcode = 'P0002';
  end if;

  perform public.reconcile_tournament_division_invitations(
    v_target_tournament_id,
    v_target_tournament_bracket_id,
    v_invitation.recipient_player_id
  );

  select invitation.*
  into v_invitation
  from public.tournament_division_invitations as invitation
  where invitation.id = p_invitation_id;

  if v_invitation.status = 'invalidated' then
    return pg_catalog.jsonb_build_object(
      'invitationId', v_invitation.id,
      'status', v_invitation.status,
      'invalidationReason', v_invitation.invalidation_reason,
      'targetTournamentId', v_target_tournament_id,
      'targetTournamentSlug', v_target_tournament_slug,
      'targetTournamentBracketId',
        v_invitation.target_tournament_bracket_id
    );
  end if;

  if (v_response = 'accept' and v_invitation.status = 'accepted')
    or (v_response = 'decline' and v_invitation.status = 'declined') then
    return pg_catalog.jsonb_build_object(
      'invitationId', v_invitation.id,
      'status', v_invitation.status,
      'targetTournamentId', v_target_tournament_id,
      'targetTournamentSlug', v_target_tournament_slug,
      'targetTournamentBracketId',
        v_invitation.target_tournament_bracket_id
    );
  end if;

  if v_invitation.status <> 'pending' then
    raise exception 'Division invitation has already been resolved'
      using errcode = '55000';
  end if;

  v_resolved_at := pg_catalog.clock_timestamp();
  update public.tournament_division_invitations as invitation
  set
    status = case when v_response = 'accept' then 'accepted' else 'declined' end,
    accepted_at = case when v_response = 'accept' then v_resolved_at else null end,
    declined_at = case when v_response = 'decline' then v_resolved_at else null end
  where invitation.id = p_invitation_id
  returning invitation.* into v_invitation;

  return pg_catalog.jsonb_build_object(
    'invitationId', v_invitation.id,
    'status', v_invitation.status,
    'targetTournamentId', v_target_tournament_id,
    'targetTournamentSlug', v_target_tournament_slug,
    'targetTournamentBracketId', v_invitation.target_tournament_bracket_id
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.respond_to_waitlist_offer(p_registration_id uuid, p_response text)
 RETURNS TABLE(registration_id uuid, tournament_id uuid, tournament_bracket_id uuid, registration_status text, waitlist_offer_status text, waitlist_offer_resolved_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_clerk_user_id text;
  v_tournament_bracket_id uuid;
  v_registration public.registrations%rowtype;
  v_launched_at timestamptz;
  v_resolved_at timestamptz;
begin
  if coalesce(auth.role(), '') <> 'authenticated' then
    raise exception 'Not authorized';
  end if;

  v_clerk_user_id := nullif(auth.jwt() ->> 'sub', '');
  if v_clerk_user_id is null then
    raise exception 'Not authorized';
  end if;

  if p_response is null or p_response not in ('accept', 'decline') then
    raise exception 'Waitlist response must be accept or decline';
  end if;

  select registration.tournament_bracket_id
  into v_tournament_bracket_id
  from public.registrations as registration
  where registration.id = p_registration_id
    and registration.clerk_user_id = v_clerk_user_id;

  if not found or v_tournament_bracket_id is null then
    raise exception 'Waitlist offer not found';
  end if;

  select bracket.launched_at
  into v_launched_at
  from public.tournament_brackets as bracket
  where bracket.id = v_tournament_bracket_id
  for update;

  select registration.*
  into v_registration
  from public.registrations as registration
  where registration.id = p_registration_id
    and registration.clerk_user_id = v_clerk_user_id
    and registration.tournament_bracket_id = v_tournament_bracket_id
  for update;

  if not found
    or v_registration.registration_status <> 'waitlisted'
    or v_registration.waitlist_offer_status <> 'offered' then
    raise exception 'This waitlist offer is no longer available';
  end if;

  if v_launched_at is not null then
    raise exception 'This waitlist offer closed when the division launched';
  end if;

  if p_response = 'accept' then
    perform ironclad_private.require_current_account_legal_acceptance();
  end if;

  v_resolved_at := clock_timestamp();

  if v_resolved_at >= v_registration.waitlist_offer_expires_at then
    raise exception 'This waitlist offer has expired';
  end if;

  if p_response = 'accept' then
    update public.registrations
    set
      registration_status = 'pending',
      waitlist_offer_status = 'accepted',
      waitlist_offer_resolved_at = v_resolved_at
    where id = p_registration_id;

    registration_status := 'pending';
    waitlist_offer_status := 'accepted';
  else
    update public.registrations
    set
      waitlist_offer_status = 'declined',
      waitlist_offer_resolved_at = v_resolved_at
    where id = p_registration_id;

    registration_status := 'waitlisted';
    waitlist_offer_status := 'declined';
  end if;

  registration_id := v_registration.id;
  tournament_id := v_registration.tournament_id;
  tournament_bracket_id := v_registration.tournament_bracket_id;
  waitlist_offer_resolved_at := v_resolved_at;
  return next;
end;
$function$

CREATE OR REPLACE FUNCTION public.review_match_series_result(p_submission_id uuid, p_decision text, p_reviewed_by text, p_review_notes text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_match_id uuid;
  v_submission public.match_result_submissions%rowtype;
  v_match public.tournament_matches%rowtype;
  v_review_started_at timestamptz;
  v_resolved_at timestamptz;
begin
  select submission.match_id
  into v_match_id
  from public.match_result_submissions as submission
  where submission.id = p_submission_id;

  if not found then
    raise exception 'Match result submission not found';
  end if;

  select match.*
  into v_match
  from public.tournament_matches as match
  where match.id = v_match_id
  for update;

  if not found then
    raise exception 'Tournament match not found';
  end if;

  select submission.*
  into v_submission
  from public.match_result_submissions as submission
  where submission.id = p_submission_id
    and submission.match_id = v_match.id
  for update;

  if not found then
    raise exception using
      errcode = '40001',
      message = 'Match result conflict: the legacy submission changed before review';
  end if;

  select pg_catalog.min(submission.created_at)
  into v_review_started_at
  from public.match_result_submissions as submission
  where submission.match_id = v_submission.match_id
    and submission.status = 'pending'
    and submission.report_group_id is null;

  perform public.review_match_series_result_without_deadline_restore(
    p_submission_id,
    p_decision,
    p_reviewed_by,
    p_review_notes
  );

  if p_decision not in ('rejected', 'resubmission_requested') then
    return;
  end if;

  v_resolved_at := pg_catalog.clock_timestamp();

  update public.tournament_matches
  set
    status = 'in_progress',
    deadline_at = deadline_at + greatest(
      interval '0 seconds',
      v_resolved_at - coalesce(v_review_started_at, v_resolved_at)
    )
  where id = v_submission.match_id
    and status = 'scheduled'
    and activation_version > 0
    and deadline_at is not null
    and outcome_type is null;

  if not found then
    perform public.activate_tournament_match_if_ready(
      v_submission.match_id,
      false
    );
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.review_match_series_result_without_deadline_restore(p_submission_id uuid, p_decision text, p_reviewed_by text, p_review_notes text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_submission public.match_result_submissions%rowtype;
  v_match public.tournament_matches%rowtype;
  v_player_one_wins integer;
  v_player_two_wins integer;
  v_wins_required integer;
  v_series_winner uuid;
  v_pending_ids uuid[];
begin
  if p_reviewed_by is null or btrim(p_reviewed_by) = '' then
    raise exception 'Reviewing administrator is required';
  end if;

  if p_decision not in (
    'approved',
    'rejected',
    'resubmission_requested'
  ) then
    raise exception 'Invalid result review decision';
  end if;

  if p_decision in ('rejected', 'resubmission_requested')
    and nullif(btrim(p_review_notes), '') is null then
    raise exception
      'An administrator message is required for rejection or resubmission';
  end if;

  select submission.*
  into v_submission
  from public.match_result_submissions as submission
  where submission.id = p_submission_id
    and submission.status = 'pending'
    and submission.report_group_id is null
  for update;

  if not found then
    raise exception 'Pending ungrouped game report not found';
  end if;

  select match.*
  into v_match
  from public.tournament_matches as match
  where match.id = v_submission.match_id
  for update;

  if exists (
    select 1
    from public.match_result_report_groups as report_group
    where report_group.match_id = v_submission.match_id
      and report_group.status in (
        'pending_confirmation',
        'disputed',
        'under_review'
      )
      and report_group.finalized_at is null
  ) then
    raise exception
      'This match has an active confirmation report group. Use the report-group review workflow.';
  end if;

  select array_agg(submission.id)
  into v_pending_ids
  from public.match_result_submissions as submission
  where submission.match_id = v_submission.match_id
    and submission.status = 'pending'
    and submission.report_group_id is null;

  if p_decision <> 'approved' then
    update public.match_result_submissions
    set
      status = p_decision,
      reviewed_by = p_reviewed_by,
      review_notes = nullif(btrim(p_review_notes), ''),
      reviewed_at = now()
    where id = any(v_pending_ids);

    update public.tournament_matches
    set status = 'scheduled'
    where id = v_submission.match_id
      and status = 'pending_review'
      and not exists (
        select 1
        from public.match_result_report_groups as report_group
        where report_group.match_id = v_submission.match_id
          and report_group.status in (
            'pending_confirmation',
            'disputed',
            'under_review'
          )
          and report_group.finalized_at is null
      );
    return;
  end if;

  if exists (
    select 1
    from public.match_result_submissions as report
    where report.match_id = v_submission.match_id
      and report.status = 'pending'
      and report.report_group_id is null
    group by report.game_number
    having count(distinct report.claimed_winner_registration_id) > 1
  ) then
    raise exception 'Conflicting player reports must be resolved before approval';
  end if;

  with resolved_games as (
    select
      report.game_number,
      min(report.claimed_winner_registration_id::text)::uuid as winner_id
    from public.match_result_submissions as report
    where report.match_id = v_submission.match_id
      and report.status = 'pending'
      and report.report_group_id is null
    group by report.game_number
  )
  select
    count(*) filter (
      where winner_id = v_match.player_one_registration_id
    )::integer,
    count(*) filter (
      where winner_id = v_match.player_two_registration_id
    )::integer
  into v_player_one_wins, v_player_two_wins
  from resolved_games;

  v_wins_required := (v_match.series_best_of / 2) + 1;

  if greatest(v_player_one_wins, v_player_two_wins) <> v_wins_required
    or least(v_player_one_wins, v_player_two_wins) >= v_wins_required then
    raise exception
      'The reported games do not yet form a complete series result';
  end if;

  v_series_winner := case
    when v_player_one_wins > v_player_two_wins
      then v_match.player_one_registration_id
    else v_match.player_two_registration_id
  end;

  perform public.apply_official_match_result(
    v_match.id,
    v_player_one_wins,
    v_player_two_wins,
    v_series_winner,
    p_reviewed_by
  );

  update public.match_result_submissions
  set
    status = 'approved',
    reviewed_by = p_reviewed_by,
    review_notes = nullif(btrim(p_review_notes), ''),
    reviewed_at = now()
  where id = any(v_pending_ids);

  update public.tournament_matches
  set
    official_result_submission_id = p_submission_id,
    official_result_decided_by = p_reviewed_by,
    official_result_decided_at = now()
  where id = v_match.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.review_tournament_registration(p_registration_id uuid, p_registration_status text, p_admin_notes text DEFAULT NULL::text)
 RETURNS TABLE(registration_id uuid, tournament_id uuid, tournament_bracket_id uuid, registration_status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_tournament_bracket_id uuid;
  v_registration public.registrations%rowtype;
  v_launched_at timestamptz;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'Not authorized';
  end if;

  if p_registration_status not in (
    'pending',
    'manual_review',
    'approved',
    'rejected',
    'waitlisted',
    'withdrawn'
  ) then
    raise exception 'Invalid registration review status';
  end if;

  if p_admin_notes is not null and length(p_admin_notes) > 1000 then
    raise exception 'Administrator notes cannot exceed 1000 characters';
  end if;

  select registration.tournament_bracket_id
  into v_tournament_bracket_id
  from public.registrations as registration
  where registration.id = p_registration_id;

  if not found or v_tournament_bracket_id is null then
    raise exception 'Registration not found';
  end if;

  select bracket.launched_at
  into v_launched_at
  from public.tournament_brackets as bracket
  where bracket.id = v_tournament_bracket_id
  for update;

  select registration.*
  into v_registration
  from public.registrations as registration
  where registration.id = p_registration_id
    and registration.tournament_bracket_id = v_tournament_bracket_id
  for update;

  if not found then
    raise exception 'Registration not found';
  end if;

  if p_registration_status = 'withdrawn'
    and v_registration.registration_status <> 'withdrawn' then
    raise exception 'Only the player can withdraw a registration';
  end if;

  if p_registration_status = 'waitlisted'
    and v_registration.registration_status <> 'waitlisted' then
    raise exception 'Administrator review cannot move a player to waitlist';
  end if;

  if v_registration.registration_status = 'waitlisted'
    and p_registration_status not in ('waitlisted', 'rejected') then
    raise exception
      'Waitlisted players must accept an offer before administrator review';
  end if;

  if v_registration.registration_status = 'waitlisted'
    and v_registration.waitlist_offer_status in (
      'declined',
      'expired',
      'cancelled'
    )
    and p_registration_status <> 'waitlisted' then
    raise exception 'A resolved waitlist registration is final';
  end if;

  if v_registration.registration_status = 'withdrawn'
    and p_registration_status <> 'withdrawn' then
    raise exception 'A withdrawn registration is final';
  end if;

  if v_launched_at is not null
    and p_registration_status is distinct from
      v_registration.registration_status then
    raise exception
      'Roster review is blocked because this division has launched';
  end if;

  update public.registrations as registration
  set
    registration_status = p_registration_status,
    waitlist_offer_status = case
      when registration.registration_status = 'waitlisted'
        and registration.waitlist_offer_status = 'offered'
        and p_registration_status = 'rejected'
        then 'cancelled'
      else registration.waitlist_offer_status
    end,
    waitlist_offer_resolved_at = case
      when registration.registration_status = 'waitlisted'
        and registration.waitlist_offer_status = 'offered'
        and p_registration_status = 'rejected'
        then clock_timestamp()
      else registration.waitlist_offer_resolved_at
    end,
    admin_notes = case
      when p_admin_notes is null then registration.admin_notes
      else p_admin_notes
    end
  where registration.id = p_registration_id;

  registration_id := v_registration.id;
  tournament_id := v_registration.tournament_id;
  tournament_bracket_id := v_registration.tournament_bracket_id;
  registration_status := p_registration_status;
  return next;
end;
$function$

CREATE OR REPLACE FUNCTION public.roll_match_dice(p_match_id uuid, p_expected_activation_version integer, p_game_number smallint, p_expected_tie_round integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_match public.tournament_matches%rowtype;
  v_format text;
  v_tournament_id uuid;
  v_tournament_status text;
  v_launched_at timestamptz;
  v_clerk_user_id text := nullif(
    pg_catalog.btrim(auth.jwt() ->> 'sub'),
    ''
  );
  v_registration_id uuid;
  v_participant_slot text;
  v_existing_roll public.match_dice_rolls%rowtype;
  v_stored_roll public.match_dice_rolls%rowtype;
  v_latest_tie_round integer;
  v_latest_roll_count integer;
  v_latest_total_one integer;
  v_latest_total_two integer;
  v_required_tie_round integer;
  v_random_byte integer;
  v_die_1 smallint;
  v_die_2 smallint;
  v_created boolean := false;
begin
  if v_clerk_user_id is null then
    raise exception 'Authentication is required'
      using errcode = '28000';
  end if;

  if p_match_id is null
    or p_expected_activation_version is null
    or p_expected_activation_version < 1
    or p_game_number is null
    or p_game_number not in (1, 3, 5)
    or p_expected_tie_round is null
    or p_expected_tie_round < 1 then
    raise exception 'Invalid dice roll request'
      using errcode = '22023';
  end if;

  -- Match mutation paths in the established result/reset architecture lock
  -- this concrete Match first. The tournament SHARE lock below then makes
  -- cancellation/completion status changes linear with this insert.
  select match.*
  into v_match
  from public.tournament_matches as match
  where match.id = p_match_id
  for update;

  if not found then
    raise exception 'Dice roll-off is unavailable'
      using errcode = '42501';
  end if;

  select
    generated.format,
    bracket.tournament_id,
    bracket.launched_at
  into v_format, v_tournament_id, v_launched_at
  from public.generated_brackets as generated
  join public.tournament_brackets as bracket
    on bracket.id = generated.tournament_bracket_id
  where generated.id = v_match.generated_bracket_id;

  if not found then
    raise exception 'Dice roll-off is unavailable'
      using errcode = '42501';
  end if;

  select tournament.status
  into v_tournament_status
  from public.tournaments as tournament
  where tournament.id = v_tournament_id
  for share;

  if not found then
    raise exception 'Dice roll-off is unavailable'
      using errcode = '42501';
  end if;

  -- Resolve the exact current participant before returning any Match-state
  -- detail. An unrelated authenticated caller receives only the same generic
  -- refusal as an unknown Match; Admin metadata never grants write authority.
  select
    registration.id,
    case
      when registration.id = v_match.player_one_registration_id
        then 'player_one'
      else 'player_two'
    end
  into v_registration_id, v_participant_slot
  from public.registrations as registration
  where registration.clerk_user_id = v_clerk_user_id
    and registration.id in (
      v_match.player_one_registration_id,
      v_match.player_two_registration_id
    )
  order by registration.id
  limit 1;

  if v_registration_id is null then
    raise exception 'Dice roll-off is unavailable'
      using errcode = '42501';
  end if;

  perform ironclad_private.require_current_account_legal_acceptance();

  if v_format is distinct from 'single_elimination' then
    raise exception 'Dice Roll-Off supports single-elimination Matches only'
      using errcode = '55000';
  end if;

  if v_launched_at is null
    or v_tournament_status is distinct from 'in_progress'
    or v_match.status is distinct from 'in_progress'
    or v_match.player_one_registration_id is null
    or v_match.player_two_registration_id is null
    or v_match.player_one_registration_id =
      v_match.player_two_registration_id
    or v_match.activation_version < 1
    or v_match.official_result_submission_id is not null
    or v_match.winner_registration_id is not null
    or v_match.outcome_type is not null
    or (
      v_match.hold_started_at is not null
      and v_match.hold_released_at is null
    ) then
    raise exception 'Dice roll-off is not currently actionable'
      using errcode = '55000';
  end if;

  if v_match.deadline_at is null
    or pg_catalog.clock_timestamp() >= v_match.deadline_at then
    raise exception 'The Match deadline has elapsed'
      using errcode = '55000';
  end if;

  if v_match.activation_version <>
    p_expected_activation_version then
    raise exception 'The Match activation changed; refresh and try again'
      using errcode = '40001';
  end if;

  if v_match.series_best_of not in (3, 5) then
    raise exception 'This Series format is not supported for Dice Roll-Off'
      using errcode = '55000';
  end if;

  if p_game_number = 5 and v_match.series_best_of <> 5 then
    raise exception 'Game 5 Dice Roll-Off is available only for BO5 Matches'
      using errcode = '22023';
  end if;

  -- An exact retry is idempotent even if the opponent's tied roll has since
  -- opened the next round. Activation freshness was checked above, so a stale
  -- pre-reset tab cannot read or write through this mutation RPC.
  select roll.*
  into v_existing_roll
  from public.match_dice_rolls as roll
  where roll.match_id = p_match_id
    and roll.activation_version = p_expected_activation_version
    and roll.game_number = p_game_number
    and roll.tie_round = p_expected_tie_round
    and roll.participant_registration_id = v_registration_id;

  if found then
    return pg_catalog.jsonb_build_object(
      'snapshot', public.get_match_dice_rolloff(p_match_id),
      'roll', pg_catalog.jsonb_build_object(
        'activationVersion', v_existing_roll.activation_version,
        'gameNumber', v_existing_roll.game_number,
        'tieRound', v_existing_roll.tie_round,
        'participantSlot', v_participant_slot,
        'die1', v_existing_roll.die_1,
        'die2', v_existing_roll.die_2,
        'total', v_existing_roll.die_1 + v_existing_roll.die_2,
        'rolledAt', v_existing_roll.rolled_at,
        'created', false
      )
    );
  end if;

  select pg_catalog.max(roll.tie_round)
  into v_latest_tie_round
  from public.match_dice_rolls as roll
  where roll.match_id = p_match_id
    and roll.activation_version = p_expected_activation_version
    and roll.game_number = p_game_number;

  if v_latest_tie_round is null then
    v_required_tie_round := 1;
  else
    select
      pg_catalog.count(*)::integer,
      pg_catalog.max(roll.die_1 + roll.die_2) filter (
        where roll.participant_registration_id =
          v_match.player_one_registration_id
      ),
      pg_catalog.max(roll.die_1 + roll.die_2) filter (
        where roll.participant_registration_id =
          v_match.player_two_registration_id
      )
    into
      v_latest_roll_count,
      v_latest_total_one,
      v_latest_total_two
    from public.match_dice_rolls as roll
    where roll.match_id = p_match_id
      and roll.activation_version = p_expected_activation_version
      and roll.game_number = p_game_number
      and roll.tie_round = v_latest_tie_round;

    if v_latest_roll_count = 1 then
      v_required_tie_round := v_latest_tie_round;
    elsif v_latest_roll_count = 2
      and v_latest_total_one is not null
      and v_latest_total_two is not null
      and v_latest_total_one = v_latest_total_two then
      v_required_tie_round := v_latest_tie_round + 1;
    elsif v_latest_roll_count = 2
      and v_latest_total_one is not null
      and v_latest_total_two is not null then
      raise exception 'This Game Dice Roll-Off is already complete'
        using errcode = '55000';
    else
      raise exception 'Dice Roll-Off history is inconsistent'
        using errcode = '55000';
    end if;
  end if;

  if v_required_tie_round <> p_expected_tie_round then
    raise exception 'The tie round changed; refresh and try again'
      using errcode = '40001';
  end if;

  -- Staging preflight positively resolves pgcrypto's secure-byte function as
  -- extensions.gen_random_bytes(integer). Reject the four high byte values so
  -- every accepted d6 face owns exactly 42 of the 252 accepted byte values.
  loop
    v_random_byte := pg_catalog.get_byte(
      extensions.gen_random_bytes(1),
      0
    );
    exit when v_random_byte < 252;
  end loop;
  v_die_1 := (pg_catalog.mod(v_random_byte, 6) + 1)::smallint;

  loop
    v_random_byte := pg_catalog.get_byte(
      extensions.gen_random_bytes(1),
      0
    );
    exit when v_random_byte < 252;
  end loop;
  v_die_2 := (pg_catalog.mod(v_random_byte, 6) + 1)::smallint;

  insert into public.match_dice_rolls (
    match_id,
    activation_version,
    game_number,
    tie_round,
    participant_registration_id,
    die_1,
    die_2
  )
  values (
    p_match_id,
    p_expected_activation_version,
    p_game_number,
    p_expected_tie_round,
    v_registration_id,
    v_die_1,
    v_die_2
  )
  on conflict do nothing
  returning * into v_stored_roll;

  v_created := found;

  if not v_created then
    select roll.*
    into v_stored_roll
    from public.match_dice_rolls as roll
    where roll.match_id = p_match_id
      and roll.activation_version = p_expected_activation_version
      and roll.game_number = p_game_number
      and roll.tie_round = p_expected_tie_round
      and roll.participant_registration_id = v_registration_id;

    if not found then
      raise exception 'Dice roll could not be stored'
        using errcode = '40001';
    end if;
  end if;

  return pg_catalog.jsonb_build_object(
    'snapshot', public.get_match_dice_rolloff(p_match_id),
    'roll', pg_catalog.jsonb_build_object(
      'activationVersion', v_stored_roll.activation_version,
      'gameNumber', v_stored_roll.game_number,
      'tieRound', v_stored_roll.tie_round,
      'participantSlot', v_participant_slot,
      'die1', v_stored_roll.die_1,
      'die2', v_stored_roll.die_2,
      'total', v_stored_roll.die_1 + v_stored_roll.die_2,
      'rolledAt', v_stored_roll.rolled_at,
      'created', v_created
    )
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.save_bracket_assignments(p_generated_bracket_id uuid, p_assignments jsonb, p_updated_by text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_tournament_bracket_id uuid;
  v_tournament_id uuid;
  v_launched_at timestamptz;
  v_max_players integer;
  v_required_count integer;
  v_approved_count integer;
  v_unresolved_count integer;
  v_format text;
  v_slot_count integer;
  v_participant_count integer;
  v_assignment jsonb;
  v_slot_number integer;
  v_registration_id uuid;
  v_assigned_registration_ids uuid[] := array[]::uuid[];
  v_updated_rows integer;
  v_second_updated_rows integer;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'Not authorized';
  end if;

  if p_updated_by is null or btrim(p_updated_by) = '' then
    raise exception 'Updating administrator is required';
  end if;

  if p_assignments is null or jsonb_typeof(p_assignments) <> 'array' then
    raise exception 'Bracket assignments must be a JSON array';
  end if;

  select generated.tournament_bracket_id
  into v_tournament_bracket_id
  from public.generated_brackets as generated
  where generated.id = p_generated_bracket_id;

  if not found then
    raise exception 'Generated bracket not found';
  end if;

  select
    bracket.tournament_id,
    bracket.launched_at,
    bracket.max_players
  into
    v_tournament_id,
    v_launched_at,
    v_max_players
  from public.tournament_brackets as bracket
  where bracket.id = v_tournament_bracket_id
  for update;

  if not found then
    raise exception 'Tournament division not found';
  end if;

  if v_launched_at is not null then
    raise exception 'Bracket assignments cannot change after division launch';
  end if;

  select
    generated.format,
    generated.slot_count,
    generated.participant_count
  into v_format, v_slot_count, v_participant_count
  from public.generated_brackets as generated
  where generated.id = p_generated_bracket_id
    and generated.tournament_bracket_id = v_tournament_bracket_id
  for update;

  if not found then
    raise exception 'Generated bracket not found';
  end if;

  v_required_count := least(v_max_players, 8);

  select
    count(*) filter (
      where registration.registration_status = 'approved'
    )::integer,
    count(*) filter (
      where registration.registration_status in (
        'pending',
        'manual_review'
      )
        or (
          registration.registration_status = 'waitlisted'
          and registration.waitlist_offer_status = 'offered'
        )
    )::integer
  into v_approved_count, v_unresolved_count
  from public.registrations as registration
  where registration.tournament_bracket_id = v_tournament_bracket_id;

  if v_approved_count <> v_required_count
    or v_unresolved_count <> 0
    or v_slot_count <> v_required_count
    or v_participant_count <> v_required_count then
    raise exception
      'Private bracket assignments require exactly % approved players and a matching draft',
      v_required_count;
  end if;

  perform public.repair_generated_bracket_matches(
    p_generated_bracket_id,
    p_updated_by
  );

  if jsonb_array_length(p_assignments) <> v_slot_count then
    raise exception 'Every bracket slot must be included';
  end if;

  if (
    select count(*)
    from (
      select (assignment->>'slot_number')::integer as slot_number
      from jsonb_array_elements(p_assignments) as assignment
    ) as slots
  ) <> (
    select count(distinct slot_number)
    from (
      select (assignment->>'slot_number')::integer as slot_number
      from jsonb_array_elements(p_assignments) as assignment
    ) as slots
  ) then
    raise exception 'Each bracket slot may appear only once';
  end if;

  for v_assignment in
    select value from jsonb_array_elements(p_assignments)
  loop
    v_slot_number := nullif(v_assignment->>'slot_number', '')::integer;
    v_registration_id :=
      nullif(v_assignment->>'registration_id', '')::uuid;

    if v_slot_number is null
      or v_slot_number < 1
      or v_slot_number > v_slot_count then
      raise exception 'Invalid bracket slot number';
    end if;

    if v_registration_id is not null then
      if v_registration_id = any(v_assigned_registration_ids) then
        raise exception 'A participant can only occupy one bracket slot';
      end if;

      if not exists (
        select 1
        from public.registrations as registration
        where registration.id = v_registration_id
          and registration.tournament_id = v_tournament_id
          and registration.tournament_bracket_id =
            v_tournament_bracket_id
          and registration.registration_status = 'approved'
      ) then
        raise exception
          'Only approved participants from this division can be assigned';
      end if;

      v_assigned_registration_ids := array_append(
        v_assigned_registration_ids,
        v_registration_id
      );
    end if;
  end loop;

  update public.tournament_matches
  set
    player_one_registration_id = case
      when player_one_slot is not null then null
      else player_one_registration_id
    end,
    player_two_registration_id = case
      when player_two_slot is not null then null
      else player_two_registration_id
    end
  where generated_bracket_id = p_generated_bracket_id;

  for v_assignment in
    select value from jsonb_array_elements(p_assignments)
  loop
    v_slot_number := (v_assignment->>'slot_number')::integer;
    v_registration_id :=
      nullif(v_assignment->>'registration_id', '')::uuid;
    v_updated_rows := 0;

    update public.tournament_matches
    set player_one_registration_id = v_registration_id
    where generated_bracket_id = p_generated_bracket_id
      and player_one_slot = v_slot_number;
    get diagnostics v_updated_rows = row_count;

    update public.tournament_matches
    set player_two_registration_id = v_registration_id
    where generated_bracket_id = p_generated_bracket_id
      and player_two_slot = v_slot_number;
    get diagnostics v_second_updated_rows = row_count;
    v_updated_rows := v_updated_rows + v_second_updated_rows;

    if v_updated_rows = 0 then
      raise exception 'Bracket slot % has no match record', v_slot_number;
    end if;
  end loop;

  if v_format = 'round_robin' then
    delete from public.tournament_standings
    where generated_bracket_id = p_generated_bracket_id;

    insert into public.tournament_standings (
      generated_bracket_id,
      registration_id
    )
    select
      p_generated_bracket_id,
      registration_id
    from unnest(v_assigned_registration_ids) as registration_id;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_poll_draft(p_poll_id uuid, p_purpose text, p_audience_kind text, p_tournament_id uuid, p_tournament_bracket_id uuid, p_question text, p_context text, p_option_source text, p_options jsonb, p_max_selections smallint, p_winner_count smallint, p_authority text, p_result_visibility text, p_public_final_totals boolean, p_opens_at timestamp with time zone, p_closes_at timestamp with time zone, p_selected_player_ids uuid[], p_actor_clerk_user_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_poll_id uuid := coalesce(p_poll_id, pg_catalog.gen_random_uuid());
  v_actor text := nullif(pg_catalog.btrim(p_actor_clerk_user_id), '');
  v_question text := nullif(
    pg_catalog.regexp_replace(pg_catalog.btrim(p_question), '\s+', ' ', 'g'),
    ''
  );
  v_context text := nullif(pg_catalog.btrim(p_context), '');
  v_option_count integer;
  v_distinct_position_count integer;
  v_selected_count integer;
  v_valid_selected_count integer;
  v_existing public.polls%rowtype;
begin
  perform public.assert_poll_service_role();

  if v_actor is null then
    raise exception 'Poll administrator is required' using errcode = '22023';
  end if;

  if p_poll_id is not null then
    select poll.*
    into v_existing
    from public.polls as poll
    where poll.id = p_poll_id
    for update;

    if not found then
      raise exception 'Poll not found';
    end if;
    if v_existing.published_at is not null then
      raise exception 'Published polls cannot be edited'
        using errcode = '55000';
    end if;
  end if;

  if p_purpose not in ('tournament_decision', 'community_feedback') then
    raise exception 'Poll purpose is invalid' using errcode = '22023';
  end if;
  if p_audience_kind not in (
    'tournament_approved',
    'tournament_division_approved',
    'selected_tournament_players',
    'active_players',
    'selected_active_players'
  ) then
    raise exception 'Poll audience is invalid' using errcode = '22023';
  end if;
  if v_question is null or char_length(v_question) > 160 then
    raise exception 'Poll question must be between 1 and 160 characters'
      using errcode = '22023';
  end if;
  if v_context is not null and char_length(v_context) > 1000 then
    raise exception 'Poll context cannot exceed 1000 characters'
      using errcode = '22023';
  end if;
  if p_option_source not in ('text', 'coh3_map') then
    raise exception 'Poll option source is invalid' using errcode = '22023';
  end if;
  if p_max_selections not between 1 and 5
    or p_winner_count not between 1 and 5
    or p_winner_count > p_max_selections then
    raise exception 'Poll selection and winner limits are invalid'
      using errcode = '22023';
  end if;
  if p_result_visibility not in ('live', 'after_close') then
    raise exception 'Poll result visibility is invalid' using errcode = '22023';
  end if;
  if p_authority not in ('advisory', 'binding') then
    raise exception 'Poll authority is invalid' using errcode = '22023';
  end if;
  if p_opens_at is null or p_closes_at is null
    or p_closes_at < p_opens_at + interval '15 minutes'
    or p_closes_at > p_opens_at + interval '30 days' then
    raise exception 'Poll duration must be between 15 minutes and 30 days'
      using errcode = '22023';
  end if;

  if p_purpose = 'community_feedback' then
    if p_audience_kind not in ('active_players', 'selected_active_players')
      or p_tournament_id is not null
      or p_tournament_bracket_id is not null then
      raise exception 'Community Feedback audience is invalid'
        using errcode = '22023';
    end if;
    if p_authority <> 'advisory' then
      raise exception 'Community Feedback polls must be Advisory'
        using errcode = '22023';
    end if;
    if coalesce(p_public_final_totals, false) then
      raise exception 'Community Feedback remains authenticated-only'
        using errcode = '22023';
    end if;
  else
    if p_audience_kind not in (
      'tournament_approved',
      'tournament_division_approved',
      'selected_tournament_players'
    ) or p_tournament_id is null then
      raise exception 'Tournament Decision audience is invalid'
        using errcode = '22023';
    end if;
    if p_audience_kind = 'tournament_division_approved'
      and p_tournament_bracket_id is null then
      raise exception 'Tournament Division is required'
        using errcode = '22023';
    end if;
    if p_audience_kind <> 'tournament_division_approved'
      and p_tournament_bracket_id is not null then
      raise exception 'Tournament Division is not valid for this audience'
        using errcode = '22023';
    end if;
    if not exists (
      select 1 from public.tournaments as tournament
      where tournament.id = p_tournament_id
    ) then
      raise exception 'Tournament not found';
    end if;
    if p_tournament_bracket_id is not null and not exists (
      select 1 from public.tournament_brackets as bracket
      where bracket.id = p_tournament_bracket_id
        and bracket.tournament_id = p_tournament_id
    ) then
      raise exception 'Tournament Division does not belong to the tournament';
    end if;
  end if;

  if p_options is null or pg_catalog.jsonb_typeof(p_options) <> 'array' then
    raise exception 'Poll options must be a JSON array' using errcode = '22023';
  end if;

  select count(*)::integer,
    count(distinct (option_value ->> 'position')::integer)::integer
  into v_option_count, v_distinct_position_count
  from pg_catalog.jsonb_array_elements(p_options) as option_row(option_value);

  if v_option_count not between 2 and 24 then
    raise exception 'Poll option count must be between 2 and 24'
      using errcode = '22023';
  end if;
  if p_max_selections > v_option_count or p_winner_count > v_option_count then
    raise exception 'Poll selection limits cannot exceed the option count'
      using errcode = '22023';
  end if;
  if v_distinct_position_count <> v_option_count or exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_options) as option_row(option_value)
    where (option_value ->> 'position')::integer not between 1 and v_option_count
  ) then
    raise exception 'Poll option positions must be unique and contiguous'
      using errcode = '22023';
  end if;

  if p_option_source = 'text' then
    if exists (
      select 1
      from pg_catalog.jsonb_array_elements(p_options) as option_row(option_value)
      where nullif(pg_catalog.btrim(option_value ->> 'label'), '') is null
        or char_length(pg_catalog.btrim(option_value ->> 'label')) > 120
        or nullif(option_value ->> 'coh3_map_id', '') is not null
    ) then
      raise exception 'Text poll options require labels of at most 120 characters'
        using errcode = '22023';
    end if;
    if (
      select count(distinct lower(pg_catalog.regexp_replace(
        pg_catalog.btrim(option_value ->> 'label'), '\s+', ' ', 'g'
      )))
      from pg_catalog.jsonb_array_elements(p_options) as option_row(option_value)
    ) <> v_option_count then
      raise exception 'Duplicate poll options are not allowed'
        using errcode = '22023';
    end if;
  else
    if exists (
      select 1
      from pg_catalog.jsonb_array_elements(p_options) as option_row(option_value)
      where nullif(option_value ->> 'coh3_map_id', '') is null
    ) then
      raise exception 'Map poll options require catalogue map IDs'
        using errcode = '22023';
    end if;
    if (
      select count(distinct (option_value ->> 'coh3_map_id')::uuid)
      from pg_catalog.jsonb_array_elements(p_options) as option_row(option_value)
    ) <> v_option_count then
      raise exception 'Duplicate poll options are not allowed'
        using errcode = '22023';
    end if;
    if (
      select count(*)::integer
      from public.coh3_maps as map
      where map.id in (
        select (option_value ->> 'coh3_map_id')::uuid
        from pg_catalog.jsonb_array_elements(p_options)
          as option_row(option_value)
      )
        and map.status = 'active'
        and map.game_mode = '1v1'
    ) <> v_option_count then
      raise exception 'Map polls require active 1v1 catalogue maps'
        using errcode = '22023';
    end if;
  end if;

  if coalesce(cardinality(p_selected_player_ids), 0) > 0 then
    if array_position(p_selected_player_ids, null) is not null then
      raise exception 'Selected players must be valid'
        using errcode = '22023';
    end if;
    select count(distinct selected_id)::integer
    into v_selected_count
    from unnest(p_selected_player_ids) as selected_id;
    if v_selected_count <> cardinality(p_selected_player_ids) then
      raise exception 'Select each player only once' using errcode = '22023';
    end if;
  else
    v_selected_count := 0;
  end if;

  if p_audience_kind in (
    'selected_tournament_players',
    'selected_active_players'
  ) then
    -- Serialize Draft selection with account closure. If save wins, closure
    -- subsequently removes and invalidates the selection; if closure wins,
    -- the active/scope validation below rejects the stale target.
    perform player.id
    from public.players as player
    where player.id = any(
      coalesce(p_selected_player_ids, array[]::uuid[])
    )
    order by player.id
    for share;

    if p_audience_kind = 'selected_active_players' then
      select count(*)::integer
      into v_valid_selected_count
      from public.players as player
      where player.id = any(coalesce(p_selected_player_ids, array[]::uuid[]))
        and player.account_closed_at is null;
    else
      select count(distinct player.id)::integer
      into v_valid_selected_count
      from public.players as player
      join public.registrations as registration
        on registration.profile_id = player.id
      where player.id = any(coalesce(p_selected_player_ids, array[]::uuid[]))
        and player.account_closed_at is null
        and registration.tournament_id = p_tournament_id
        and registration.registration_status = 'approved';
    end if;
    if v_valid_selected_count <> v_selected_count then
      raise exception 'Selected audience contains an ineligible player'
        using errcode = '22023';
    end if;
  elsif v_selected_count <> 0 then
    raise exception 'This audience does not accept selected players'
      using errcode = '22023';
  end if;

  if p_poll_id is null then
    insert into public.polls (
      id, purpose, audience_kind, tournament_id, tournament_bracket_id,
      question, context, option_source, max_selections, winner_count,
      authority, result_visibility, public_final_totals, opens_at, closes_at,
      created_by_clerk_user_id, updated_by_clerk_user_id
    ) values (
      v_poll_id, p_purpose, p_audience_kind, p_tournament_id,
      p_tournament_bracket_id, v_question, v_context, p_option_source,
      p_max_selections, p_winner_count, p_authority, p_result_visibility,
      coalesce(p_public_final_totals, false), p_opens_at, p_closes_at,
      v_actor, v_actor
    );
  else
    update public.polls
    set purpose = p_purpose,
      audience_kind = p_audience_kind,
      tournament_id = p_tournament_id,
      tournament_bracket_id = p_tournament_bracket_id,
      question = v_question,
      context = v_context,
      option_source = p_option_source,
      max_selections = p_max_selections,
      winner_count = p_winner_count,
      authority = p_authority,
      result_visibility = p_result_visibility,
      public_final_totals = coalesce(p_public_final_totals, false),
      draft_audience_invalidated = false,
      opens_at = p_opens_at,
      closes_at = p_closes_at,
      updated_by_clerk_user_id = v_actor
    where id = v_poll_id;
  end if;

  delete from public.poll_eligible_voters
  where poll_id = v_poll_id;
  delete from public.poll_options
  where poll_id = v_poll_id;

  if p_option_source = 'text' then
    insert into public.poll_options (
      id, poll_id, position, label_snapshot
    )
    select
      coalesce(
        nullif(option_value ->> 'id', '')::uuid,
        pg_catalog.gen_random_uuid()
      ),
      v_poll_id,
      (option_value ->> 'position')::smallint,
      pg_catalog.regexp_replace(
        pg_catalog.btrim(option_value ->> 'label'), '\s+', ' ', 'g'
      )
    from pg_catalog.jsonb_array_elements(p_options)
      as option_row(option_value)
    order by (option_value ->> 'position')::integer;
  else
    insert into public.poll_options (
      id, poll_id, position, label_snapshot, coh3_map_id,
      map_display_name_snapshot, map_slug_snapshot
    )
    select
      coalesce(
        nullif(option_value ->> 'id', '')::uuid,
        pg_catalog.gen_random_uuid()
      ),
      v_poll_id,
      (option_value ->> 'position')::smallint,
      map.display_name,
      map.id,
      map.display_name,
      map.slug
    from pg_catalog.jsonb_array_elements(p_options)
      as option_row(option_value)
    join public.coh3_maps as map
      on map.id = (option_value ->> 'coh3_map_id')::uuid
    order by (option_value ->> 'position')::integer;
  end if;

  if p_audience_kind in (
    'selected_tournament_players',
    'selected_active_players'
  ) then
    insert into public.poll_eligible_voters (poll_id, player_id)
    select v_poll_id, selected_id
    from unnest(coalesce(p_selected_player_ids, array[]::uuid[]))
      as selected_id
    order by selected_id;
  end if;

  return pg_catalog.jsonb_build_object(
    'poll_id', v_poll_id,
    'saved', true
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.save_tournament(p_tournament_id uuid, p_title text, p_slug text, p_description text, p_banner_image_url text, p_registration_open_at timestamp with time zone, p_registration_close_at timestamp with time zone, p_start_date timestamp with time zone, p_end_date timestamp with time zone, p_status text, p_format text, p_prize_pool text, p_rules_url text, p_battlefy_url text, p_registration_enabled boolean, p_grand_final_at timestamp with time zone, p_rule_format text, p_result_confirmation_window_minutes integer, p_brackets jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_tournament_id uuid;
  v_bracket jsonb;
  v_bracket_name text;
  v_conflicting_tournament_title text;
  v_protected_bracket_name text;
  v_rule_format text;
  v_confirmation_window integer;
begin
  v_rule_format := coalesce(nullif(p_rule_format, ''), 'format_a');
  v_confirmation_window :=
    coalesce(p_result_confirmation_window_minutes, 30);

  if v_rule_format not in ('format_a', 'format_b') then
    raise exception 'Invalid tournament rule format';
  end if;

  if v_confirmation_window not in (
    1, 5, 15, 30, 60, 120, 360, 720, 1440
  ) then
    raise exception 'Invalid result confirmation window';
  end if;

  if p_registration_open_at is not null
    and p_registration_close_at is not null
    and p_registration_open_at >= p_registration_close_at then
    raise exception 'Registration open date must be before close date';
  end if;

  if p_registration_close_at is not null
    and p_start_date is not null
    and p_registration_close_at > p_start_date then
    raise exception 'Registration must close before the tournament starts';
  end if;

  if p_end_date is not null
    and p_start_date is not null
    and p_end_date < p_start_date then
    raise exception 'Tournament end date must be after the start date';
  end if;

  if p_brackets is null
    or pg_catalog.jsonb_typeof(p_brackets) <> 'array'
    or pg_catalog.jsonb_array_length(p_brackets) = 0 then
    raise exception 'At least one bracket is required';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_brackets) as requested(value)
    where pg_catalog.jsonb_typeof(requested.value) <> 'object'
      or requested.value ->> 'name' not in ('Academy', 'Challenge', 'Main')
  ) or (
    select count(*)
    from pg_catalog.jsonb_array_elements(p_brackets)
  ) <> (
    select count(distinct requested.value ->> 'name')
    from pg_catalog.jsonb_array_elements(p_brackets) as requested(value)
  ) then
    raise exception 'Tournament divisions must be unique canonical divisions';
  end if;

  if p_tournament_id is not null then
    select tournament.id
    into v_tournament_id
    from public.tournaments as tournament
    where tournament.id = p_tournament_id
    for update;

    if not found then
      raise exception 'Tournament not found';
    end if;
  end if;

  for v_bracket_name in
    select requested.value ->> 'name'
    from pg_catalog.jsonb_array_elements(p_brackets) as requested(value)
    order by requested.value ->> 'name'
  loop
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        'ironclad:ranked-division-cycle:' || v_bracket_name,
        0
      )
    );

    select tournament.title
    into v_conflicting_tournament_title
    from public.tournament_brackets as bracket
    join public.tournaments as tournament
      on tournament.id = bracket.tournament_id
    where bracket.name = v_bracket_name
      and (
        p_tournament_id is null
        or tournament.id <> p_tournament_id
      )
      and coalesce(tournament.status, '') not in (
        'completed', 'cancelled', 'voided'
      )
      and not exists (
        select 1
        from public.tournament_division_not_held_closures as closure
        where closure.tournament_bracket_id = bracket.id
      )
      and (
        bracket.launched_at is null
        or not exists (
          select 1
          from public.generated_brackets as generated
          where generated.tournament_bracket_id = bracket.id
        )
        or exists (
          select 1
          from public.generated_brackets as generated
          where generated.tournament_bracket_id = bracket.id
            and public.is_generated_bracket_complete(generated.id)
              is distinct from true
        )
      )
    order by tournament.created_at, tournament.id
    limit 1;

    if v_conflicting_tournament_title is not null then
      raise exception
        'The % Division already has an unresolved ranked cycle in event %. Resolve that Division before enabling another.',
        v_bracket_name,
        v_conflicting_tournament_title
        using errcode = '55000';
    end if;
  end loop;

  if p_tournament_id is not null then
    select bracket.name
    into v_protected_bracket_name
    from public.tournament_brackets as bracket
    where bracket.tournament_id = p_tournament_id
      and bracket.name not in (
        select requested.value ->> 'name'
        from pg_catalog.jsonb_array_elements(p_brackets) as requested(value)
      )
      and (
        exists (
          select 1
          from public.tournament_division_not_held_closures as closure
          where closure.tournament_bracket_id = bracket.id
        )
        or exists (
          select 1
          from public.registrations as registration
          where registration.tournament_bracket_id = bracket.id
            and registration.registration_status = 'approved'
        )
        or exists (
          select 1
          from public.generated_brackets as generated
          where generated.tournament_bracket_id = bracket.id
        )
      )
    order by bracket.name
    limit 1;

    if v_protected_bracket_name is not null then
      raise exception
        'Cannot remove the % bracket during a normal tournament edit because it has protected registration or competition history.',
        v_protected_bracket_name;
    end if;
  end if;

  if p_tournament_id is null then
    insert into public.tournaments (
      title, slug, description, banner_image_url,
      registration_open_at, registration_close_at,
      start_date, end_date, status, format, prize_pool,
      rules_url, battlefy_url, registration_enabled,
      grand_final_at, rule_format,
      result_confirmation_window_minutes
    )
    values (
      p_title, p_slug, p_description, p_banner_image_url,
      p_registration_open_at, p_registration_close_at,
      p_start_date, p_end_date, p_status, p_format,
      coalesce(p_prize_pool, ''), nullif(p_rules_url, ''),
      nullif(p_battlefy_url, ''), p_registration_enabled, null,
      v_rule_format, v_confirmation_window
    )
    returning id into v_tournament_id;
  else
    update public.tournaments
    set
      title = p_title,
      slug = p_slug,
      description = p_description,
      banner_image_url = p_banner_image_url,
      registration_open_at = p_registration_open_at,
      registration_close_at = p_registration_close_at,
      start_date = coalesce(p_start_date, start_date),
      end_date = coalesce(p_end_date, end_date),
      status = p_status,
      format = p_format,
      prize_pool = coalesce(p_prize_pool, ''),
      rules_url = nullif(p_rules_url, ''),
      battlefy_url = nullif(p_battlefy_url, ''),
      registration_enabled = p_registration_enabled,
      rule_format = v_rule_format,
      result_confirmation_window_minutes = v_confirmation_window
    where id = p_tournament_id
    returning id into v_tournament_id;
  end if;

  for v_bracket in
    select requested.value
    from pg_catalog.jsonb_array_elements(p_brackets) as requested(value)
  loop
    insert into public.tournament_brackets (
      tournament_id, name, elo_rules, max_players
    )
    values (
      v_tournament_id,
      v_bracket ->> 'name',
      v_bracket ->> 'elo_rules',
      (v_bracket ->> 'max_players')::integer
    )
    on conflict (tournament_id, name)
    do update set
      elo_rules = excluded.elo_rules,
      max_players = excluded.max_players;
  end loop;

  delete from public.tournament_brackets
  where tournament_id = v_tournament_id
    and name not in (
      select requested.value ->> 'name'
      from pg_catalog.jsonb_array_elements(p_brackets) as requested(value)
    );

  -- Re-run the existing lifecycle derivation now that the Division rows exist.
  -- Assigning status to itself deliberately invokes the existing trigger; it
  -- does not introduce another registration-enabled writer.
  update public.tournaments as tournament
  set status = tournament.status
  where tournament.id = v_tournament_id;

  return v_tournament_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_match_room_enabled(p_enabled boolean, p_actor_clerk_user_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare v_actor text := nullif(btrim(p_actor_clerk_user_id), '');
begin
  if session_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'Match Room setting requires the trusted server boundary' using errcode = '42501';
  end if;
  if p_enabled is null or v_actor is null or char_length(v_actor) > 256 then
    raise exception 'Invalid Match Room setting' using errcode = '22023';
  end if;
  insert into public.platform_settings(key, value, updated_by_clerk_user_id)
  values ('match_room', jsonb_build_object('enabled', p_enabled), v_actor)
  on conflict(key) do update set value = excluded.value,
    updated_by_clerk_user_id = excluded.updated_by_clerk_user_id;
  return jsonb_build_object('enabled', p_enabled);
end;
$function$

CREATE OR REPLACE FUNCTION public.set_match_room_retention_hold(p_room_id uuid, p_message_ids uuid[], p_case_reference uuid, p_reason text, p_expires_at timestamp with time zone, p_actor_clerk_user_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET lock_timeout TO '2s'
 SET statement_timeout TO '60s'
AS $function$
declare v_actor uuid; v_id uuid;
begin
  v_actor:=ironclad_private.match_room_privacy_actor(p_actor_clerk_user_id);
  if p_case_reference is null or p_reason is null or p_reason not in('legal','security','abuse_safety','competition_integrity')
    or p_expires_at is null or p_expires_at<=clock_timestamp() or p_expires_at>clock_timestamp()+interval '366 days'
    or (p_message_ids is not null and (cardinality(p_message_ids) not between 1 and 1000 or array_position(p_message_ids,null) is not null)) then
    raise exception 'Invalid bounded hold' using errcode='22023'; end if;
  perform ironclad_private.lock_match_room_privacy(p_room_id);
  perform ironclad_private.match_room_privacy_actor(p_actor_clerk_user_id);
  if p_message_ids is not null and exists(select 1 from unnest(p_message_ids) as scope(message_id) where not exists(select 1 from public.match_messages m where m.id=scope.message_id and m.room_id=p_room_id)) then
    raise exception 'Hold scope contains unavailable message' using errcode='22023'; end if;
  insert into ironclad_private.match_room_retention_holds(room_id,message_ids,case_reference,reason,expires_at)
    values(p_room_id,p_message_ids,p_case_reference,p_reason,p_expires_at) returning id into v_id;
  insert into ironclad_private.match_room_privacy_audit(room_id,operation,actor_player_id,reference_id)
    values(p_room_id,'hold',v_actor,v_id);
  return jsonb_build_object('holdId',v_id,'roomId',p_room_id,'expiresAt',p_expires_at);
end $function$

CREATE OR REPLACE FUNCTION public.settle_leaderboard_division_on_match_result()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_tournament_id uuid;
  v_tournament_bracket_id uuid;
  v_error_state text;
begin
  select bracket.tournament_id, bracket.id
  into v_tournament_id, v_tournament_bracket_id
  from public.generated_brackets as generated
  join public.tournament_brackets as bracket
    on bracket.id = generated.tournament_bracket_id
  where generated.id = new.generated_bracket_id;

  if v_tournament_bracket_id is null
    or public.is_generated_bracket_complete(new.generated_bracket_id)
      is distinct from true then
    return null;
  end if;

  begin
    -- A result transaction already owns the final match row. Never wait behind
    -- a concurrent manual settlement that may itself be waiting for that row;
    -- record the existing repair signal and let the authoritative result
    -- commit. An uncontended trigger re-enters these transaction locks inside
    -- the canonical writer.
    if not pg_catalog.pg_try_advisory_xact_lock(
      pg_catalog.hashtextextended('ironclad:leaderboard:all-time', 0)
    ) then
      raise exception 'Division settlement is already in progress'
        using errcode = '55P03';
    end if;
    if not pg_catalog.pg_try_advisory_xact_lock(
      pg_catalog.hashtextextended(
        'ironclad:leaderboard:division:' || v_tournament_bracket_id::text,
        0
      )
    ) then
      raise exception 'Division settlement is already in progress'
        using errcode = '55P03';
    end if;

    perform public.settle_leaderboard_division(
      v_tournament_bracket_id,
      null
    );
  exception
    when query_canceled or assert_failure or others then
      get stacked diagnostics v_error_state = returned_sqlstate;
      begin
        insert into public.leaderboard_recalculation_runs (
          tournament_id,
          scope,
          status,
          finished_at,
          notes
        )
        values (
          v_tournament_id,
          'tournament',
          'failed',
          clock_timestamp(),
          format(
            'Automatic Division settlement failed: SQLSTATE %s',
            coalesce(v_error_state, 'unknown')
          )
        );
      exception
        when query_canceled or assert_failure or others then
          raise warning using message = format(
            'Automatic Division settlement audit failed: SQLSTATE %s',
            coalesce(v_error_state, 'unknown')
          );
      end;
  end;

  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.submit_match_game_result(p_match_id uuid, p_submitted_by_clerk_user_id text, p_game_number integer, p_winner_registration_id uuid, p_replay_storage_path text, p_screenshot_storage_path text, p_notes text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_match public.tournament_matches%rowtype;
  v_reporter_registration_id uuid;
  v_submission_number integer;
  v_expected_game_number integer;
  v_wins_required integer;
  v_reporter_player_one_wins integer;
  v_reporter_player_two_wins integer;
begin
  if p_submitted_by_clerk_user_id is null
    or btrim(p_submitted_by_clerk_user_id) = '' then
    raise exception 'Submitting player is required';
  end if;

  if p_replay_storage_path is null
    and p_screenshot_storage_path is null then
    raise exception 'At least one proof file is required';
  end if;

  select match.*
  into v_match
  from public.tournament_matches as match
  where match.id = p_match_id
  for update;

  if not found or v_match.status = 'completed' then
    raise exception 'This match is not accepting game reports';
  end if;

  if p_game_number < 1 or p_game_number > v_match.series_best_of then
    raise exception 'Game number is outside this series format';
  end if;

  if v_match.player_one_registration_id is null
    or v_match.player_two_registration_id is null then
    raise exception 'Both match participants must be assigned';
  end if;

  select registration.id
  into v_reporter_registration_id
  from public.registrations as registration
  where registration.id in (
    v_match.player_one_registration_id,
    v_match.player_two_registration_id
  )
    and registration.clerk_user_id = p_submitted_by_clerk_user_id;

  if v_reporter_registration_id is null then
    raise exception 'Player is not a participant in this match';
  end if;

  if p_winner_registration_id not in (
    v_match.player_one_registration_id,
    v_match.player_two_registration_id
  ) then
    raise exception 'Game winner must be a participant in this match';
  end if;

  select coalesce(max(report.game_number), 0) + 1
  into v_expected_game_number
  from public.match_result_submissions as report
  where report.match_id = p_match_id
    and report.submitted_by_registration_id =
      v_reporter_registration_id
    and report.status = 'pending';

  if p_game_number <> v_expected_game_number then
    raise exception 'Games must be reported in series order';
  end if;

  select
    count(*) filter (
      where report.claimed_winner_registration_id =
        v_match.player_one_registration_id
    )::integer,
    count(*) filter (
      where report.claimed_winner_registration_id =
        v_match.player_two_registration_id
    )::integer
  into v_reporter_player_one_wins, v_reporter_player_two_wins
  from public.match_result_submissions as report
  where report.match_id = p_match_id
    and report.submitted_by_registration_id =
      v_reporter_registration_id
    and report.status = 'pending';

  v_wins_required := (v_match.series_best_of / 2) + 1;
  if greatest(
    v_reporter_player_one_wins,
    v_reporter_player_two_wins
  ) >= v_wins_required then
    raise exception 'This player has already reported a complete series';
  end if;

  select coalesce(max(submission.submission_number), 0) + 1
  into v_submission_number
  from public.match_result_submissions as submission
  where submission.match_id = p_match_id;

  insert into public.match_result_submissions (
    submission_number,
    game_number,
    match_id,
    submitted_by_clerk_user_id,
    submitted_by_registration_id,
    claimed_winner_registration_id,
    player_one_score,
    player_two_score,
    replay_storage_path,
    screenshot_storage_path,
    notes,
    status
  )
  values (
    v_submission_number,
    p_game_number,
    p_match_id,
    p_submitted_by_clerk_user_id,
    v_reporter_registration_id,
    p_winner_registration_id,
    case when p_winner_registration_id =
      v_match.player_one_registration_id then 1 else 0 end,
    case when p_winner_registration_id =
      v_match.player_two_registration_id then 1 else 0 end,
    p_replay_storage_path,
    p_screenshot_storage_path,
    nullif(btrim(p_notes), ''),
    'pending'
  );

  update public.tournament_matches
  set status = 'pending_review'
  where id = p_match_id;

  return v_submission_number;
end;
$function$

CREATE OR REPLACE FUNCTION public.submit_match_no_show_report(p_match_id uuid, p_submitted_by_clerk_user_id text, p_no_show_registration_id uuid, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_match public.tournament_matches%rowtype;
  v_format text;
begin
  select match.*
  into v_match
  from public.tournament_matches as match
  where match.id = p_match_id
  for update;

  if not found then
    raise exception 'Tournament match not found';
  end if;

  select generated.format
  into v_format
  from public.generated_brackets as generated
  where generated.id = v_match.generated_bracket_id;

  if v_format = 'single_elimination' then
    if v_match.status <> 'in_progress'
      or v_match.activation_version < 1
      or v_match.deadline_at is null
      or v_match.outcome_type is not null
      or v_match.hold_started_at is not null
        and v_match.hold_released_at is null then
      raise exception 'This matchup is not currently actionable';
    end if;

    if clock_timestamp() >= v_match.deadline_at then
      raise exception 'The matchup deadline has passed';
    end if;
  end if;

  return public.submit_match_no_show_report_without_matchup_deadline(
    p_match_id,
    p_submitted_by_clerk_user_id,
    p_no_show_registration_id,
    p_notes
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.submit_match_no_show_report_without_matchup_deadline(p_match_id uuid, p_submitted_by_clerk_user_id text, p_no_show_registration_id uuid, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_match public.tournament_matches%rowtype;
  v_tournament_id uuid;
  v_reporter_registration_id uuid;
  v_opponent_registration_id uuid;
  v_confirmation_window_minutes integer;
  v_group_id uuid;
  v_existing_group_id uuid;
  v_wins_required integer;
  v_player_one_score integer;
  v_player_two_score integer;
  v_deadline timestamptz;
begin
  if p_submitted_by_clerk_user_id is null
    or btrim(p_submitted_by_clerk_user_id) = '' then
    raise exception 'Submitting player is required';
  end if;

  if p_no_show_registration_id is null then
    raise exception 'Missing player is required';
  end if;

  if p_notes is not null and length(p_notes) > 2000 then
    raise exception 'No-show notes must be 2000 characters or fewer';
  end if;

  select match.*
  into v_match
  from public.tournament_matches as match
  where match.id = p_match_id
  for update;

  if not found then
    raise exception 'Tournament match not found';
  end if;

  if v_match.status = 'completed'
    or v_match.official_result_submission_id is not null then
    raise exception 'This match already has an official result';
  end if;

  if v_match.player_one_registration_id is null
    or v_match.player_two_registration_id is null then
    raise exception 'Both match participants must be assigned';
  end if;

  select bracket.tournament_id, tournament.result_confirmation_window_minutes
  into v_tournament_id, v_confirmation_window_minutes
  from public.generated_brackets as generated
  join public.tournament_brackets as bracket
    on bracket.id = generated.tournament_bracket_id
  join public.tournaments as tournament
    on tournament.id = bracket.tournament_id
  where generated.id = v_match.generated_bracket_id;

  if v_tournament_id is null then
    raise exception 'Tournament could not be resolved for this match';
  end if;

  select registration.id
  into v_reporter_registration_id
  from public.registrations as registration
  where registration.id in (
    v_match.player_one_registration_id,
    v_match.player_two_registration_id
  )
    and registration.clerk_user_id = p_submitted_by_clerk_user_id;

  if v_reporter_registration_id is null then
    raise exception 'Player is not a participant in this match';
  end if;

  v_opponent_registration_id := case
    when v_reporter_registration_id = v_match.player_one_registration_id
      then v_match.player_two_registration_id
    else v_match.player_one_registration_id
  end;

  if p_no_show_registration_id <> v_opponent_registration_id then
    raise exception 'Only the opposing player can be reported as a no-show';
  end if;

  select report_group.id
  into v_existing_group_id
  from public.match_result_report_groups as report_group
  where report_group.match_id = p_match_id
    and report_group.status in (
      'pending_confirmation',
      'disputed',
      'under_review'
    )
  order by report_group.created_at, report_group.id
  limit 1
  for update;

  if v_existing_group_id is not null then
    raise exception 'This match already has an active result report group';
  end if;

  if exists (
    select 1
    from public.match_result_submissions as submission
    where submission.match_id = p_match_id
      and submission.status = 'pending'
      and submission.report_group_id is null
  ) then
    raise exception
      'This match has legacy pending reports awaiting administrator review';
  end if;

  v_wins_required := (v_match.series_best_of / 2) + 1;
  v_player_one_score := case
    when v_reporter_registration_id = v_match.player_one_registration_id
      then v_wins_required
    else 0
  end;
  v_player_two_score := case
    when v_reporter_registration_id = v_match.player_two_registration_id
      then v_wins_required
    else 0
  end;
  v_deadline := now() + make_interval(
    mins => coalesce(v_confirmation_window_minutes, 30)
  );

  insert into public.match_result_report_groups (
    match_id,
    tournament_id,
    submitted_by_clerk_user_id,
    submitted_by_registration_id,
    opponent_registration_id,
    winner_registration_id,
    player_one_score,
    player_two_score,
    replay_storage_path,
    replay_proof_mode,
    status,
    confirmation_deadline_at,
    result_type,
    no_show_reported_by_registration_id,
    no_show_registration_id,
    no_show_status,
    no_show_note
  )
  values (
    p_match_id,
    v_tournament_id,
    p_submitted_by_clerk_user_id,
    v_reporter_registration_id,
    v_opponent_registration_id,
    v_reporter_registration_id,
    v_player_one_score,
    v_player_two_score,
    null,
    'no_show_report',
    'pending_confirmation',
    v_deadline,
    'no_show',
    v_reporter_registration_id,
    p_no_show_registration_id,
    'pending',
    nullif(btrim(p_notes), '')
  )
  returning id into v_group_id;

  update public.tournament_matches
  set status = 'pending_review'
  where id = p_match_id
    and status in ('scheduled', 'in_progress');

  return jsonb_build_object(
    'report_group_id', v_group_id,
    'reporter_registration_id', v_reporter_registration_id,
    'no_show_registration_id', p_no_show_registration_id,
    'no_show_status', 'pending',
    'confirmation_deadline_at', v_deadline
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.submit_match_result_claim(p_match_id uuid, p_submitted_by_clerk_user_id text, p_winner_registration_id uuid, p_player_one_score integer, p_player_two_score integer, p_replay_storage_path text, p_screenshot_storage_path text, p_notes text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_match public.tournament_matches%rowtype;
  v_round_name text;
  v_wins_required integer;
  v_reporter_registration_id uuid;
  v_submission_number integer;
begin
  if p_submitted_by_clerk_user_id is null
    or btrim(p_submitted_by_clerk_user_id) = '' then
    raise exception 'Submitting player is required';
  end if;

  if p_replay_storage_path is null
    and p_screenshot_storage_path is null then
    raise exception 'At least one proof file is required';
  end if;

  select match.*
  into v_match
  from public.tournament_matches as match
  where match.id = p_match_id
  for update;

  if not found or v_match.status = 'completed' then
    raise exception 'This match is not accepting result submissions';
  end if;

  select round.name
  into v_round_name
  from public.bracket_rounds as round
  where round.id = v_match.round_id;

  if v_match.player_one_registration_id is null
    or v_match.player_two_registration_id is null then
    raise exception 'Both match participants must be assigned';
  end if;

  select registration.id
  into v_reporter_registration_id
  from public.registrations as registration
  where registration.id in (
    v_match.player_one_registration_id,
    v_match.player_two_registration_id
  )
    and registration.clerk_user_id = p_submitted_by_clerk_user_id;

  if v_reporter_registration_id is null then
    raise exception 'Player is not a participant in this match';
  end if;

  if p_winner_registration_id not in (
    v_match.player_one_registration_id,
    v_match.player_two_registration_id
  ) then
    raise exception 'Winner must be a participant in this match';
  end if;

  v_wins_required := case
    when lower(v_round_name) in ('grand final', 'final') then 3
    else 2
  end;

  if p_player_one_score is null
    or p_player_two_score is null
    or p_player_one_score = p_player_two_score
    or p_player_one_score < 0
    or p_player_two_score < 0
    or greatest(p_player_one_score, p_player_two_score) <> v_wins_required
    or least(p_player_one_score, p_player_two_score) >= v_wins_required
    or (
      p_winner_registration_id = v_match.player_one_registration_id
      and p_player_one_score <= p_player_two_score
    )
    or (
      p_winner_registration_id = v_match.player_two_registration_id
      and p_player_two_score <= p_player_one_score
    ) then
    raise exception 'Score does not satisfy the match format';
  end if;

  select coalesce(max(submission.submission_number), 0) + 1
  into v_submission_number
  from public.match_result_submissions as submission
  where submission.match_id = p_match_id;

  insert into public.match_result_submissions (
    submission_number,
    match_id,
    submitted_by_clerk_user_id,
    submitted_by_registration_id,
    claimed_winner_registration_id,
    player_one_score,
    player_two_score,
    replay_storage_path,
    screenshot_storage_path,
    notes,
    status
  )
  values (
    v_submission_number,
    p_match_id,
    p_submitted_by_clerk_user_id,
    v_reporter_registration_id,
    p_winner_registration_id,
    p_player_one_score,
    p_player_two_score,
    p_replay_storage_path,
    p_screenshot_storage_path,
    nullif(btrim(p_notes), ''),
    'pending'
  );

  update public.tournament_matches
  set status = 'pending_review'
  where id = p_match_id;

  return v_submission_number;
end;
$function$

CREATE OR REPLACE FUNCTION public.submit_match_series_result_report(p_match_id uuid, p_submitted_by_clerk_user_id text, p_winner_registration_id uuid, p_player_one_score integer, p_player_two_score integer, p_replay_storage_paths text[], p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_match public.tournament_matches%rowtype;
  v_reporter_registration_id uuid;
  v_submission_id uuid;
  v_submission_ids uuid[] := array[]::uuid[];
  v_submission_number integer;
  v_first_submission_number integer;
  v_report_group_id uuid;
  v_confirmation_deadline_at timestamptz;
  v_wins_required integer;
  v_winner_score integer;
  v_loser_score integer;
  v_required_replay_count integer;
  v_replay_paths text[];
  v_replay_count integer;
  v_distinct_replay_count integer;
  v_index integer;
begin
  if p_submitted_by_clerk_user_id is null
    or btrim(p_submitted_by_clerk_user_id) = '' then
    raise exception 'Submitting player is required';
  end if;

  select coalesce(array_agg(path order by ordinal), array[]::text[])
  into v_replay_paths
  from (
    select btrim(replay.path) as path, replay.ordinal
    from unnest(coalesce(p_replay_storage_paths, array[]::text[]))
      with ordinality as replay(path, ordinal)
    where replay.path is not null
      and btrim(replay.path) <> ''
  ) as normalized;

  select count(*), count(distinct replay.path)
  into v_replay_count, v_distinct_replay_count
  from unnest(v_replay_paths) as replay(path);

  if v_replay_count = 0 then
    raise exception 'Replay proof is required';
  end if;

  if v_replay_count <> v_distinct_replay_count then
    raise exception 'Replay proof paths must be unique';
  end if;

  if exists (
    select 1
    from unnest(v_replay_paths) as replay(path)
    where lower(replay.path) not like '%.rec'
  ) then
    raise exception 'Every replay proof must use a .rec file';
  end if;

  if p_player_one_score is null
    or p_player_two_score is null
    or p_player_one_score < 0
    or p_player_two_score < 0
    or p_player_one_score = p_player_two_score then
    raise exception 'Enter a valid non-tied final score';
  end if;

  select match.*
  into v_match
  from public.tournament_matches as match
  where match.id = p_match_id
  for update;

  if not found then
    raise exception 'Tournament match not found';
  end if;

  if v_match.status = 'completed'
    or v_match.official_result_submission_id is not null then
    raise exception 'This match already has an official result';
  end if;

  if v_match.player_one_registration_id is null
    or v_match.player_two_registration_id is null then
    raise exception 'Both match participants must be assigned';
  end if;

  select registration.id
  into v_reporter_registration_id
  from public.registrations as registration
  where registration.id in (
    v_match.player_one_registration_id,
    v_match.player_two_registration_id
  )
    and registration.clerk_user_id = p_submitted_by_clerk_user_id;

  if v_reporter_registration_id is null then
    raise exception 'Player is not a participant in this match';
  end if;

  if p_winner_registration_id not in (
    v_match.player_one_registration_id,
    v_match.player_two_registration_id
  ) then
    raise exception 'Winner must be a participant in this match';
  end if;

  v_wins_required := (v_match.series_best_of / 2) + 1;
  v_winner_score := case
    when p_winner_registration_id = v_match.player_one_registration_id
      then p_player_one_score
    else p_player_two_score
  end;
  v_loser_score := case
    when p_winner_registration_id = v_match.player_one_registration_id
      then p_player_two_score
    else p_player_one_score
  end;

  if v_winner_score <> v_wins_required
    or v_loser_score >= v_wins_required then
    raise exception
      'This BO% series requires the winner to finish on % wins',
      v_match.series_best_of,
      v_wins_required;
  end if;

  v_required_replay_count := p_player_one_score + p_player_two_score;

  if v_replay_count <> v_required_replay_count then
    raise exception
      'This score requires exactly % replay file%',
      v_required_replay_count,
      case when v_required_replay_count = 1 then '' else 's' end;
  end if;

  if exists (
    select 1
    from public.match_result_submissions as submission
    where submission.match_id = p_match_id
      and submission.status = 'pending'
      and submission.report_group_id is null
  ) then
    raise exception
      'This match has legacy pending reports awaiting administrator review';
  end if;

  if exists (
    select 1
    from public.match_result_report_groups as report_group
    where report_group.match_id = p_match_id
      and report_group.status in (
        'pending_confirmation',
        'disputed',
        'under_review'
      )
      and report_group.finalized_at is null
  ) then
    raise exception 'This match already has an active result report group';
  end if;

  for v_index in 1..v_required_replay_count loop
    select coalesce(max(submission.submission_number), 0) + 1
    into v_submission_number
    from public.match_result_submissions as submission
    where submission.match_id = p_match_id;

    insert into public.match_result_submissions (
      submission_number,
      game_number,
      match_id,
      submitted_by_clerk_user_id,
      submitted_by_registration_id,
      claimed_winner_registration_id,
      player_one_score,
      player_two_score,
      replay_storage_path,
      screenshot_storage_path,
      notes,
      status
    )
    values (
      v_submission_number,
      v_index,
      p_match_id,
      p_submitted_by_clerk_user_id,
      v_reporter_registration_id,
      p_winner_registration_id,
      p_player_one_score,
      p_player_two_score,
      v_replay_paths[v_index],
      null,
      case when v_index = 1 then nullif(btrim(p_notes), '') else null end,
      'pending'
    )
    returning id into v_submission_id;

    if v_first_submission_number is null then
      v_first_submission_number := v_submission_number;
    end if;

    v_submission_ids := array_append(v_submission_ids, v_submission_id);
  end loop;

  v_report_group_id := public.create_match_result_report_group(
    p_match_id,
    p_submitted_by_clerk_user_id,
    p_winner_registration_id,
    p_player_one_score,
    p_player_two_score,
    v_submission_ids,
    v_replay_paths[1]
  );

  select report_group.confirmation_deadline_at
  into v_confirmation_deadline_at
  from public.match_result_report_groups as report_group
  where report_group.id = v_report_group_id;

  return jsonb_build_object(
    'report_group_id', v_report_group_id,
    'submission_ids', to_jsonb(v_submission_ids),
    'submission_number', v_first_submission_number,
    'replay_count', v_replay_count,
    'required_replay_count', v_required_replay_count,
    'confirmation_deadline_at', v_confirmation_deadline_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.submit_match_series_result_report(p_match_id uuid, p_submitted_by_clerk_user_id text, p_winner_registration_id uuid, p_player_one_score integer, p_player_two_score integer, p_replay_storage_paths text[], p_replay_content_hashes text[], p_game_winner_registration_ids uuid[], p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_result jsonb;
  v_updated_count integer;
begin
  perform ironclad_private.validate_match_game_winner_sequence(
    p_match_id,
    p_winner_registration_id,
    p_player_one_score,
    p_player_two_score,
    p_game_winner_registration_ids
  );

  v_result := public.submit_match_series_result_report(
    p_match_id,
    p_submitted_by_clerk_user_id,
    p_winner_registration_id,
    p_player_one_score,
    p_player_two_score,
    p_replay_storage_paths,
    p_replay_content_hashes,
    p_notes
  );

  with linked_submission as (
    select
      submission_id::uuid as id,
      ordinal
    from jsonb_array_elements_text(v_result->'submission_ids')
      with ordinality as submission(submission_id, ordinal)
  ),
  game_winner as (
    select winner_registration_id, ordinal
    from unnest(p_game_winner_registration_ids)
      with ordinality as winner(winner_registration_id, ordinal)
  )
  update public.match_result_submissions as submission
  set claimed_winner_registration_id = game_winner.winner_registration_id
  from linked_submission
  join game_winner using (ordinal)
  where submission.id = linked_submission.id
    and submission.match_id = p_match_id
    and submission.report_group_id = (v_result->>'report_group_id')::uuid;

  get diagnostics v_updated_count = row_count;

  if v_updated_count <> cardinality(p_game_winner_registration_ids) then
    raise exception 'Per-game winner authority could not be linked completely';
  end if;

  return v_result || jsonb_build_object(
    'game_winner_count', v_updated_count
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.submit_match_series_result_report(p_match_id uuid, p_submitted_by_clerk_user_id text, p_winner_registration_id uuid, p_player_one_score integer, p_player_two_score integer, p_replay_storage_paths text[], p_replay_content_hashes text[], p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_result jsonb;
  v_replay_path_count integer;
  v_hashes text[];
  v_hash_count integer;
  v_distinct_hash_count integer;
begin
  select count(*)
  into v_replay_path_count
  from unnest(coalesce(p_replay_storage_paths, array[]::text[])) as replay(path)
  where replay.path is not null
    and btrim(replay.path) <> '';

  select coalesce(array_agg(hash order by ordinal), array[]::text[])
  into v_hashes
  from (
    select lower(btrim(replay_hash.hash)) as hash, replay_hash.ordinal
    from unnest(coalesce(p_replay_content_hashes, array[]::text[]))
      with ordinality as replay_hash(hash, ordinal)
    where replay_hash.hash is not null
      and btrim(replay_hash.hash) <> ''
  ) as normalized;

  select count(*), count(distinct replay_hash.hash)
  into v_hash_count, v_distinct_hash_count
  from unnest(v_hashes) as replay_hash(hash);

  if v_hash_count <> v_replay_path_count then
    raise exception 'Replay hash count must match replay file count';
  end if;

  if exists (
    select 1
    from unnest(v_hashes) as replay_hash(hash)
    where replay_hash.hash !~ '^[0-9a-f]{64}$'
  ) then
    raise exception 'Replay content hashes must be SHA-256 hex strings';
  end if;

  if v_distinct_hash_count <> v_hash_count then
    raise exception 'Each game requires a unique replay file';
  end if;

  v_result := public.submit_match_series_result_report(
    p_match_id,
    p_submitted_by_clerk_user_id,
    p_winner_registration_id,
    p_player_one_score,
    p_player_two_score,
    p_replay_storage_paths,
    p_notes
  );

  with linked_submission as (
    select
      submission_id::uuid as id,
      ordinal
    from jsonb_array_elements_text(v_result->'submission_ids')
      with ordinality as submission(submission_id, ordinal)
  ),
  replay_hash as (
    select hash, ordinal
    from unnest(v_hashes) with ordinality as replay_hash(hash, ordinal)
  )
  update public.match_result_submissions as submission
  set replay_content_hash = replay_hash.hash
  from linked_submission
  join replay_hash
    on replay_hash.ordinal = linked_submission.ordinal
  where submission.id = linked_submission.id;

  return v_result || jsonb_build_object('replay_hash_count', v_hash_count);
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_tournament_division_invitation_availability()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
begin
  if tg_table_name = 'tournaments' then
    perform public.reconcile_tournament_division_invitations(new.id, null, null);
  elsif tg_table_name = 'tournament_brackets' then
    perform public.reconcile_tournament_division_invitations(
      new.tournament_id,
      new.id,
      null
    );
  elsif tg_table_name = 'tournament_division_not_held_closures' then
    perform public.reconcile_tournament_division_invitations(
      null,
      new.tournament_bracket_id,
      null
    );
  elsif tg_table_name = 'registrations' then
    perform public.reconcile_tournament_division_invitations(
      new.tournament_id,
      null,
      new.profile_id
    );
  elsif tg_table_name = 'players' then
    if old.clerk_user_id is distinct from new.clerk_user_id then
      update public.tournament_division_invitations as invitation
      set created_by_clerk_user_id = new.clerk_user_id
      where invitation.created_by_clerk_user_id = old.clerk_user_id;
    end if;
    perform public.reconcile_tournament_division_invitations(
      null,
      null,
      new.id
    );
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_tournament_registration_enabled()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_has_open_unlaunched boolean;
begin
  select exists (
    select 1
    from public.tournament_brackets as bracket
    where bracket.tournament_id = new.id
      and bracket.launched_at is null
      and not exists (
        select 1
        from public.tournament_division_not_held_closures as closure
        where closure.tournament_bracket_id = bracket.id
      )
  )
  into v_has_open_unlaunched;

  if new.status = 'registration_open' then
    new.registration_enabled := v_has_open_unlaunched;
  elsif new.status = 'in_progress' and tg_op = 'UPDATE' then
    if v_has_open_unlaunched then
      new.registration_enabled := old.registration_enabled;
    else
      new.registration_enabled := false;
    end if;
  else
    new.registration_enabled := false;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.upsert_web_push_subscription(p_clerk_user_id text, p_endpoint text, p_p256dh text, p_auth text, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_clerk_user_id text := nullif(btrim(p_clerk_user_id), '');
  v_endpoint text := btrim(p_endpoint);
  v_existing public.push_subscriptions%rowtype;
  v_id uuid;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'Not authorized' using errcode = '42501';
  end if;

  if v_clerk_user_id is null
    or length(v_clerk_user_id) > 255
    or v_clerk_user_id ~ '[[:cntrl:]]' then
    raise exception 'Invalid subscription owner' using errcode = '22023';
  end if;

  if length(v_endpoint) not between 24 and 2048
    or v_endpoint ~ '[[:cntrl:][:space:]]'
    or v_endpoint !~* '^https://(fcm\.googleapis\.com|updates\.push\.services\.mozilla\.com|([a-z0-9]|[a-z0-9][a-z0-9-]{0,61}[a-z0-9])\.push\.apple\.com|([a-z0-9]|[a-z0-9][a-z0-9-]{0,61}[a-z0-9])\.notify\.windows\.com)/'
    or length(p_p256dh) not between 80 and 120
    or p_p256dh !~ '^[A-Za-z0-9_-]+$'
    or length(p_auth) not between 16 and 64
    or p_auth !~ '^[A-Za-z0-9_-]+$' then
    raise exception 'Invalid Push subscription' using errcode = '22023';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_clerk_user_id, 0)
  );

  delete from public.push_subscriptions as subscription
  where subscription.owner_clerk_user_id = v_clerk_user_id
    and subscription.expires_at is not null
    and subscription.expires_at <= pg_catalog.clock_timestamp();

  select subscription.*
  into v_existing
  from public.push_subscriptions as subscription
  where subscription.endpoint = v_endpoint
  for update;

  if found then
    if v_existing.owner_clerk_user_id <> v_clerk_user_id then
      raise exception 'Push endpoint is already owned'
        using errcode = '23505';
    end if;

    update public.push_subscriptions as subscription
    set
      p256dh = p_p256dh,
      auth = p_auth,
      expires_at = p_expires_at,
      updated_at = greatest(
        pg_catalog.clock_timestamp(),
        subscription.created_at
      )
    where subscription.id = v_existing.id
    returning subscription.id into v_id;

    return v_id;
  end if;

  if (
    select pg_catalog.count(*)
    from public.push_subscriptions as subscription
    where subscription.owner_clerk_user_id = v_clerk_user_id
  ) >= 10 then
    raise exception 'Push subscription limit reached'
      using errcode = '54000';
  end if;

  insert into public.push_subscriptions (
    owner_clerk_user_id,
    endpoint,
    p256dh,
    auth,
    expires_at
  ) values (
    v_clerk_user_id,
    v_endpoint,
    p_p256dh,
    p_auth,
    p_expires_at
  )
  returning id into v_id;

  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_match_result_report_group()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_match public.tournament_matches%rowtype;
  v_tournament_id uuid;
  v_submitter_clerk_user_id text;
  v_wins_required integer;
begin
  select match.*
  into v_match
  from public.tournament_matches as match
  where match.id = new.match_id;

  if not found then
    raise exception 'Tournament match not found';
  end if;

  select bracket.tournament_id
  into v_tournament_id
  from public.generated_brackets as generated
  join public.tournament_brackets as bracket
    on bracket.id = generated.tournament_bracket_id
  where generated.id = v_match.generated_bracket_id;

  if v_tournament_id is null or new.tournament_id <> v_tournament_id then
    raise exception 'Report group tournament does not match the match bracket';
  end if;

  if v_match.player_one_registration_id is null
    or v_match.player_two_registration_id is null then
    raise exception 'Both match participants must be assigned';
  end if;

  if new.submitted_by_registration_id not in (
    v_match.player_one_registration_id,
    v_match.player_two_registration_id
  ) then
    raise exception 'Submitting registration is not a participant in this match';
  end if;

  if new.opponent_registration_id not in (
    v_match.player_one_registration_id,
    v_match.player_two_registration_id
  ) then
    raise exception 'Opponent registration is not a participant in this match';
  end if;

  if new.winner_registration_id not in (
    v_match.player_one_registration_id,
    v_match.player_two_registration_id
  ) then
    raise exception 'Winner must be a participant in this match';
  end if;

  if new.result_type = 'no_show' then
    if new.no_show_reported_by_registration_id is distinct from
      new.submitted_by_registration_id then
      raise exception 'No-show reporter must match the submitting registration';
    end if;

    if new.no_show_registration_id is distinct from
      new.opponent_registration_id then
      raise exception 'No-show registration must be the opposing participant';
    end if;

    if new.no_show_registration_id = new.submitted_by_registration_id then
      raise exception 'A player cannot report themselves as a no-show';
    end if;

    if new.winner_registration_id is distinct from
      new.submitted_by_registration_id then
      raise exception 'No-show reporter must be the reported winner';
    end if;

    if new.no_show_status is null then
      raise exception 'No-show status is required';
    end if;
  else
    if new.no_show_reported_by_registration_id is not null
      or new.no_show_registration_id is not null
      or new.no_show_status is not null
      or new.no_show_note is not null
      or new.no_show_resolved_at is not null
      or new.no_show_resolved_by is not null then
      raise exception 'No-show fields are only valid for no-show reports';
    end if;
  end if;

  v_wins_required := (v_match.series_best_of / 2) + 1;

  if new.winner_registration_id = v_match.player_one_registration_id then
    if new.player_one_score <> v_wins_required
      or new.player_two_score >= v_wins_required then
      raise exception 'Report group score does not satisfy the match format';
    end if;
  else
    if new.player_two_score <> v_wins_required
      or new.player_one_score >= v_wins_required then
      raise exception 'Report group score does not satisfy the match format';
    end if;
  end if;

  select registration.clerk_user_id
  into v_submitter_clerk_user_id
  from public.registrations as registration
  where registration.id = new.submitted_by_registration_id;

  if v_submitter_clerk_user_id is distinct from
    new.submitted_by_clerk_user_id then
    raise exception
      'Submitting registration does not match the submitting account';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.withdraw_official_announcement(p_announcement_id uuid, p_actor_clerk_user_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_actor_clerk_user_id text := nullif(btrim(p_actor_clerk_user_id), '');
  v_announcement public.announcements%rowtype;
  v_withdrawn_at timestamptz;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'Announcement withdrawal is unavailable'
      using errcode = '42501';
  end if;

  if p_announcement_id is null or v_actor_clerk_user_id is null then
    raise exception 'Announcement withdrawal is unavailable'
      using errcode = '22023';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'ironclad:announcement-account:' || v_actor_clerk_user_id,
      0
    )
  );

  select announcement.*
  into v_announcement
  from public.announcements as announcement
  where announcement.id = p_announcement_id
  for update;

  if not found or v_announcement.withdrawn_at is not null then
    return pg_catalog.jsonb_build_object('withdrawn', false);
  end if;

  v_withdrawn_at := clock_timestamp();
  update public.announcements as announcement
  set
    withdrawn_at = v_withdrawn_at,
    withdrawn_by_clerk_user_id = v_actor_clerk_user_id
  where announcement.id = v_announcement.id;

  return pg_catalog.jsonb_build_object(
    'withdrawn', true,
    'withdrawn_at', v_withdrawn_at,
    'media_path', v_announcement.media_path
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.withdraw_tournament_registration(p_registration_id uuid)
 RETURNS TABLE(registration_id uuid, tournament_id uuid, tournament_bracket_id uuid, registration_status text, withdrawn_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_clerk_user_id text;
  v_tournament_bracket_id uuid;
  v_registration public.registrations%rowtype;
  v_launched_at timestamptz;
  v_withdrawn_at timestamptz;
begin
  if coalesce(auth.role(), '') <> 'authenticated' then
    raise exception 'Not authorized';
  end if;

  v_clerk_user_id := nullif(auth.jwt() ->> 'sub', '');
  if v_clerk_user_id is null then
    raise exception 'Not authorized';
  end if;

  select registration.tournament_bracket_id
  into v_tournament_bracket_id
  from public.registrations as registration
  where registration.id = p_registration_id
    and registration.clerk_user_id = v_clerk_user_id;

  if not found or v_tournament_bracket_id is null then
    raise exception 'Registration not found';
  end if;

  select bracket.launched_at
  into v_launched_at
  from public.tournament_brackets as bracket
  where bracket.id = v_tournament_bracket_id
  for update;

  select registration.*
  into v_registration
  from public.registrations as registration
  where registration.id = p_registration_id
    and registration.clerk_user_id = v_clerk_user_id
    and registration.tournament_bracket_id = v_tournament_bracket_id
  for update;

  if not found then
    raise exception 'Registration not found';
  end if;

  if v_launched_at is not null then
    raise exception 'Withdrawal is blocked because this division has launched';
  end if;

  if v_registration.registration_status not in (
    'pending',
    'manual_review',
    'approved',
    'waitlisted'
  ) then
    raise exception 'This registration cannot be withdrawn';
  end if;

  if v_registration.registration_status = 'waitlisted'
    and v_registration.waitlist_offer_status not in ('offered')
    and v_registration.waitlist_offer_status is not null then
    raise exception 'This waitlist registration is already resolved';
  end if;

  v_withdrawn_at := clock_timestamp();

  update public.registrations
  set
    registration_status = 'withdrawn',
    withdrawn_at = v_withdrawn_at,
    waitlist_offer_status = case
      when waitlist_offer_status = 'offered' then 'cancelled'
      else waitlist_offer_status
    end,
    waitlist_offer_resolved_at = case
      when waitlist_offer_status = 'offered' then v_withdrawn_at
      else waitlist_offer_resolved_at
    end
  where id = p_registration_id;

  registration_id := v_registration.id;
  tournament_id := v_registration.tournament_id;
  tournament_bracket_id := v_registration.tournament_bracket_id;
  registration_status := 'withdrawn';
  withdrawn_at := v_withdrawn_at;
  return next;
end;
$function$
